const EMBEDDED = {"/index.html":"<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover, user-scalable=no, interactive-widget=resizes-content\">\n<title>Buddymon Gold</title>\n<link rel=\"icon\" href=\"/icon-192.png\">\n<link rel=\"manifest\" href=\"/manifest.json\">\n<link rel=\"apple-touch-icon\" href=\"/icon-192.png\">\n<meta name=\"theme-color\" content=\"#0b1022\">\n<meta name=\"mobile-web-app-capable\" content=\"yes\">\n<meta name=\"apple-mobile-web-app-capable\" content=\"yes\">\n<meta name=\"apple-mobile-web-app-status-bar-style\" content=\"black-translucent\">\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link href=\"https://fonts.googleapis.com/css2?family=Fredoka:wght@400;500;600;700&family=Lilita+One&display=swap\" rel=\"stylesheet\">\n<link rel=\"stylesheet\" href=\"style.css\">\n</head>\n<body>\n<main>\n  <div id=\"stage\">\n    <div id=\"hd\"></div>\n    <div id=\"start\"><button id=\"play\">Play</button></div>\n  </div>\n\n  <div id=\"pad\" hidden>\n    <div id=\"dpad\" aria-label=\"Directional pad\"><i class=\"u\"></i><i class=\"d\"></i><i class=\"l\"></i><i class=\"r\"></i></div>\n    <div class=\"center\">\n      <button data-key=\"SELECT\">Select</button>\n      <button data-key=\"START\">Start</button>\n    </div>\n    <div class=\"ab\">\n      <button data-key=\"B\">B</button>\n      <button data-key=\"A\">A</button>\n    </div>\n  </div>\n\n  <section id=\"cloud\">\n    <span id=\"status\">Tap Play to start</span>\n    <button id=\"controls\" title=\"Controls: on-screen pad or screen gestures\">Pad</button>\n    <button id=\"install\" hidden title=\"Add the game to your home screen\">Install</button>\n    <button id=\"account-btn\" title=\"Account (optional): keep your game on any device\">Account</button>\n  </section>\n  <p class=\"hint\">Keys: arrows, Z = B, X = A, Enter = Start. Your game saves automatically.</p>\n</main>\n<dialog id=\"account\">\n  <form method=\"dialog\">\n    <h2>Account</h2>\n    <p id=\"account-note\">Optional. Make one to keep your game on any device.</p>\n    <div id=\"account-form\">\n      <input id=\"acct-user\" autocomplete=\"username\" autocapitalize=\"none\" spellcheck=\"false\" placeholder=\"Username\" maxlength=\"20\">\n      <input id=\"acct-pass\" type=\"password\" autocomplete=\"current-password\" placeholder=\"Password (6+ characters)\">\n      <div class=\"row\"><button type=\"button\" id=\"acct-login\">Sign in</button><button type=\"button\" id=\"acct-register\">Create account</button></div>\n    </div>\n    <div id=\"account-in\" hidden><button type=\"button\" id=\"acct-logout\">Sign out</button></div>\n    <p id=\"acct-msg\" role=\"status\"></p>\n    <button value=\"close\">Close</button>\n  </form>\n</dialog>\n<script src=\"app.js\"></script>\n</body>\n</html>\n","/app.js":"\"use strict\";\n/* page/hd/core/registry.js */\n// Registries the art/ and scenes/ files add to. Loaded first by bundle.js.\nconst INK = \"#0b1730\";\nconst Art = {};\nconst Scenes = {};\n\n/* page/hd/ui/actors.js */\n// The hero and other people drawn over a room or world, kept in step with game state.\n// box = { w, h, ox, oy }: art units across/down and the origin offset; cell (x, y) is 100 units.\nfunction actorLayer(wrap, box) {\n  const npcs = new Map();\n  const spawn = (cls) => {\n    const a = h(`<div class=\"actor ${cls}\"><div class=\"sprite\"></div><i class=\"emote\">!</i></div>`);\n    a.style.width = `${(104 / box.w) * 100}%`;\n    wrap.appendChild(a);\n    return a;\n  };\n  const person = (look) => (dir) => Art.person(dir, look);\n  const sync = (a, draw, x, y, dir) => {\n    if (a.dataset.dir !== String(dir)) { a.dataset.dir = dir; a.querySelector(\".sprite\").innerHTML = draw(dir); }\n    if (a.dataset.x !== String(x) || a.dataset.y !== String(y)) {\n      const first = a.dataset.x === undefined;\n      if (!first) a.walkUntil = performance.now() + 400;\n      else a.style.transition = \"none\"; // appear in place instead of gliding in from the corner\n      a.dataset.x = x; a.dataset.y = y;\n      a.style.zIndex = y * 2 + (a.classList.contains(\"hero\") ? 1 : 0); // whoever stands lower is drawn in front\n      a.style.left = `${((x * 100 + 50 + box.ox) / box.w) * 100}%`;\n      a.style.top = `${((y * 100 + 92 + box.oy) / box.h) * 100}%`;\n      if (first) { a.offsetWidth; a.style.transition = \"\"; }\n    }\n    a.classList.toggle(\"walk\", performance.now() < (a.walkUntil || 0));\n  };\n  const shout = (a, on) => a.classList.toggle(\"shout\", !!on);\n  const hero = spawn(\"hero\");\n  return {\n    hero,\n    update(state) {\n      sync(hero, person(Art.looks.HERO), state.x, state.y, state.dir);\n      const seen = new Set();\n      for (const o of state.objects) {\n        seen.add(o.id);\n        if (!npcs.has(o.id)) npcs.set(o.id, spawn(\"npc\"));\n        const a = npcs.get(o.id);\n        const name = o.name;\n        if (a.dataset.look !== String(name)) { a.dataset.look = name; delete a.dataset.dir; }\n        shout(a, o.emote);\n        sync(a, Art.props[name] || person(Art.looks[name] || Art.looks.OTHER), o.x, o.y, o.dir);\n      }\n      for (const [id, a] of npcs) if (!seen.has(id)) { a.remove(); npcs.delete(id); }\n    },\n  };\n}\n\n/* page/hd/ui/dialogue.js */\n// Bottom text box fed by state.dialogue (see core/engine.js).\nfunction dialogue(parent, tag) {\n  const el = h(`<div class=\"dlg\" hidden>${tag ? `<div class=\"dlg-tag\">${tag}</div>` : \"\"}<p class=\"l1\"></p><p class=\"l2\"></p><span class=\"more\">▼</span></div>`);\n  parent.appendChild(el);\n  return {\n    el,\n    setTag(t) { const tg = el.querySelector(\".dlg-tag\"); if (tg) tg.textContent = t; },\n    update(d) {\n      el.hidden = !d;\n      if (!d) { parent.style.setProperty(\"--dlg-h\", \"0px\"); return; }\n      // Native engine sends one paragraph (`text`) and lets it wrap; the ROM sends two fixed lines.\n      el.querySelector(\".l1\").textContent = d.text ?? d.lines[0];\n      el.querySelector(\".l2\").textContent = d.text ? \"\" : d.lines[1];\n      el.querySelector(\".more\").style.visibility = d.more ? \"visible\" : \"hidden\";\n      parent.style.setProperty(\"--dlg-h\", `${el.offsetHeight}px`); // menus anchor above the box, whatever its size\n    },\n  };\n}\n\n\n/* page/hd/ui/dom.js */\n// DOM helpers shared by scenes.\nfunction h(html) { const t = document.createElement(\"template\"); t.innerHTML = html.trim(); return t.content.firstChild; }\n\n// Night-sky backdrop used behind several scenes.\nfunction sky() { return h(`<div class=\"sky\">${Art.sky()}<i class=\"glow\"></i></div>`); }\n\n// Escape text that came from the player (nicknames) before it goes into markup.\nfunction esc(t) { return String(t).replace(/[&<>\"']/g, (c) => ({ \"&\": \"&amp;\", \"<\": \"&lt;\", \">\": \"&gt;\", '\"': \"&quot;\", \"'\": \"&#39;\" }[c])); }\nconst genderTag = (g) => (g === \"F\" ? '<span class=\"gender f\">♀</span>' : g === \"M\" ? '<span class=\"gender m\">♂</span>' : \"\");\n\n/* page/hd/ui/panel.js */\n// A full-height list screen over the current scene (state.panel, see game/menu/verbs.js): title, optional big picture, tabs,\n// text lines, selectable rows (with optional HP bar and little picture) and a Back button. Rows and Back answer taps through Game.pick.\nfunction panelLayer(parent) {\n  const el = h(`<div class=\"panel-ui\" hidden></div>`);\n  parent.appendChild(el);\n  let last = \"\";\n  el.addEventListener(\"pointerdown\", (e) => {\n    const row = e.target.closest(\"[data-i]\");\n    if (row) Game.pick(+row.dataset.i);\n    else if (e.target.closest(\".pn-back\")) Game.pick(-1);\n  });\n  const row = (r, n, sel) => `<li data-i=\"${n}\" class=\"${n === sel ? \"sel\" : \"\"} ${r.dim ? \"dim\" : \"\"}\">\n    ${r.art ? `<span class=\"pn-art\">${Art.creature(r.art)}</span>` : \"\"}\n    <span class=\"pn-main\"><b>${esc(r.label)}${genderTag(r.g)}</b>${r.sub ? `<small>${esc(r.sub)}</small>` : \"\"}${r.bar !== undefined ? `<i class=\"pn-bar\"><i data-level=\"${r.bar > 0.5 ? \"ok\" : r.bar > 0.2 ? \"warn\" : \"low\"}\" style=\"width:${Math.round(r.bar * 100)}%\"></i></i>` : \"\"}</span>\n    ${r.right ? `<em>${esc(r.right)}</em>` : \"\"}</li>`;\n  return {\n    update(p) {\n      const key = JSON.stringify(p);\n      if (key === last) return;\n      last = key;\n      el.hidden = !p;\n      if (!p) { el.innerHTML = \"\"; return; }\n      el.innerHTML = `<h2>${esc(p.title)}${genderTag(p.g)}</h2>\n        ${p.art ? `<div class=\"pn-hero\">${Art.creature(p.art)}</div>` : \"\"}\n        ${p.tabs ? `<div class=\"pn-tabs\">${p.tabs.map((t) => `<span class=\"${t.sel ? \"sel\" : \"\"}\">${t.label}</span>`).join(\"\")}</div>` : \"\"}\n        ${(p.lines || []).map((l) => `<p class=\"pn-line\">${l}</p>`).join(\"\")}\n        <ul>${p.rows.map((r, n) => row(r, n, p.sel)).join(\"\")}</ul>\n        ${p.hint ? `<p class=\"pn-hint\">${p.hint}</p>` : \"\"}\n        <button class=\"pn-back\">Back</button>`;\n      const selected = el.querySelector(\"li.sel\");\n      if (selected) selected.scrollIntoView({ block: \"nearest\" });\n    },\n  };\n}\n\n/* page/hd/ui/pic.js */\n// The big buddymon picture shown while the game introduces one (state.pic = species name), like Gold's pokepic.\nfunction picLayer(parent) {\n  const el = h(`<div class=\"pic\" hidden></div>`);\n  parent.appendChild(el);\n  let shown = null;\n  return {\n    update(species) {\n      if (species === shown) return;\n      shown = species;\n      el.hidden = !species;\n      el.innerHTML = species ? `<div class=\"pic-art\">${Art.creature(species)}</div><div class=\"pic-name\">${species.toUpperCase()}</div>` : \"\";\n    },\n  };\n}\n\n/* page/hd/ui/popup.js */\n// List boxes (Start menu, Yes/No, submenus) drawn over a scene from state.boxes; tap a row to answer.\n// b.pos \"low\" puts a box just over the message box, \"top\" at the top of the screen.\nfunction popups(parent) {\n  const el = h(`<div class=\"popups\"></div>`);\n  parent.appendChild(el);\n  el.addEventListener(\"pointerdown\", (e) => { const li = e.target.closest(\"li\"); if (li) Game.pick(+li.dataset.i); }); // tap a row\n  let last = \"\";\n  return {\n    update(boxes) {\n      const key = JSON.stringify(boxes);\n      if (key === last) return;\n      last = key;\n      el.innerHTML = boxes.map((b) => {\n        const low = b.pos === \"low\", right = b.c0 >= 7;\n        return `<ul class=\"popup ${low ? \"low\" : \"top\"} ${right ? \"right\" : \"left\"}\">${b.rows.map((r, n) =>\n          `<li data-i=\"${n}\" class=\"${r.selected ? \"sel\" : \"\"}\">${esc(r.text)}</li>`).join(\"\")}</ul>`;\n      }).join(\"\");\n    },\n  };\n}\n\n/* page/hd/art/_eye.js */\n// Shared eye: white sclera, coloured iris, ink pupil, two glints.\nArt.eye = function (cx, cy, r, iris = \"#e04a4a\") {\n  return `<g><ellipse cx=\"${cx}\" cy=\"${cy}\" rx=\"${r}\" ry=\"${r * 1.12}\" fill=\"#fff\" stroke=\"${INK}\" stroke-width=\"3.5\"/>\n    <ellipse cx=\"${cx + r * 0.08}\" cy=\"${cy + r * 0.1}\" rx=\"${r * 0.68}\" ry=\"${r * 0.78}\" fill=\"${iris}\"/>\n    <ellipse cx=\"${cx + r * 0.1}\" cy=\"${cy + r * 0.12}\" rx=\"${r * 0.36}\" ry=\"${r * 0.42}\" fill=\"${INK}\"/>\n    <circle cx=\"${cx - r * 0.22}\" cy=\"${cy - r * 0.3}\" r=\"${r * 0.22}\" fill=\"#fff\"/>\n    <circle cx=\"${cx + r * 0.3}\" cy=\"${cy + r * 0.28}\" r=\"${r * 0.1}\" fill=\"#fff\"/></g>`;\n};\n\n/* page/hd/art/badger.js */\n// Brock Family emblem: a badger (brock = badger) in a gold-ringed crest.\nArt.badger = function () {\n  return `<svg viewBox=\"0 0 200 200\" xmlns=\"http://www.w3.org/2000/svg\">\n<defs>\n  <radialGradient id=\"bg-crest\" cx=\".5\" cy=\".4\" r=\".7\"><stop offset=\"0\" stop-color=\"#2b4ea8\"/><stop offset=\"1\" stop-color=\"#10204f\"/></radialGradient>\n  <linearGradient id=\"bg-ring\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"1\"><stop offset=\"0\" stop-color=\"#fff3a8\"/><stop offset=\".5\" stop-color=\"#ffc93c\"/><stop offset=\"1\" stop-color=\"#f08a14\"/></linearGradient>\n</defs>\n<g stroke=\"${INK}\" stroke-width=\"6\" stroke-linejoin=\"round\" stroke-linecap=\"round\">\n  <circle cx=\"100\" cy=\"100\" r=\"94\" fill=\"url(#bg-ring)\"/>\n  <circle cx=\"100\" cy=\"100\" r=\"80\" fill=\"url(#bg-crest)\"/>\n  <circle cx=\"64\" cy=\"58\" r=\"17\" fill=\"#3a3f52\"/><circle cx=\"136\" cy=\"58\" r=\"17\" fill=\"#3a3f52\"/>\n  <circle cx=\"64\" cy=\"58\" r=\"7\" fill=\"#f6f2e4\" stroke=\"none\"/><circle cx=\"136\" cy=\"58\" r=\"7\" fill=\"#f6f2e4\" stroke=\"none\"/>\n  <ellipse cx=\"100\" cy=\"108\" rx=\"52\" ry=\"46\" fill=\"#3a3f52\"/>\n  <path fill=\"#f6f2e4\" d=\"M100 62 C86 64 80 80 84 100 L94 152 L106 152 L116 100 C120 80 114 64 100 62 Z\"/>\n  <ellipse cx=\"66\" cy=\"124\" rx=\"15\" ry=\"13\" fill=\"#f6f2e4\"/><ellipse cx=\"134\" cy=\"124\" rx=\"15\" ry=\"13\" fill=\"#f6f2e4\"/>\n</g>\n${Art.eye(77, 102, 9, \"#caa23a\")}${Art.eye(123, 102, 9, \"#caa23a\")}\n<ellipse cx=\"100\" cy=\"142\" rx=\"11\" ry=\"8\" fill=\"${INK}\"/><circle cx=\"96\" cy=\"139\" r=\"2.6\" fill=\"#fff\"/>\n<path d=\"M88 152 Q100 162 112 152\" fill=\"none\" stroke=\"${INK}\" stroke-width=\"4\" stroke-linecap=\"round\"/>\n<path d=\"M46 36 L50 28 L56 36 M144 36 L150 28 L154 36\" fill=\"none\" stroke=\"#fff6dc\" stroke-width=\"4\" stroke-linecap=\"round\" opacity=\".8\"/>\n</svg>`;\n};\n\n/* page/hd/art/bandit.js */\n// BANDIT: the tuxedo cat (dark starter), drawn from the author's cat: black coat, white muzzle, chest and paws, amber-green eyes.\nArt.bandit = function () {\n  return `<svg viewBox=\"0 0 200 200\" xmlns=\"http://www.w3.org/2000/svg\">\n<defs>\n<linearGradient id=\"bn-fur\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0\" stop-color=\"#3a3f55\"/><stop offset=\"1\" stop-color=\"#171a26\"/></linearGradient>\n<linearGradient id=\"bn-white\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0\" stop-color=\"#ffffff\"/><stop offset=\"1\" stop-color=\"#dfe5f2\"/></linearGradient>\n</defs>\n<ellipse cx=\"100\" cy=\"186\" rx=\"58\" ry=\"8\" fill=\"#000\" opacity=\".22\"/>\n<g stroke=\"${INK}\" stroke-width=\"5\" stroke-linejoin=\"round\" stroke-linecap=\"round\">\n<path fill=\"url(#bn-fur)\" d=\"M136 172 C200 174 204 112 172 90 C178 126 162 146 140 148 Z\"/>\n<ellipse cx=\"72\" cy=\"178\" rx=\"19\" ry=\"11\" fill=\"url(#bn-white)\"/>\n<ellipse cx=\"128\" cy=\"178\" rx=\"19\" ry=\"11\" fill=\"url(#bn-white)\"/>\n<ellipse cx=\"100\" cy=\"142\" rx=\"42\" ry=\"37\" fill=\"url(#bn-fur)\"/>\n<path fill=\"url(#bn-white)\" d=\"M68 128 C78 116 122 116 132 128 C138 158 62 158 68 128 Z\"/>\n<path fill=\"url(#bn-fur)\" d=\"M44 76 L46 12 L88 54 Z\"/><path fill=\"#e8a5b4\" stroke=\"none\" d=\"M54 62 L55 32 L74 54 Z\"/>\n<path fill=\"url(#bn-fur)\" d=\"M156 76 L154 12 L112 54 Z\"/><path fill=\"#e8a5b4\" stroke=\"none\" d=\"M146 62 L145 32 L126 54 Z\"/>\n<path fill=\"url(#bn-fur)\" d=\"M40 96 C36 66 66 48 100 48 C134 48 164 66 160 96 C158 120 130 136 100 136 C70 136 42 120 40 96 Z\"/>\n<path fill=\"url(#bn-white)\" d=\"M44 106 L34 114 L46 116 L38 126 L54 122 C60 136 80 142 100 142 C120 142 140 136 146 122 L162 126 L154 116 L166 114 L156 106 C148 98 132 100 100 106 C68 100 52 98 44 106 Z\"/>\n<path fill=\"${INK}\" stroke=\"none\" d=\"M86 102 L114 102 L108 120 L100 126 L92 120 Z\"/>\n</g>\n<path d=\"M100 54 L100 80\" stroke=\"#fff\" stroke-width=\"5\" stroke-linecap=\"round\" opacity=\".8\"/>\n<g fill=\"none\" stroke=\"#fff\" stroke-width=\"3\" stroke-linecap=\"round\"><path d=\"M54 112 L22 104 M54 120 L24 124 M146 112 L178 104 M146 120 L176 124\"/></g>\n<ellipse cx=\"100\" cy=\"106\" rx=\"7\" ry=\"4\" fill=\"#5a5f78\"/>\n${this.eye(74, 92, 12, \"#d6b52a\")}${this.eye(126, 92, 12, \"#d6b52a\")}\n<path d=\"M58 80 Q74 78 90 86 M142 80 Q126 78 110 86\" fill=\"none\" stroke=\"${INK}\" stroke-width=\"6\" stroke-linecap=\"round\"/>\n<path d=\"M100 126 L100 132 M90 134 Q100 140 110 134\" fill=\"none\" stroke=\"${INK}\" stroke-width=\"4\" stroke-linecap=\"round\"/>\n</svg>`;\n};\n\n/* page/hd/art/bramblet.js */\n// BRAMBLET: leaf-spined hedgehog (grass starter)\nArt.bramblet = function () {\n  return `<svg viewBox=\"0 0 200 200\" xmlns=\"http://www.w3.org/2000/svg\">\n<defs>\n<linearGradient id=\"bb-leaf\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0\" stop-color=\"#58d684\"/><stop offset=\"1\" stop-color=\"#1f8f4e\"/></linearGradient>\n<linearGradient id=\"bb-fur\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0\" stop-color=\"#ffd9a0\"/><stop offset=\"1\" stop-color=\"#eeb06b\"/></linearGradient>\n</defs>\n<ellipse cx=\"100\" cy=\"184\" rx=\"58\" ry=\"9\" fill=\"#000\" opacity=\".22\"/>\n<g stroke=\"${INK}\" stroke-width=\"5\" stroke-linejoin=\"round\" stroke-linecap=\"round\">\n<path fill=\"url(#bb-leaf)\" d=\"M22 130 C10 100 20 66 46 50 L50 78 L58 30 L82 62 L100 14 L118 62 L142 30 L150 78 L154 50 C180 66 190 100 178 130 C160 150 40 150 22 130 Z\"/>\n<path fill=\"#7be8a0\" stroke-width=\"3\" d=\"M58 30 L66 70 L74 56 Z M100 14 L96 62 L108 62 Z M142 30 L126 56 L134 70 Z\"/>\n<ellipse cx=\"68\" cy=\"172\" rx=\"20\" ry=\"12\" fill=\"url(#bb-fur)\"/>\n<ellipse cx=\"132\" cy=\"172\" rx=\"20\" ry=\"12\" fill=\"url(#bb-fur)\"/>\n<ellipse cx=\"100\" cy=\"138\" rx=\"46\" ry=\"38\" fill=\"url(#bb-fur)\"/>\n<ellipse cx=\"100\" cy=\"148\" rx=\"26\" ry=\"22\" fill=\"#fff4d6\" stroke=\"none\"/>\n<circle cx=\"58\" cy=\"76\" r=\"14\" fill=\"url(#bb-fur)\"/><circle cx=\"58\" cy=\"76\" r=\"7\" fill=\"#ff9aa8\" stroke=\"none\"/>\n<circle cx=\"142\" cy=\"76\" r=\"14\" fill=\"url(#bb-fur)\"/><circle cx=\"142\" cy=\"76\" r=\"7\" fill=\"#ff9aa8\" stroke=\"none\"/>\n<ellipse cx=\"100\" cy=\"100\" rx=\"50\" ry=\"42\" fill=\"url(#bb-fur)\"/>\n</g>\n<path d=\"M74 66 Q100 52 126 66\" fill=\"none\" stroke=\"#fff\" stroke-width=\"4\" stroke-linecap=\"round\" opacity=\".55\"/>\n${this.eye(78, 98, 12, \"#2e9e55\")}${this.eye(122, 98, 12, \"#2e9e55\")}\n<ellipse cx=\"100\" cy=\"114\" rx=\"8\" ry=\"6\" fill=\"${INK}\"/>\n<path d=\"M92 124 Q100 132 108 124\" fill=\"none\" stroke=\"${INK}\" stroke-width=\"4\" stroke-linecap=\"round\"/>\n<circle cx=\"64\" cy=\"116\" r=\"8\" fill=\"#ff8c9e\" opacity=\".7\"/><circle cx=\"136\" cy=\"116\" r=\"8\" fill=\"#ff8c9e\" opacity=\".7\"/>\n</svg>`;\n};\n\n/* page/hd/art/buildings.js */\n// A building for the world scene, w x h cells (100 units each) drawn at (x, y): roof on top, wall below with windows, door on the bottom row.\n// opts: roof, wall colours; label for a shop-style plaque; door = column of the door (0-based, bottom row).\nArt.building = function (b) {\n  const o = `stroke=\"${INK}\" stroke-width=\"5\" stroke-linejoin=\"round\" stroke-linecap=\"round\"`;\n  const W = b.w * 100, H = b.h * 100, roofH = Math.min(150, H * 0.5), wallY = roofH - 10;\n  const roof = b.roof || \"#d9604c\", wall = b.wall || \"#fff1d0\";\n  const planks = Array.from({ length: Math.floor(roofH / 25) }, (_, i) => `<path d=\"M0 ${(i + 1) * 25} H${W}\" stroke=\"rgba(0,0,0,.18)\" stroke-width=\"3\"/>`).join(\"\");\n  const wins = Array.from({ length: b.w }, (_, i) => (i === b.door ? \"\" : `<rect x=\"${i * 100 + 20}\" y=\"${wallY + 24}\" width=\"60\" height=\"${Math.min(52, H - wallY - 70)}\" rx=\"6\" fill=\"#8fd3ff\" ${o}/>`)).join(\"\");\n  const dx = b.door * 100;\n  return `<g transform=\"translate(${b.x * 100} ${b.y * 100})\">\n    <ellipse cx=\"${W / 2}\" cy=\"${H + 4}\" rx=\"${W / 2 + 6}\" ry=\"12\" fill=\"#000\" opacity=\".2\"/>\n    <rect y=\"${wallY}\" width=\"${W}\" height=\"${H - wallY}\" fill=\"${wall}\" ${o}/>\n    <rect y=\"${H - 14}\" width=\"${W}\" height=\"14\" fill=\"#c9a46a\" ${o} stroke-width=\"3\"/>${wins}\n    <path d=\"M-12 ${roofH} L${W * 0.12} 0 H${W * 0.88} L${W + 12} ${roofH} Z\" fill=\"${roof}\" ${o}/>\n    <g clip-path=\"inset(0)\">${planks}</g>\n    <rect x=\"${dx + 18}\" y=\"${H - 96}\" width=\"64\" height=\"96\" rx=\"8\" fill=\"#9a6a3a\" ${o}/><circle cx=\"${dx + 68}\" cy=\"${H - 46}\" r=\"5\" fill=\"#ffc93c\"/>\n    ${b.label ? `<rect x=\"${W / 2 - 60}\" y=\"${roofH - 38}\" width=\"120\" height=\"34\" rx=\"8\" fill=\"#3a56b0\" ${o}/><text x=\"${W / 2}\" y=\"${roofH - 13}\" text-anchor=\"middle\" font-family=\"'Lilita One','Fredoka',sans-serif\" font-size=\"24\" fill=\"#fff\">${b.label}</text>` : \"\"}\n  </g>`;\n};\n\n/* page/hd/art/cherrygroveMart.js */\n// Cherrygrove Mart, 12 x 8 cells: shelves (0..11,0..1), counter (0..2,4) with the clerk behind at (1,3), door (2..3,7).\nArt.cherrygroveMart = function () {\n  const f = Art.furniture;\n  return Art.shell(12, 8, \"house\") + f.window(100) + f.shelf(300, 40, 900, 160) +\n    f.counter(0, 400, 300, 90) + f.rug(700, 560, 260, 80) + f.mat(200, 700, 200) + Art.roomEnd;\n};\n\n/* page/hd/art/chirplet.js */\n// CHIRPLET (was Pidgey): fluffy chick-bird with a three-feather crest.\nArt.chirplet = function () {\n  return `<svg viewBox=\"0 0 200 200\" xmlns=\"http://www.w3.org/2000/svg\">\n<defs><linearGradient id=\"cp-b\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0\" stop-color=\"#ffe08a\"/><stop offset=\"1\" stop-color=\"#f6b64a\"/></linearGradient>\n<linearGradient id=\"cp-w\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0\" stop-color=\"#f6a03c\"/><stop offset=\"1\" stop-color=\"#d9742a\"/></linearGradient></defs>\n<ellipse cx=\"100\" cy=\"186\" rx=\"54\" ry=\"8\" fill=\"#000\" opacity=\".22\"/>\n<g stroke=\"${INK}\" stroke-width=\"5\" stroke-linejoin=\"round\" stroke-linecap=\"round\">\n  <path fill=\"url(#cp-w)\" d=\"M140 150 L186 138 L170 160 L190 176 L146 172Z\"/>\n  <path d=\"M78 176 V190 M70 190 H88 M122 176 V190 M114 190 H132\" fill=\"none\" stroke=\"#e8842a\" stroke-width=\"6\"/>\n  <ellipse cx=\"100\" cy=\"128\" rx=\"58\" ry=\"52\" fill=\"url(#cp-b)\"/>\n  <ellipse cx=\"100\" cy=\"148\" rx=\"34\" ry=\"28\" fill=\"#fff6dc\" stroke=\"none\"/>\n  <path fill=\"url(#cp-w)\" d=\"M40 112 C20 124 22 160 50 164 C60 150 58 126 40 112Z\"/>\n  <path fill=\"url(#cp-w)\" d=\"M160 112 C180 124 178 160 150 164 C140 150 142 126 160 112Z\"/>\n  <path fill=\"#f6a03c\" d=\"M84 50 L80 20 L98 42 L104 14 L116 42 L130 22 L122 54Z\"/>\n  <path fill=\"#ff8a3a\" d=\"M88 98 L112 98 L100 116Z\"/>\n</g>\n${Art.eye(74, 88, 11, \"#4a3a1a\")}${Art.eye(126, 88, 11, \"#4a3a1a\")}\n<circle cx=\"56\" cy=\"108\" r=\"8\" fill=\"#ff8c9e\" opacity=\".6\"/><circle cx=\"144\" cy=\"108\" r=\"8\" fill=\"#ff8c9e\" opacity=\".6\"/>\n</svg>`;\n};\n\n/* page/hd/art/chomplet.js */\n// CHOMPLET: shark pup (water starter), after the supplied reference style\nArt.chomplet = function () {\n  return `<svg viewBox=\"0 0 200 200\" xmlns=\"http://www.w3.org/2000/svg\">\n<defs>\n<linearGradient id=\"ch-body\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0\" stop-color=\"#4fb6d9\"/><stop offset=\"1\" stop-color=\"#2a6fa8\"/></linearGradient>\n<linearGradient id=\"ch-mouth\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0\" stop-color=\"#d63a4a\"/><stop offset=\"1\" stop-color=\"#8f1f36\"/></linearGradient>\n</defs>\n<ellipse cx=\"100\" cy=\"188\" rx=\"58\" ry=\"8\" fill=\"#000\" opacity=\".22\"/>\n<g stroke=\"${INK}\" stroke-width=\"5\" stroke-linejoin=\"round\" stroke-linecap=\"round\">\n<path fill=\"url(#ch-body)\" d=\"M104 10 C132 24 140 46 140 66 L66 66 C84 52 100 34 104 10 Z\"/>\n<path fill=\"url(#ch-body)\" d=\"M26 150 C22 100 52 66 100 66 C148 66 178 100 174 150 C170 176 140 188 100 188 C60 188 30 176 26 150 Z\"/>\n<path fill=\"#ffe08a\" stroke=\"none\" d=\"M44 160 C60 178 140 178 156 160 C150 186 50 186 44 160 Z\"/>\n<path fill=\"url(#ch-body)\" d=\"M30 140 L8 156 L30 166 Z\"/><path fill=\"url(#ch-body)\" d=\"M170 140 L192 156 L170 166 Z\"/>\n<path fill=\"url(#ch-mouth)\" d=\"M44 112 C66 130 134 130 156 112 C160 146 134 172 100 172 C66 172 40 146 44 112 Z\"/>\n</g>\n<g fill=\"#fff\" stroke=\"${INK}\" stroke-width=\"3\" stroke-linejoin=\"round\">\n<path d=\"M50 114 L62 132 L72 118 Z\"/><path d=\"M76 120 L88 138 L98 124 Z\"/><path d=\"M102 124 L112 138 L124 120 Z\"/><path d=\"M128 118 L138 132 L150 114 Z\"/>\n</g>\n<path d=\"M82 160 C90 148 110 148 118 160 C112 170 88 170 82 160 Z\" fill=\"#ff8da1\" stroke=\"${INK}\" stroke-width=\"4\"/>\n<path d=\"M66 92 L90 86\" stroke=\"${INK}\" stroke-width=\"6\" stroke-linecap=\"round\"/><path d=\"M134 92 L110 86\" stroke=\"${INK}\" stroke-width=\"6\" stroke-linecap=\"round\"/>\n${this.eye(72, 100, 12, \"#e04a4a\")}${this.eye(128, 100, 12, \"#e04a4a\")}\n<path d=\"M84 52 C92 40 98 30 100 22\" fill=\"none\" stroke=\"#bfeaff\" stroke-width=\"5\" stroke-linecap=\"round\" opacity=\".7\"/>\n</svg>`;\n};\n\n/* page/hd/art/creature.js */\n// Art for a species key (\"bramblet\"): hand-drawn where we have art/<key>.js, otherwise a seeded placeholder (art/critter.js).\nArt.creature = (key) => (Art[key] ? Art[key]() : Art.critter([...key].reduce((n, ch) => (n * 31 + ch.charCodeAt(0)) >>> 0, 7)));\n\n/* page/hd/art/critter.js */\n// Procedural placeholder creature for any species without hand-drawn art (Art.creature falls back here).\n// Seeded by the species id, so a species always looks the same: hue, body, ears, tail and markings vary.\nArt.critter = function (id) {\n  let seed = (id * 9301 + 49297) % 233280;\n  const rnd = () => ((seed = (seed * 9301 + 49297) % 233280) / 233280);\n  const pick = (list) => list[Math.floor(rnd() * list.length)];\n  const hue = Math.floor(rnd() * 360);\n  const hsl = (dh, s, l) => `hsl(${(hue + dh) % 360} ${s}% ${l}%)`;\n  const body = hsl(0, 62, 58), dark = hsl(0, 60, 40), light = hsl(0, 70, 82), accent = hsl(150, 70, 58);\n  const ears = pick([\"round\", \"point\", \"long\", \"horn\", \"none\"]);\n  const tail = pick([\"curl\", \"fluff\", \"spike\", \"none\"]);\n  const mark = pick([\"belly\", \"stripes\", \"spots\", \"none\"]);\n  const eyeR = 10 + Math.floor(rnd() * 4), iris = hsl(180, 60, 40);\n  const rx = 52 + Math.floor(rnd() * 14), ry = 46 + Math.floor(rnd() * 12);\n  const o = `stroke=\"${INK}\" stroke-width=\"5\" stroke-linejoin=\"round\" stroke-linecap=\"round\"`;\n\n  const earSvg = {\n    round: `<circle cx=\"${100 - rx + 8}\" cy=\"62\" r=\"16\" fill=\"${body}\" ${o}/><circle cx=\"${100 + rx - 8}\" cy=\"62\" r=\"16\" fill=\"${body}\" ${o}/>`,\n    point: `<path d=\"M${100 - rx + 4} 74 L${100 - rx + 6} 28 L${100 - 14} 56Z M${100 + rx - 4} 74 L${100 + rx - 6} 28 L${100 + 14} 56Z\" fill=\"${body}\" ${o}/>`,\n    long: `<ellipse cx=\"${100 - 34}\" cy=\"34\" rx=\"12\" ry=\"34\" fill=\"${body}\" ${o}/><ellipse cx=\"${100 + 34}\" cy=\"34\" rx=\"12\" ry=\"34\" fill=\"${body}\" ${o}/>`,\n    horn: `<path d=\"M${100 - 30} 62 L${100 - 38} 24 L${100 - 14} 56Z M${100 + 30} 62 L${100 + 38} 24 L${100 + 14} 56Z\" fill=\"${accent}\" ${o}/>`,\n    none: \"\",\n  }[ears];\n  const tailSvg = {\n    curl: `<path d=\"M140 156 C190 160 196 108 164 100 C176 124 160 134 142 134Z\" fill=\"${body}\" ${o}/>`,\n    fluff: `<ellipse cx=\"170\" cy=\"140\" rx=\"24\" ry=\"34\" fill=\"${light}\" ${o} transform=\"rotate(25 170 140)\"/>`,\n    spike: `<path d=\"M136 160 L190 146 L150 130Z\" fill=\"${accent}\" ${o}/>`,\n    none: \"\",\n  }[tail];\n  const markSvg = {\n    belly: `<ellipse cx=\"100\" cy=\"152\" rx=\"26\" ry=\"22\" fill=\"${light}\"/>`,\n    stripes: `<path d=\"M62 84 L84 90 M138 84 L116 90 M60 108 L82 112 M140 108 L118 112\" stroke=\"${dark}\" stroke-width=\"7\" stroke-linecap=\"round\"/>`,\n    spots: `<circle cx=\"70\" cy=\"132\" r=\"9\" fill=\"${dark}\" opacity=\".6\"/><circle cx=\"132\" cy=\"128\" r=\"7\" fill=\"${dark}\" opacity=\".6\"/><circle cx=\"104\" cy=\"150\" r=\"6\" fill=\"${dark}\" opacity=\".6\"/>`,\n    none: \"\",\n  }[mark];\n\n  return `<svg viewBox=\"0 0 200 200\" xmlns=\"http://www.w3.org/2000/svg\">\n<ellipse cx=\"100\" cy=\"186\" rx=\"58\" ry=\"9\" fill=\"#000\" opacity=\".22\"/>\n${tailSvg}\n<ellipse cx=\"70\" cy=\"174\" rx=\"20\" ry=\"11\" fill=\"${body}\" ${o}/><ellipse cx=\"130\" cy=\"174\" rx=\"20\" ry=\"11\" fill=\"${body}\" ${o}/>\n<ellipse cx=\"100\" cy=\"144\" rx=\"${rx - 14}\" ry=\"36\" fill=\"${body}\" ${o}/>${markSvg}\n${earSvg}\n<ellipse cx=\"100\" cy=\"100\" rx=\"${rx}\" ry=\"${ry}\" fill=\"${body}\" ${o}/>\n<path d=\"M${100 - rx + 18} 70 Q100 44 ${100 + rx - 18} 70\" fill=\"none\" stroke=\"#fff\" stroke-width=\"4\" stroke-linecap=\"round\" opacity=\".5\"/>\n${Art.eye(76, 98, eyeR, iris)}${Art.eye(124, 98, eyeR, iris)}\n<ellipse cx=\"100\" cy=\"116\" rx=\"7\" ry=\"5\" fill=\"${INK}\"/><path d=\"M92 126 Q100 134 108 126\" fill=\"none\" stroke=\"${INK}\" stroke-width=\"4\" stroke-linecap=\"round\"/>\n<circle cx=\"58\" cy=\"118\" r=\"8\" fill=\"#ff8c9e\" opacity=\".6\"/><circle cx=\"142\" cy=\"118\" r=\"8\" fill=\"#ff8c9e\" opacity=\".6\"/>\n</svg>`;\n};\n\n/* page/hd/art/furniture.js */\n// Shared room pieces. All coordinates are art units (cell = 100); pieces draw at (x, y) = top-left.\n// Art.shell(cols, rows, theme) is the empty room; rooms add pieces after it and close with Art.roomEnd.\nArt.shell = function (cols, rows, theme) {\n  const W = cols * 100, H = rows * 100;\n  const t = theme === \"lab\"\n    ? { floorA: \"#e6edf7\", floorB: \"#cfd9ea\", wallA: \"#9fd0e6\", wallB: \"#6fb3d4\" }\n    : { floorA: \"#f0be78\", floorB: \"#d99a54\", wallA: \"#ffd9a0\", wallB: \"#f2b872\" };\n  const lines = theme === \"lab\"\n    ? Array.from({ length: cols }, (_, i) => `<path d=\"M${i * 100} 110 V${H}\" stroke=\"#b5c3dc\" stroke-width=\"2\"/>`).join(\"\") +\n      Array.from({ length: rows }, (_, i) => `<path d=\"M0 ${i * 100 + 110} H${W}\" stroke=\"#b5c3dc\" stroke-width=\"2\"/>`).join(\"\")\n    : Array.from({ length: Math.floor(H / 40) }, (_, i) => `<path d=\"M0 ${110 + i * 40} H${W}\" stroke=\"#c98d4a\" stroke-width=\"2\" opacity=\".45\"/>`).join(\"\");\n  return `<svg class=\"room-svg\" viewBox=\"-20 -20 ${W + 40} ${H + 40}\" xmlns=\"http://www.w3.org/2000/svg\">\n<defs><linearGradient id=\"sh-f\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0\" stop-color=\"${t.floorA}\"/><stop offset=\"1\" stop-color=\"${t.floorB}\"/></linearGradient>\n<linearGradient id=\"sh-w\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0\" stop-color=\"${t.wallA}\"/><stop offset=\"1\" stop-color=\"${t.wallB}\"/></linearGradient></defs>\n<rect width=\"${W}\" height=\"${H}\" rx=\"10\" fill=\"url(#sh-f)\"/>${lines}\n<rect width=\"${W}\" height=\"110\" fill=\"url(#sh-w)\"/><rect y=\"96\" width=\"${W}\" height=\"16\" fill=\"#fff6dc\" stroke=\"${INK}\" stroke-width=\"5\"/>\n<rect x=\"-6\" y=\"-6\" width=\"${W + 12}\" height=\"${H + 12}\" rx=\"12\" fill=\"none\" stroke=\"${INK}\" stroke-width=\"12\"/>`;\n};\nArt.roomEnd = \"</svg>\";\n\nArt.furniture = (() => {\n  const o = `stroke=\"${INK}\" stroke-width=\"5\" stroke-linejoin=\"round\" stroke-linecap=\"round\"`;\n  return {\n    window: (x) => `<g ${o}><rect x=\"${x + 10}\" y=\"14\" width=\"80\" height=\"74\" rx=\"6\" fill=\"#8fd3ff\"/><path d=\"M${x + 50} 14 V88 M${x + 10} 51 H${x + 90}\" stroke-width=\"5\"/></g>`,\n    shelf: (x, y, w, h = 150) => {\n      const books = [\"#e04a4a\", \"#46c26f\", \"#ffc93c\", \"#4fb6d9\", \"#ff9aa8\", \"#6f86d6\"];\n      let inner = \"\";\n      for (let i = 0; i < Math.floor(w / 100); i++) for (let r = 0; r < 2; r++) for (let b = 0; b < 4; b++)\n        inner += `<rect x=\"${x + i * 100 + 12 + b * 20}\" y=\"${y + 14 + r * (h / 2 - 8) + (b % 2) * 4}\" width=\"15\" height=\"${h / 2 - 34}\" fill=\"${books[(i + r + b) % 6]}\" stroke-width=\"3\" ${o}/>`;\n      return `<g ${o}><rect x=\"${x}\" y=\"${y}\" width=\"${w}\" height=\"${h}\" rx=\"8\" fill=\"#b8763a\"/><rect x=\"${x + 8}\" y=\"${y + 8}\" width=\"${w - 16}\" height=\"${h - 16}\" fill=\"#7a4a1e\" stroke=\"none\"/>${inner}</g>`;\n    },\n    tv: (x, y) => `<g ${o}><rect x=\"${x + 6}\" y=\"${y + 8}\" width=\"86\" height=\"130\" rx=\"10\" fill=\"#3a56b0\"/><rect x=\"${x + 16}\" y=\"${y + 18}\" width=\"66\" height=\"52\" rx=\"6\" fill=\"#0c1a44\"/><path d=\"M${x + 24} ${y + 30} L${x + 74} ${y + 58}\" stroke=\"#6f86d6\" stroke-width=\"4\" opacity=\".6\"/><rect x=\"${x + 18}\" y=\"${y + 86}\" width=\"62\" height=\"40\" rx=\"6\" fill=\"#e9eef8\"/><circle cx=\"${x + 38}\" cy=\"${y + 106}\" r=\"7\" fill=\"#ff6b5e\"/></g>`,\n    pc: (x, y) => `<g ${o}><rect x=\"${x + 4}\" y=\"${y + 20}\" width=\"92\" height=\"80\" rx=\"8\" fill=\"#b8763a\"/><rect x=\"${x + 12}\" y=\"${y - 30}\" width=\"76\" height=\"60\" rx=\"8\" fill=\"#e9eef8\"/><rect x=\"${x + 22}\" y=\"${y - 22}\" width=\"56\" height=\"40\" rx=\"4\" fill=\"#1b2d6b\"/><path d=\"M${x + 30} ${y - 8} H${x + 62}\" stroke=\"#7be8a0\" stroke-width=\"4\"/></g>`,\n    radio: (x, y) => `<g ${o}><rect x=\"${x + 12}\" y=\"${y + 30}\" width=\"76\" height=\"52\" rx=\"8\" fill=\"#ff6b5e\"/><circle cx=\"${x + 36}\" cy=\"${y + 56}\" r=\"14\" fill=\"#ffe0dc\"/><path d=\"M${x + 60} ${y + 46} H${x + 80} M${x + 60} ${y + 58} H${x + 80} M${x + 60} ${y + 70} H${x + 80}\" stroke-width=\"3\"/></g>`,\n    table: (x, y, w, h, cloth = \"#ff8fa3\", plate = true) => `<g fill=\"#000\" opacity=\".16\"><ellipse cx=\"${x + w / 2}\" cy=\"${y + h + 8}\" rx=\"${w / 2 + 10}\" ry=\"12\"/></g>\n      <g ${o}><rect x=\"${x + 6}\" y=\"${y + 6}\" width=\"${w - 12}\" height=\"${h - 12}\" rx=\"16\" fill=\"#c98446\"/><rect x=\"${x + 20}\" y=\"${y + 20}\" width=\"${w - 40}\" height=\"${h - 40}\" rx=\"10\" fill=\"${cloth}\" opacity=\".9\" stroke-width=\"3\"/>${plate ? `<circle cx=\"${x + w / 2}\" cy=\"${y + h / 2}\" r=\"${Math.min(w, h) / 6}\" fill=\"#fff6dc\" stroke-width=\"4\"/>` : \"\"}</g>`,\n    plant: (x, y) => `<g ${o}><path d=\"M${x + 50} ${y + 60} C${x + 14} ${y + 40} ${x + 14} ${y + 6} ${x + 44} ${y} C${x + 52} ${y + 28} ${x + 62} ${y + 40} ${x + 50} ${y + 60} Z M${x + 50} ${y + 60} C${x + 88} ${y + 40} ${x + 92} ${y + 12} ${x + 66} ${y - 2} C${x + 54} ${y + 26} ${x + 44} ${y + 44} ${x + 50} ${y + 60} Z\" fill=\"#46c26f\" stroke-width=\"4\"/><rect x=\"${x + 28}\" y=\"${y + 52}\" width=\"44\" height=\"40\" rx=\"6\" fill=\"#ff8a6b\"/></g>`,\n    mat: (x, y, w) => `<g ${o}><rect x=\"${x + 12}\" y=\"${y + 16}\" width=\"${w - 24}\" height=\"68\" rx=\"12\" fill=\"#d63a4a\"/><rect x=\"${x + 26}\" y=\"${y + 28}\" width=\"${w - 52}\" height=\"44\" rx=\"8\" fill=\"none\" stroke=\"#ffd0c4\" stroke-width=\"4\" stroke-dasharray=\"12 8\"/></g>`,\n    counter: (x, y, w, h) => `<g ${o}><rect x=\"${x}\" y=\"${y}\" width=\"${w}\" height=\"${h}\" rx=\"8\" fill=\"#e9eef8\"/><rect x=\"${x + 8}\" y=\"${y + 8}\" width=\"${w - 16}\" height=\"14\" fill=\"#cfd9ea\" stroke=\"none\"/></g>`,\n    machine: (x, y) => `<g ${o}><rect x=\"${x + 6}\" y=\"${y}\" width=\"88\" height=\"140\" rx=\"10\" fill=\"#e9eef8\"/><rect x=\"${x + 18}\" y=\"${y + 14}\" width=\"64\" height=\"40\" rx=\"6\" fill=\"#1b2d6b\"/><path d=\"M${x + 26} ${y + 34} H${x + 74}\" stroke=\"#7be8a0\" stroke-width=\"4\"/>\n      ${[0, 1, 2].map((i) => `<circle cx=\"${x + 28 + i * 22}\" cy=\"${y + 84}\" r=\"9\" fill=\"#ff6b5e\"/>`).join(\"\")}<rect x=\"${x + 18}\" y=\"${y + 104}\" width=\"64\" height=\"20\" rx=\"4\" fill=\"#cfd9ea\"/></g>`,\n    trash: (x, y) => `<g ${o}><path d=\"M${x + 24} ${y + 30} L${x + 30} ${y + 92} H${x + 70} L${x + 76} ${y + 30}Z\" fill=\"#9aa4c8\"/><rect x=\"${x + 18}\" y=\"${y + 20}\" width=\"64\" height=\"14\" rx=\"5\" fill=\"#6f7aa0\"/></g>`,\n    rug: (cx, cy, rx, ry) => `<ellipse cx=\"${cx}\" cy=\"${cy}\" rx=\"${rx}\" ry=\"${ry}\" fill=\"#6f86d6\" ${o} opacity=\".9\"/><ellipse cx=\"${cx}\" cy=\"${cy}\" rx=\"${rx - 30}\" ry=\"${ry - 24}\" fill=\"none\" stroke=\"#bcd0ff\" stroke-width=\"5\" stroke-dasharray=\"14 10\"/>`,\n  };\n})();\n\n/* page/hd/art/gate.js */\n// Route gate house, 10 x 8 cells: doors north (4..5,0) and south (4..5,7), guard room at (0,4).\nArt.gate = function () {\n  const f = Art.furniture;\n  return Art.shell(10, 8, \"house\") + f.window(100) + f.window(700) + f.mat(400, 0, 200) + f.rug(500, 400, 260, 90) +\n    f.plant(0, 600) + f.plant(900, 600) + f.mat(400, 700, 200) + Art.roomEnd;\n};\n\n/* page/hd/art/hero.js */\n// Player portrait: the kid in the cap (viewBox 300 x 380)\nArt.hero = function () {\n  return `<svg viewBox=\"0 0 300 380\" xmlns=\"http://www.w3.org/2000/svg\">\n<defs>\n<linearGradient id=\"hr-jacket\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0\" stop-color=\"#ffb62e\"/><stop offset=\"1\" stop-color=\"#e57d12\"/></linearGradient>\n<linearGradient id=\"hr-cap\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0\" stop-color=\"#ff6b5e\"/><stop offset=\"1\" stop-color=\"#c9322a\"/></linearGradient>\n</defs>\n<g stroke=\"${INK}\" stroke-width=\"6\" stroke-linejoin=\"round\" stroke-linecap=\"round\">\n<path fill=\"url(#hr-jacket)\" d=\"M24 380 C24 304 66 266 112 256 L188 256 C234 266 276 304 276 380 Z\"/>\n<path fill=\"#1f3a8a\" d=\"M112 256 L150 336 L188 256 L168 250 L150 292 L132 250 Z\"/>\n<rect x=\"126\" y=\"218\" width=\"48\" height=\"44\" rx=\"14\" fill=\"#e9b184\"/>\n<ellipse cx=\"150\" cy=\"168\" rx=\"66\" ry=\"70\" fill=\"#f4c397\"/>\n<path fill=\"#3a2418\" d=\"M82 150 C84 110 116 96 150 96 C184 96 216 110 218 150 C200 134 176 128 150 128 C124 128 100 134 82 150 Z\"/>\n<path fill=\"url(#hr-cap)\" d=\"M78 134 C80 66 120 40 154 40 C192 40 224 70 222 134 C196 118 104 118 78 134 Z\"/>\n<path fill=\"url(#hr-cap)\" d=\"M96 128 C130 112 214 112 248 138 C226 150 124 146 96 128 Z\"/>\n<circle cx=\"150\" cy=\"82\" r=\"16\" fill=\"#ffd25a\"/>\n</g>\n<circle cx=\"120\" cy=\"172\" r=\"9\" fill=\"${INK}\"/><circle cx=\"180\" cy=\"172\" r=\"9\" fill=\"${INK}\"/>\n<circle cx=\"117\" cy=\"169\" r=\"3.4\" fill=\"#fff\"/><circle cx=\"177\" cy=\"169\" r=\"3.4\" fill=\"#fff\"/>\n<path d=\"M132 200 Q150 216 168 200\" fill=\"none\" stroke=\"${INK}\" stroke-width=\"5\" stroke-linecap=\"round\"/>\n<circle cx=\"102\" cy=\"196\" r=\"9\" fill=\"#ff8c9e\" opacity=\".6\"/><circle cx=\"198\" cy=\"196\" r=\"9\" fill=\"#ff8c9e\" opacity=\".6\"/>\n</svg>`;\n};\n\n/* page/hd/art/hootling.js */\n// HOOTLING (was Hoothoot): round night owl with moon-yellow eyes and ear tufts.\nArt.hootling = function () {\n  return `<svg viewBox=\"0 0 200 200\" xmlns=\"http://www.w3.org/2000/svg\">\n<defs><linearGradient id=\"ht-b\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0\" stop-color=\"#9a7ad0\"/><stop offset=\"1\" stop-color=\"#5a3f9a\"/></linearGradient></defs>\n<ellipse cx=\"100\" cy=\"188\" rx=\"50\" ry=\"8\" fill=\"#000\" opacity=\".22\"/>\n<g stroke=\"${INK}\" stroke-width=\"5\" stroke-linejoin=\"round\" stroke-linecap=\"round\">\n  <path d=\"M80 174 V190 M70 190 H90 M120 174 V190 M110 190 H130\" fill=\"none\" stroke=\"#ffb84a\" stroke-width=\"6\"/>\n  <ellipse cx=\"100\" cy=\"124\" rx=\"60\" ry=\"58\" fill=\"url(#ht-b)\"/>\n  <ellipse cx=\"100\" cy=\"146\" rx=\"36\" ry=\"32\" fill=\"#f2e8ff\" stroke=\"none\"/>\n  <path d=\"M82 134 q18 12 36 0 M80 150 q20 12 40 0 M86 164 q14 8 28 0\" fill=\"none\" stroke=\"#9a7ad0\" stroke-width=\"4\"/>\n  <path d=\"M38 118 C16 134 22 172 54 172 C64 150 58 132 38 118Z\" fill=\"#4a3382\"/>\n  <path d=\"M162 118 C184 134 178 172 146 172 C136 150 142 132 162 118Z\" fill=\"#4a3382\"/>\n  <path d=\"M52 80 L44 38 L84 66Z M148 80 L156 38 L116 66Z\" fill=\"url(#ht-b)\"/>\n  <ellipse cx=\"100\" cy=\"84\" rx=\"56\" ry=\"44\" fill=\"url(#ht-b)\"/>\n  <circle cx=\"74\" cy=\"86\" r=\"26\" fill=\"#fff6dc\"/><circle cx=\"126\" cy=\"86\" r=\"26\" fill=\"#fff6dc\"/>\n  <path fill=\"#ffb84a\" d=\"M90 96 L110 96 L100 118Z\"/>\n</g>\n${Art.eye(74, 86, 15, \"#ffd25a\")}${Art.eye(126, 86, 15, \"#ffd25a\")}\n</svg>`;\n};\n\n/* page/hd/art/introMeadow.js */\n// Intro act 2 backdrop: morning meadow with rolling hills and flowers (portrait, slice).\nArt.introMeadow = function () {\n  let flowers = \"\";\n  const cols = [\"#ff6b5e\", \"#ffc93c\", \"#fff6dc\", \"#ff9aa8\"];\n  for (let i = 0; i < 26; i++) {\n    const x = (i * 137) % 980 + 10, y = 860 + ((i * 71) % 300);\n    flowers += `<circle cx=\"${x}\" cy=\"${y}\" r=\"9\" fill=\"${cols[i % 4]}\" stroke=\"${INK}\" stroke-width=\"3\"/>`;\n  }\n  return `<svg class=\"bgsvg\" viewBox=\"0 0 1000 1200\" preserveAspectRatio=\"xMidYMid slice\" xmlns=\"http://www.w3.org/2000/svg\">\n<defs><linearGradient id=\"morn\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0\" stop-color=\"#7cc8ff\"/><stop offset=\".7\" stop-color=\"#d9f2ff\"/><stop offset=\"1\" stop-color=\"#fff2c8\"/></linearGradient></defs>\n<rect width=\"1000\" height=\"1200\" fill=\"url(#morn)\"/>\n<circle cx=\"780\" cy=\"260\" r=\"90\" fill=\"#ffe27a\" stroke=\"${INK}\" stroke-width=\"6\"/>\n<g class=\"clouds2\" fill=\"#fff\" stroke=\"${INK}\" stroke-width=\"5\"><path d=\"M110 330 q30 -60 90 -30 q50 -50 100 10 q40 0 40 40 H110z\"/><path d=\"M520 180 q30 -50 80 -24 q40 -40 80 8 q34 0 34 34 H520z\"/></g>\n<path d=\"M0 760 C180 680 360 740 560 690 C760 640 880 720 1000 690 L1000 1200 L0 1200Z\" fill=\"#59c97a\" stroke=\"${INK}\" stroke-width=\"6\"/>\n<path d=\"M0 900 C220 830 420 900 620 850 C800 810 920 870 1000 850 L1000 1200 L0 1200Z\" fill=\"#3fae62\" stroke=\"${INK}\" stroke-width=\"6\"/>\n${flowers}\n</svg>`;\n};\n\n/* page/hd/art/introSea.js */\n// Intro act 1 backdrop: sunlit deep water, light rays, kelp (portrait, slice).\nArt.introSea = function () {\n  const kelp = [80, 210, 380, 590, 760, 910].map((x, i) =>\n    `<path class=\"kelp\" style=\"animation-delay:${i * 0.4}s\" d=\"M${x} 1200 C${x - 40} 1100 ${x + 40} 1020 ${x} 930 C${x - 40} 850 ${x + 40} 780 ${x + 6} 700\" fill=\"none\" stroke=\"${i % 2 ? \"#1f9b6a\" : \"#2fc486\"}\" stroke-width=\"22\" stroke-linecap=\"round\"/>`).join(\"\");\n  return `<svg class=\"bgsvg\" viewBox=\"0 0 1000 1200\" preserveAspectRatio=\"xMidYMid slice\" xmlns=\"http://www.w3.org/2000/svg\">\n<defs>\n  <linearGradient id=\"sea\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0\" stop-color=\"#6fd6ff\"/><stop offset=\".5\" stop-color=\"#1a8fc4\"/><stop offset=\"1\" stop-color=\"#0b3b78\"/></linearGradient>\n  <linearGradient id=\"ray\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0\" stop-color=\"#fff\" stop-opacity=\".4\"/><stop offset=\"1\" stop-color=\"#fff\" stop-opacity=\"0\"/></linearGradient>\n</defs>\n<rect width=\"1000\" height=\"1200\" fill=\"url(#sea)\"/>\n<g class=\"rays\" fill=\"url(#ray)\"><path d=\"M150 0 L330 0 L120 900 L-60 900Z\"/><path d=\"M520 0 L650 0 L520 900 L360 900Z\"/><path d=\"M800 0 L930 0 L1000 900 L780 900Z\"/></g>\n${kelp}\n<path d=\"M0 1130 C200 1090 380 1150 600 1110 C800 1075 920 1130 1000 1100 L1000 1200 L0 1200Z\" fill=\"#e9c98a\" stroke=\"${INK}\" stroke-width=\"6\"/>\n</svg>`;\n};\n\n/* page/hd/art/logo.js */\n// The Buddymon Gold title logo (wordmark with badge), used by the title and menu scenes.\nArt.logo = function () {\n  return `<svg class=\"logo-svg\" viewBox=\"0 0 1000 320\" xmlns=\"http://www.w3.org/2000/svg\">\n<defs>\n<linearGradient id=\"gold\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0\" stop-color=\"#fff3a8\"/><stop offset=\".5\" stop-color=\"#ffc93c\"/><stop offset=\"1\" stop-color=\"#f08a14\"/></linearGradient>\n<linearGradient id=\"rib\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0\" stop-color=\"#2b4ea8\"/><stop offset=\"1\" stop-color=\"#16295f\"/></linearGradient>\n<clipPath id=\"top-half\"><rect x=\"0\" y=\"0\" width=\"1000\" height=\"112\"/></clipPath>\n</defs>\n<g font-family=\"'Lilita One','Fredoka',system-ui,sans-serif\" text-anchor=\"middle\" stroke-linejoin=\"round\">\n<text x=\"500\" y=\"192\" font-size=\"172\" fill=\"#b84a12\" stroke=\"${INK}\" stroke-width=\"34\" paint-order=\"stroke\">BUDDYMON</text>\n<text x=\"500\" y=\"176\" font-size=\"172\" fill=\"url(#gold)\" stroke=\"${INK}\" stroke-width=\"30\" paint-order=\"stroke\">BUDDYMON</text>\n<text x=\"500\" y=\"176\" font-size=\"172\" fill=\"#fff\" opacity=\".45\" clip-path=\"url(#top-half)\">BUDDYMON</text>\n</g>\n<path d=\"M300 226 L700 226 L730 260 L700 294 L300 294 L270 260 Z\" fill=\"url(#rib)\" stroke=\"${INK}\" stroke-width=\"8\" stroke-linejoin=\"round\"/>\n<path d=\"M300 236 L700 236\" stroke=\"#6f93ff\" stroke-width=\"3\" opacity=\".6\"/>\n<text x=\"500\" y=\"282\" text-anchor=\"middle\" font-family=\"'Lilita One','Fredoka',system-ui,sans-serif\" font-size=\"58\" letter-spacing=\"14\" fill=\"url(#gold)\" stroke=\"${INK}\" stroke-width=\"8\" paint-order=\"stroke\">GOLD</text>\n<path d=\"M270 260 l-26 -20 l0 40 z M730 260 l26 -20 l0 40 z\" fill=\"#ffc93c\" stroke=\"${INK}\" stroke-width=\"6\" stroke-linejoin=\"round\"/>\n</svg>`;\n};\n\n/* page/hd/art/looks.js */\n// Who is who: looks for Art.person. NPC keys are SPRITE_* names (see constants/sprite_constants.asm).\nArt.looks = {\n  HERO: { hat: \"#c9322a\", hair: \"#3a2418\", top: \"#ffb62e\", legs: \"#1f3a8a\" },\n  MOM: { hair: \"#6b3d1e\", bun: true, dress: true, top: \"#ff8fa3\", apron: \"#fff6dc\", legs: \"#f4c397\" },\n  TEACHER: { hair: \"#8a5a2b\", glasses: true, dress: true, top: \"#7ab6ff\", legs: \"#f4c397\" },\n  FISHER: { hat: \"#ffd25a\", hair: \"#7a5a2a\", top: \"#3fae62\", legs: \"#6b4a2a\" },\n  RIVAL: { hair: \"#c9322a\", top: \"#3a3f52\", legs: \"#2a2f45\" },\n  WILLOW: { hair: \"#6b4a2a\", glasses: true, dress: true, top: \"#ffffff\", legs: \"#6b4a2a\" },\n  SCIENTIST: { hair: \"#3a6fb0\", glasses: true, dress: true, top: \"#ffffff\", legs: \"#6b4a2a\" },\n  BUG_CATCHER: { hat: \"#6fd382\", hair: \"#6b4a2a\", top: \"#ffb62e\", legs: \"#3a6fb0\" },\n  COOLTRAINER_F: { hair: \"#d9604c\", dress: true, top: \"#ff6b5e\", legs: \"#f4c397\" },\n  NURSE: { hair: \"#ff9fb0\", bun: true, dress: true, top: \"#ffd1dc\", apron: \"#ffffff\", legs: \"#f4c397\" },\n  CLERK: { hair: \"#4a3a2a\", dress: true, top: \"#46a0e0\", legs: \"#2a3a6a\" },\n  GENTLEMAN: { hair: \"#c9c9d6\", dress: true, top: \"#3a3f52\", legs: \"#2a2f45\" },\n  YOUNGSTER: { hat: \"#4aa3e8\", hair: \"#3a2418\", top: \"#ffb62e\", legs: \"#6b4a2a\" },\n  COOLTRAINER_M: { hair: \"#3a2418\", top: \"#e8e8f0\", legs: \"#2a2f45\" },\n  GRAMPS: { hair: \"#e8e8ee\", dress: true, top: \"#8a6a3a\", legs: \"#5a4a2a\" },\n  POKEFAN_M: { hat: \"#e8943a\", hair: \"#6b4a2a\", top: \"#5aa860\", legs: \"#4a4a6a\" },\n  LASS: { hair: \"#7a4a2a\", dress: true, top: \"#ffa0d0\", legs: \"#f4c397\" },\n  OFFICER: { hat: \"#2a3a8a\", hair: \"#3a2418\", top: \"#3a56b0\", legs: \"#2a3a6a\" },\n  ASPEN: { hair: \"#c8c8d4\", dress: true, top: \"#f4f7ff\", legs: \"#7a5a3a\" },\n  OTHER: { hair: \"#555a6e\", top: \"#9aa4c8\", legs: \"#5a5f7a\" }, // anyone without a look yet\n};\nArt.heroSprite = (dir) => Art.person(dir, Art.looks.HERO);\n\n/* page/hd/art/mrBuddymonHouse.js */\n// Mr. Buddymon's house, 8 x 8 cells: magazines (0..1,1), broken computer (6..7,1), table (4..5,3..4), strange coins (6..7,3), door (2..3,7).\nArt.mrBuddymonHouse = function () {\n  const f = Art.furniture, o = `stroke=\"${INK}\" stroke-width=\"5\" stroke-linejoin=\"round\"`;\n  const coins = [[630, 330], [690, 350], [740, 330], [660, 380], [720, 385]].map(([x, y]) => `<ellipse cx=\"${x}\" cy=\"${y}\" rx=\"26\" ry=\"12\" fill=\"#ffc93c\" ${o} stroke-width=\"3\"/>`).join(\"\");\n  return Art.shell(8, 8, \"house\") + f.window(300) + f.shelf(0, 40, 200, 160) + f.pc(600, 100) + f.pc(700, 100) +\n    f.table(400, 300, 200, 200, \"#8fd3ff\") + `<rect x=\"610\" y=\"300\" width=\"170\" height=\"110\" rx=\"10\" fill=\"#b8763a\" ${o}/>` + coins +\n    f.rug(300, 600, 200, 70) + f.mat(200, 700, 200) + Art.roomEnd;\n};\n\n/* page/hd/art/neighborHouse.js */\n// The neighbor's house, 8 x 8 cells: shelves (0..1,1), TV (2,1), radio (7,1), table (3..4,3..4), plants (0,6) (7,6), door (2..3,7).\nArt.neighborHouse = function () {\n  const f = Art.furniture;\n  return Art.shell(8, 8, \"house\") + f.window(500) + f.shelf(0, 40, 200, 160) + f.tv(200, 30) + f.radio(700, 100) +\n    f.rug(400, 580, 220, 80) + f.table(300, 300, 200, 200, \"#8fd3ff\") + f.plant(0, 600) + f.plant(700, 600) + f.mat(200, 700, 200) + Art.roomEnd;\n};\n\n/* page/hd/art/nibblet.js */\n// NIBBLET (was Rattata): round purple mouse with big front teeth and a curly tail.\nArt.nibblet = function () {\n  return `<svg viewBox=\"0 0 200 200\" xmlns=\"http://www.w3.org/2000/svg\">\n<defs><linearGradient id=\"nb-b\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0\" stop-color=\"#b79cf0\"/><stop offset=\"1\" stop-color=\"#8466d0\"/></linearGradient></defs>\n<ellipse cx=\"100\" cy=\"186\" rx=\"56\" ry=\"8\" fill=\"#000\" opacity=\".22\"/>\n<g stroke=\"${INK}\" stroke-width=\"5\" stroke-linejoin=\"round\" stroke-linecap=\"round\">\n  <path d=\"M146 160 C196 170 198 110 168 108 C186 120 176 150 146 146\" fill=\"none\" stroke-width=\"9\"/>\n  <path d=\"M146 160 C196 170 198 110 168 108 C186 120 176 150 146 146\" fill=\"none\" stroke=\"#e8c8d8\" stroke-width=\"4\"/>\n  <ellipse cx=\"68\" cy=\"176\" rx=\"18\" ry=\"10\" fill=\"url(#nb-b)\"/><ellipse cx=\"132\" cy=\"176\" rx=\"18\" ry=\"10\" fill=\"url(#nb-b)\"/>\n  <ellipse cx=\"100\" cy=\"140\" rx=\"44\" ry=\"38\" fill=\"url(#nb-b)\"/>\n  <ellipse cx=\"100\" cy=\"150\" rx=\"26\" ry=\"22\" fill=\"#f3e8ff\" stroke=\"none\"/>\n  <circle cx=\"52\" cy=\"66\" r=\"24\" fill=\"url(#nb-b)\"/><circle cx=\"52\" cy=\"66\" r=\"13\" fill=\"#ffb3c8\" stroke=\"none\"/>\n  <circle cx=\"148\" cy=\"66\" r=\"24\" fill=\"url(#nb-b)\"/><circle cx=\"148\" cy=\"66\" r=\"13\" fill=\"#ffb3c8\" stroke=\"none\"/>\n  <ellipse cx=\"100\" cy=\"102\" rx=\"54\" ry=\"46\" fill=\"url(#nb-b)\"/>\n  <rect x=\"88\" y=\"124\" width=\"12\" height=\"22\" rx=\"4\" fill=\"#fff\" stroke-width=\"4\"/><rect x=\"100\" y=\"124\" width=\"12\" height=\"22\" rx=\"4\" fill=\"#fff\" stroke-width=\"4\"/>\n</g>\n${Art.eye(76, 94, 11, \"#d63a4a\")}${Art.eye(124, 94, 11, \"#d63a4a\")}\n<ellipse cx=\"100\" cy=\"116\" rx=\"9\" ry=\"6\" fill=\"#ff7a96\" stroke=\"${INK}\" stroke-width=\"4\"/>\n<path d=\"M60 112 L34 106 M60 120 L34 124 M140 112 L166 106 M140 120 L166 124\" stroke=\"${INK}\" stroke-width=\"3.5\" stroke-linecap=\"round\"/>\n</svg>`;\n};\n\n/* page/hd/art/peekat.js */\n// PEEKAT (was Sentret): meerkat standing tall on its tail, always keeping watch.\nArt.peekat = function () {\n  return `<svg viewBox=\"0 0 200 200\" xmlns=\"http://www.w3.org/2000/svg\">\n<defs><linearGradient id=\"pk-b\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0\" stop-color=\"#e8c28a\"/><stop offset=\"1\" stop-color=\"#c8955a\"/></linearGradient></defs>\n<ellipse cx=\"100\" cy=\"190\" rx=\"50\" ry=\"7\" fill=\"#000\" opacity=\".22\"/>\n<g stroke=\"${INK}\" stroke-width=\"5\" stroke-linejoin=\"round\" stroke-linecap=\"round\">\n  <path d=\"M128 176 C176 180 184 130 160 118 C168 140 150 158 124 160Z\" fill=\"url(#pk-b)\"/>\n  <ellipse cx=\"78\" cy=\"184\" rx=\"20\" ry=\"9\" fill=\"#a8764a\"/><ellipse cx=\"122\" cy=\"184\" rx=\"20\" ry=\"9\" fill=\"#a8764a\"/>\n  <ellipse cx=\"100\" cy=\"142\" rx=\"38\" ry=\"46\" fill=\"url(#pk-b)\"/>\n  <path d=\"M82 120 L118 120 M80 138 L120 138 M82 156 L118 156\" stroke=\"#9a6a3a\" stroke-width=\"5\" fill=\"none\"/>\n  <ellipse cx=\"100\" cy=\"150\" rx=\"22\" ry=\"26\" fill=\"#fff0d0\" stroke=\"none\"/>\n  <ellipse cx=\"62\" cy=\"132\" rx=\"11\" ry=\"22\" fill=\"url(#pk-b)\" transform=\"rotate(14 62 132)\"/><ellipse cx=\"138\" cy=\"132\" rx=\"11\" ry=\"22\" fill=\"url(#pk-b)\" transform=\"rotate(-14 138 132)\"/>\n  <circle cx=\"56\" cy=\"46\" r=\"15\" fill=\"#a8764a\"/><circle cx=\"144\" cy=\"46\" r=\"15\" fill=\"#a8764a\"/>\n  <ellipse cx=\"100\" cy=\"64\" rx=\"46\" ry=\"40\" fill=\"url(#pk-b)\"/>\n  <ellipse cx=\"100\" cy=\"80\" rx=\"26\" ry=\"18\" fill=\"#fff0d0\" stroke=\"none\"/>\n  <path d=\"M60 60 Q74 52 86 66 Q74 76 60 70Z M140 60 Q126 52 114 66 Q126 76 140 70Z\" fill=\"#6b4226\" stroke-width=\"4\"/>\n</g>\n${Art.eye(76, 62, 8, \"#e8b04a\")}${Art.eye(124, 62, 8, \"#e8b04a\")}\n<ellipse cx=\"100\" cy=\"76\" rx=\"7\" ry=\"5\" fill=\"${INK}\"/><path d=\"M92 86 Q100 93 108 86\" fill=\"none\" stroke=\"${INK}\" stroke-width=\"4\" stroke-linecap=\"round\"/>\n</svg>`;\n};\n\n/* page/hd/art/person.js */\n// Overworld person, dir: 0 down, 1 up, 2 left, 3 right (viewBox 60 x 80). Look `o` comes from Art.looks:\n//   skin, hair, hat (cap colour, optional), bun, glasses, top, dress (skirt/coat instead of tee), apron, legs.\nArt.person = function (dir, o) {\n  const skin = o.skin || \"#f4c397\";\n  const eyes = dir === 1 ? \"\" : dir === 0\n    ? `<circle cx=\"24\" cy=\"30\" r=\"3\" fill=\"${INK}\"/><circle cx=\"36\" cy=\"30\" r=\"3\" fill=\"${INK}\"/>`\n    : `<circle cx=\"${dir === 2 ? 21 : 39}\" cy=\"30\" r=\"3\" fill=\"${INK}\"/>`;\n  const specs = o.glasses && dir !== 1\n    ? `<g fill=\"none\" stroke=\"${INK}\" stroke-width=\"2\"><circle cx=\"${dir === 0 ? 24 : dir === 2 ? 21 : 39}\" cy=\"30\" r=\"5.5\"/>${dir === 0 ? `<circle cx=\"36\" cy=\"30\" r=\"5.5\"/>` : \"\"}</g>` : \"\";\n  const visor = !o.hat || dir === 1 ? \"\" : dir === 0\n    ? `<path d=\"M14 22 Q30 32 46 22 Q30 16 14 22\" fill=\"${o.hat}\"/>`\n    : `<path d=\"${dir === 2 ? \"M8 24 Q20 20 30 22 L30 28 Q18 28 8 24\" : \"M52 24 Q40 20 30 22 L30 28 Q42 28 52 24\"}\" fill=\"${o.hat}\"/>`;\n  const hair = o.hat\n    ? `<path fill=\"${dir === 1 ? o.hair : o.hat}\" d=\"M14 26 C14 8 46 8 46 26 C38 20 22 20 14 26 Z\"/>${dir === 1 ? `<path fill=\"${o.hat}\" d=\"M15 26 C15 10 45 10 45 26 C38 22 22 22 15 26 Z\"/>` : \"\"}`\n    : `<path fill=\"${o.hair}\" d=\"M13 28 C11 6 49 6 47 28 C42 18 18 18 13 28 Z\"/>${dir === 1 ? `<path fill=\"${o.hair}\" d=\"M14 28 C14 12 46 12 46 30 C40 36 20 36 14 28 Z\"/>` : \"\"}${o.bun ? `<circle cx=\"30\" cy=\"${dir === 1 ? 9 : 8}\" r=\"${dir === 1 ? 6 : 5}\" fill=\"${o.hair}\"/>` : \"\"}`;\n  const body = o.dress\n    ? `<path fill=\"${o.top}\" d=\"M14 64 C12 48 18 40 30 40 C42 40 48 48 46 64 Z\"/>${o.apron && dir !== 1 ? `<path fill=\"${o.apron}\" d=\"M22 64 C22 52 24 46 30 46 C36 46 38 52 38 64 Z\"/>` : \"\"}`\n    : `<path fill=\"${o.top}\" d=\"M16 56 C14 44 20 40 30 40 C40 40 46 44 44 56 Z\"/>`;\n  const top = o.dress ? 60 : 56;\n  return `<svg viewBox=\"0 0 60 80\" xmlns=\"http://www.w3.org/2000/svg\">\n<ellipse cx=\"30\" cy=\"74\" rx=\"18\" ry=\"5\" fill=\"#000\" opacity=\".25\"/>\n<g stroke=\"${INK}\" stroke-width=\"3.2\" stroke-linejoin=\"round\" stroke-linecap=\"round\">\n<path class=\"leg l\" fill=\"${o.legs}\" d=\"M20 ${top} L28 ${top} L28 70 L18 70 Z\"/><path class=\"leg r\" fill=\"${o.legs}\" d=\"M32 ${top} L40 ${top} L42 70 L32 70 Z\"/>\n${body}\n<circle cx=\"30\" cy=\"28\" r=\"15\" fill=\"${skin}\"/>\n${hair}\n</g>\n${eyes}${specs}${visor}\n</svg>`;\n};\n\n/* page/hd/art/pokecenter.js */\n// Pokecenter 1F, 10 x 8 cells: counter (0..5,2), healing machine (5,1), PC (9,1), sofas (7..8,5) (7..8,7), stairs (0,7), door (3..4,7).\nArt.pokecenter = function () {\n  const f = Art.furniture;\n  return Art.shell(10, 8, \"lab\") + f.window(100) + f.window(700) + f.machine(450, 40) + f.pc(900, 100) +\n    f.counter(0, 200, 600, 90) + f.table(700, 500, 200, 100, \"#ff8fa3\", false) + f.table(700, 700, 200, 100, \"#ff8fa3\", false) +\n    f.mat(300, 700, 200) + Art.roomEnd;\n};\n\n/* page/hd/art/professor.js */\n// Friendly professor, bust portrait (viewBox 300 x 380)\nArt.professor = function () {\n  return `<svg viewBox=\"0 0 300 380\" xmlns=\"http://www.w3.org/2000/svg\">\n<defs>\n<linearGradient id=\"pf-coat\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0\" stop-color=\"#ffffff\"/><stop offset=\"1\" stop-color=\"#d8e2f2\"/></linearGradient>\n<linearGradient id=\"pf-hair\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0\" stop-color=\"#e6ebf5\"/><stop offset=\"1\" stop-color=\"#b9c2d8\"/></linearGradient>\n</defs>\n<g stroke=\"${INK}\" stroke-width=\"6\" stroke-linejoin=\"round\" stroke-linecap=\"round\">\n<path fill=\"url(#pf-coat)\" d=\"M20 380 C20 300 60 262 110 252 L190 252 C240 262 280 300 280 380 Z\"/>\n<path fill=\"#2fae6b\" d=\"M112 252 L150 300 L188 252 L168 246 L150 270 L132 246 Z\"/>\n<path fill=\"#fff\" d=\"M104 250 L150 322 L124 372 L82 292 Z\"/><path fill=\"#fff\" d=\"M196 250 L150 322 L176 372 L218 292 Z\"/>\n<rect x=\"124\" y=\"214\" width=\"52\" height=\"44\" rx=\"14\" fill=\"#f2c29a\"/>\n<path fill=\"url(#pf-hair)\" d=\"M60 170 C52 70 120 30 150 30 C190 30 250 66 240 170 C246 214 230 240 212 246 L212 150 L88 150 L88 246 C70 238 56 214 60 170 Z\"/>\n<ellipse cx=\"150\" cy=\"168\" rx=\"70\" ry=\"76\" fill=\"#f7d0a8\"/>\n<path fill=\"url(#pf-hair)\" d=\"M78 150 C86 82 126 66 150 66 C180 66 218 84 224 150 C206 120 180 104 150 104 C120 104 96 118 78 150 Z\"/>\n</g>\n<g fill=\"none\" stroke=\"${INK}\" stroke-width=\"5\" stroke-linecap=\"round\">\n<circle cx=\"118\" cy=\"168\" r=\"24\" fill=\"#cfe9ff\" fill-opacity=\".35\"/><circle cx=\"182\" cy=\"168\" r=\"24\" fill=\"#cfe9ff\" fill-opacity=\".35\"/>\n<path d=\"M142 166 Q150 160 158 166\"/>\n<path d=\"M96 164 L84 160 M204 164 L216 160\"/>\n<path d=\"M126 218 Q150 236 174 218\"/>\n</g>\n<circle cx=\"118\" cy=\"170\" r=\"8\" fill=\"${INK}\"/><circle cx=\"182\" cy=\"170\" r=\"8\" fill=\"${INK}\"/>\n<circle cx=\"115\" cy=\"167\" r=\"3\" fill=\"#fff\"/><circle cx=\"179\" cy=\"167\" r=\"3\" fill=\"#fff\"/>\n<circle cx=\"102\" cy=\"196\" r=\"10\" fill=\"#ff9aa8\" opacity=\".55\"/><circle cx=\"198\" cy=\"196\" r=\"10\" fill=\"#ff9aa8\" opacity=\".55\"/>\n<path d=\"M124 150 q14 -10 28 -2 M148 148 q14 -8 28 2\" fill=\"none\" stroke=\"#8793ad\" stroke-width=\"5\" stroke-linecap=\"round\"/>\n<g transform=\"translate(206 282)\"><path d=\"M0 0 c0 -16 14 -22 26 -22 c0 14 -8 24 -26 22z\" fill=\"#46c26f\" stroke=\"${INK}\" stroke-width=\"4\" stroke-linejoin=\"round\"/></g>\n</svg>`;\n};\n\n/* page/hd/art/props.js */\n// Map objects that aren't people (viewBox 60 x 80, same box as Art.person). Keys are the names maps give their objects.\nArt.props = {\n  // A buddy net bundle: a round woven pouch with a knot on top (stands in for a Poke Ball on the lab table).\n  BUDDY_NET: () => `<svg viewBox=\"0 0 60 80\" xmlns=\"http://www.w3.org/2000/svg\"><ellipse cx=\"30\" cy=\"64\" rx=\"16\" ry=\"5\" fill=\"#000\" opacity=\".25\"/>\n<g stroke=\"${INK}\" stroke-width=\"3.2\" stroke-linejoin=\"round\" stroke-linecap=\"round\"><circle cx=\"30\" cy=\"50\" r=\"15\" fill=\"#f2d9a0\"/>\n<path d=\"M17 44 Q30 52 43 44 M16 54 Q30 62 44 54 M24 36 Q28 50 24 64 M36 36 Q32 50 36 64\" fill=\"none\" stroke-width=\"2\"/>\n<path d=\"M24 36 Q30 28 36 36 Z\" fill=\"#3a8fd9\"/><circle cx=\"30\" cy=\"30\" r=\"4\" fill=\"#ffc93c\"/></g></svg>`,\n};\n\n// The net thrown in a catch (viewBox 100 x 100): a woven round net with a drawstring.\nArt.net = () => `<svg viewBox=\"0 0 100 100\" xmlns=\"http://www.w3.org/2000/svg\"><g stroke=\"${INK}\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n<path d=\"M10 40 Q50 -6 90 40 Q82 86 50 92 Q18 86 10 40Z\" fill=\"rgba(242,217,160,.55)\"/>\n<path d=\"M18 30 Q50 52 82 30 M12 48 Q50 70 88 48 M20 66 Q50 84 80 66 M34 14 Q40 52 36 88 M50 8 Q54 52 50 92 M66 14 Q60 52 64 88\" fill=\"none\" stroke-width=\"2\"/>\n<circle cx=\"50\" cy=\"8\" r=\"6\" fill=\"#3a8fd9\"/></g></svg>`;\n\nArt.props.SACK = () => `<svg viewBox=\"0 0 60 80\" xmlns=\"http://www.w3.org/2000/svg\"><ellipse cx=\"30\" cy=\"62\" rx=\"15\" ry=\"5\" fill=\"#000\" opacity=\".25\"/>\n<g stroke=\"${INK}\" stroke-width=\"3.2\" stroke-linejoin=\"round\" stroke-linecap=\"round\"><path d=\"M16 60 Q10 44 22 34 L38 34 Q50 44 44 60 Z\" fill=\"#c9965a\"/>\n<path d=\"M22 34 Q30 26 38 34 Z\" fill=\"#b07a42\"/><path d=\"M24 32 L36 32\" stroke=\"#ffc93c\" stroke-width=\"3\"/><path d=\"M26 46 H34\" stroke-width=\"2.4\"/></g></svg>`;\n\nArt.props.FRUIT_TREE = () => `<svg viewBox=\"0 0 60 80\" xmlns=\"http://www.w3.org/2000/svg\"><ellipse cx=\"30\" cy=\"70\" rx=\"20\" ry=\"6\" fill=\"#000\" opacity=\".22\"/>\n<g stroke=\"${INK}\" stroke-width=\"3.2\" stroke-linejoin=\"round\" stroke-linecap=\"round\"><rect x=\"25\" y=\"46\" width=\"10\" height=\"24\" rx=\"3\" fill=\"#9a6a3a\"/>\n<circle cx=\"30\" cy=\"30\" r=\"24\" fill=\"#2f9b4a\"/><circle cx=\"20\" cy=\"20\" r=\"8\" fill=\"#4fc467\" stroke=\"none\"/>\n<circle cx=\"22\" cy=\"34\" r=\"4.5\" fill=\"#ff6b5e\" stroke-width=\"2\"/><circle cx=\"38\" cy=\"26\" r=\"4.5\" fill=\"#ff6b5e\" stroke-width=\"2\"/><circle cx=\"34\" cy=\"40\" r=\"4.5\" fill=\"#ff6b5e\" stroke-width=\"2\"/></g></svg>`;\n\n/* page/hd/art/room.js */\n// The player's bedroom: an 8 x 6 grid, one cell = 100 units. Layout mirrors the\n// game's collision: PC and radio on the desk (2,1)-(3,1), TV (4,1) with console\n// (4,2), bookshelf (5,1), stairs (7,0), table (4,4)-(5,4), bed (0,4)-(0,5).\nArt.room = function () {\n  const o = `stroke=\"${INK}\" stroke-width=\"5\" stroke-linejoin=\"round\" stroke-linecap=\"round\"`;\n  let planks = \"\";\n  for (let i = 1; i < 12; i++) planks += `<path d=\"M0 ${100 + i * 42} H800\" stroke=\"#c98d4a\" stroke-width=\"2\" opacity=\".45\"/>`;\n  return `<svg class=\"room-svg\" viewBox=\"-20 -20 840 640\" xmlns=\"http://www.w3.org/2000/svg\">\n<defs>\n<linearGradient id=\"fl\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0\" stop-color=\"#f0be78\"/><stop offset=\"1\" stop-color=\"#d99a54\"/></linearGradient>\n<linearGradient id=\"wl\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0\" stop-color=\"#3b57b0\"/><stop offset=\"1\" stop-color=\"#27408a\"/></linearGradient>\n<linearGradient id=\"bed\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"0\"><stop offset=\"0\" stop-color=\"#ff8a6b\"/><stop offset=\"1\" stop-color=\"#e5604a\"/></linearGradient>\n<radialGradient id=\"lamp\"><stop offset=\"0\" stop-color=\"#ffe9a8\" stop-opacity=\".55\"/><stop offset=\"1\" stop-color=\"#ffe9a8\" stop-opacity=\"0\"/></radialGradient>\n</defs>\n<rect x=\"0\" y=\"0\" width=\"800\" height=\"600\" rx=\"10\" fill=\"url(#fl)\"/>${planks}\n<rect x=\"0\" y=\"0\" width=\"800\" height=\"110\" fill=\"url(#wl)\"/>\n<g stroke=\"#4a68c8\" stroke-width=\"2\" opacity=\".5\">${Array.from({ length: 16 }, (_, i) => `<path d=\"M${25 + i * 50} 0 V100\"/>`).join(\"\")}</g>\n<rect x=\"0\" y=\"96\" width=\"800\" height=\"16\" fill=\"#f4e3c1\" ${o}/>\n<rect x=\"-6\" y=\"-6\" width=\"812\" height=\"612\" rx=\"12\" fill=\"none\" stroke=\"${INK}\" stroke-width=\"12\"/>\n<!-- window -->\n<g ${o}><rect x=\"40\" y=\"14\" width=\"110\" height=\"74\" rx=\"6\" fill=\"#0c1a44\"/><path d=\"M95 14 V88 M40 51 H150\" stroke=\"${INK}\" stroke-width=\"5\"/>\n<circle cx=\"72\" cy=\"36\" r=\"9\" fill=\"#ffd35a\" stroke=\"none\"/><circle cx=\"120\" cy=\"66\" r=\"2.5\" fill=\"#fff\" stroke=\"none\"/><circle cx=\"62\" cy=\"68\" r=\"2\" fill=\"#fff\" stroke=\"none\"/></g>\n<!-- poster -->\n<g ${o} transform=\"translate(600 10)\"><rect width=\"90\" height=\"76\" rx=\"5\" fill=\"#fff4d6\"/><path d=\"M10 62 L32 30 L48 50 L60 38 L82 62 Z\" fill=\"#46c26f\"/><circle cx=\"66\" cy=\"22\" r=\"9\" fill=\"#ffc93c\"/></g>\n<!-- stairs -->\n<g ${o}><rect x=\"710\" y=\"6\" width=\"84\" height=\"94\" rx=\"6\" fill=\"#0c1a44\"/><path d=\"M718 30 H786 M718 52 H786 M718 74 H786\" stroke=\"#6f86d6\" stroke-width=\"5\"/><path d=\"M752 82 l-12 -14 h24 z\" fill=\"#ffc93c\" stroke=\"${INK}\" stroke-width=\"3\"/></g>\n<!-- rug -->\n<ellipse cx=\"400\" cy=\"320\" rx=\"230\" ry=\"96\" fill=\"#2fae6b\" ${o} opacity=\".92\"/><ellipse cx=\"400\" cy=\"320\" rx=\"196\" ry=\"74\" fill=\"none\" stroke=\"#7be8a0\" stroke-width=\"5\" stroke-dasharray=\"14 10\"/>\n<!-- shadows -->\n<g fill=\"#000\" opacity=\".16\"><ellipse cx=\"270\" cy=\"212\" rx=\"120\" ry=\"14\"/><ellipse cx=\"610\" cy=\"212\" rx=\"58\" ry=\"14\"/></g>\n<!-- desk with PC + radio (x 2-3, y 1) -->\n<g ${o}>\n<rect x=\"198\" y=\"118\" width=\"206\" height=\"92\" rx=\"8\" fill=\"#b8763a\"/><rect x=\"208\" y=\"128\" width=\"186\" height=\"14\" fill=\"#d79a5a\" stroke=\"none\"/>\n<rect x=\"214\" y=\"68\" width=\"82\" height=\"62\" rx=\"8\" fill=\"#e9eef8\"/><rect x=\"224\" y=\"76\" width=\"62\" height=\"42\" rx=\"4\" fill=\"#1b2d6b\"/><path d=\"M232 90 H268 M232 100 H256\" stroke=\"#7be8a0\" stroke-width=\"4\"/>\n<rect x=\"222\" y=\"148\" width=\"70\" height=\"20\" rx=\"4\" fill=\"#e9eef8\"/>\n<rect x=\"318\" y=\"108\" width=\"72\" height=\"50\" rx=\"8\" fill=\"#ff6b5e\"/><circle cx=\"342\" cy=\"134\" r=\"14\" fill=\"#ffe0dc\"/><path d=\"M366 120 H382 M366 134 H382 M366 148 H382\" stroke=\"${INK}\" stroke-width=\"3\"/>\n<path d=\"M206 210 V224 M396 210 V224\" stroke-width=\"8\"/>\n</g>\n<!-- TV + console (x 4, y 1-2) -->\n<g ${o}>\n<rect x=\"416\" y=\"62\" width=\"86\" height=\"130\" rx=\"10\" fill=\"#3a56b0\"/><rect x=\"426\" y=\"72\" width=\"66\" height=\"52\" rx=\"6\" fill=\"#0c1a44\"/><path d=\"M432 84 L486 112\" stroke=\"#6f86d6\" stroke-width=\"4\" opacity=\".6\"/>\n<rect x=\"428\" y=\"140\" width=\"62\" height=\"40\" rx=\"6\" fill=\"#e9eef8\"/><circle cx=\"446\" cy=\"160\" r=\"7\" fill=\"#ff6b5e\"/><rect x=\"460\" y=\"152\" width=\"22\" height=\"16\" rx=\"3\" fill=\"#7be8a0\"/>\n<rect x=\"424\" y=\"214\" width=\"70\" height=\"40\" rx=\"8\" fill=\"#6f86d6\"/><circle cx=\"446\" cy=\"234\" r=\"8\" fill=\"#ffd35a\"/><path d=\"M470 226 v16 M462 234 h16\" stroke=\"${INK}\" stroke-width=\"4\"/>\n</g>\n<!-- bookshelf (x 5, y 1) -->\n<g ${o}>\n<rect x=\"516\" y=\"52\" width=\"86\" height=\"148\" rx=\"8\" fill=\"#b8763a\"/>\n<rect x=\"526\" y=\"64\" width=\"66\" height=\"38\" fill=\"#7a4a1e\" stroke=\"none\"/><rect x=\"526\" y=\"112\" width=\"66\" height=\"38\" fill=\"#7a4a1e\" stroke=\"none\"/>\n<g stroke-width=\"3\"><rect x=\"530\" y=\"68\" width=\"12\" height=\"32\" fill=\"#e04a4a\"/><rect x=\"544\" y=\"72\" width=\"12\" height=\"28\" fill=\"#46c26f\"/><rect x=\"558\" y=\"66\" width=\"12\" height=\"34\" fill=\"#ffc93c\"/><rect x=\"572\" y=\"72\" width=\"14\" height=\"28\" fill=\"#4fb6d9\"/>\n<rect x=\"530\" y=\"118\" width=\"16\" height=\"30\" fill=\"#ffc93c\"/><rect x=\"548\" y=\"114\" width=\"12\" height=\"34\" fill=\"#e04a4a\"/><rect x=\"562\" y=\"120\" width=\"22\" height=\"28\" fill=\"#6f86d6\"/></g>\n<rect x=\"526\" y=\"160\" width=\"66\" height=\"30\" fill=\"#7a4a1e\" stroke=\"none\"/><circle cx=\"560\" cy=\"174\" r=\"11\" fill=\"#7be8a0\" stroke-width=\"3\"/>\n</g>\n<!-- table (x 4-5, y 4) -->\n<g ${o}>\n<rect x=\"408\" y=\"410\" width=\"204\" height=\"74\" rx=\"10\" fill=\"#c98446\"/><rect x=\"418\" y=\"418\" width=\"184\" height=\"12\" fill=\"#e2a468\" stroke=\"none\"/>\n<path d=\"M424 484 V510 M596 484 V510\" stroke-width=\"9\"/>\n<rect x=\"440\" y=\"436\" width=\"46\" height=\"30\" rx=\"6\" fill=\"#ffe0dc\" stroke-width=\"4\"/>\n<circle cx=\"548\" cy=\"448\" r=\"20\" fill=\"#fff4d6\" stroke-width=\"4\"/><path d=\"M548 428 v-14\" stroke-width=\"4\"/>\n</g>\n<!-- bed (x 0, y 4-5) -->\n<g ${o}>\n<rect x=\"6\" y=\"404\" width=\"98\" height=\"190\" rx=\"12\" fill=\"url(#bed)\"/>\n<rect x=\"14\" y=\"412\" width=\"82\" height=\"52\" rx=\"12\" fill=\"#fff4d6\"/>\n<path d=\"M6 480 Q55 462 104 480\" fill=\"none\" stroke=\"#ffd0c4\" stroke-width=\"5\"/>\n</g>\n<ellipse cx=\"260\" cy=\"150\" rx=\"190\" ry=\"110\" fill=\"url(#lamp)\"/>\n</svg>`;\n};\n\n/* page/hd/art/room1F.js */\n// Player's house, ground floor: 10 x 8 cells of 100 units. Blocked cells (from the game's collision data):\n// kitchen counters (0..3,1) with the divider (3,1..3), TV (4,1), cabinet (5,1), table (5..6,3..4).\n// Stairs (9,0), front door mat (6..7,7).\nArt.room1F = function () {\n  const o = `stroke=\"${INK}\" stroke-width=\"5\" stroke-linejoin=\"round\" stroke-linecap=\"round\"`;\n  let planks = \"\";\n  for (let i = 1; i < 19; i++) planks += `<path d=\"M0 ${100 + i * 38} H1000\" stroke=\"#c98d4a\" stroke-width=\"2\" opacity=\".45\"/>`;\n  return `<svg class=\"room-svg\" viewBox=\"-20 -20 1040 840\" xmlns=\"http://www.w3.org/2000/svg\">\n<defs>\n<linearGradient id=\"fl1\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0\" stop-color=\"#f0be78\"/><stop offset=\"1\" stop-color=\"#d99a54\"/></linearGradient>\n<linearGradient id=\"wl1\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0\" stop-color=\"#ffd9a0\"/><stop offset=\"1\" stop-color=\"#f2b872\"/></linearGradient>\n</defs>\n<rect x=\"0\" y=\"0\" width=\"1000\" height=\"800\" rx=\"10\" fill=\"url(#fl1)\"/>${planks}\n<rect x=\"0\" y=\"0\" width=\"1000\" height=\"110\" fill=\"url(#wl1)\"/>\n<g stroke=\"#e8a45c\" stroke-width=\"2\" opacity=\".6\">${Array.from({ length: 20 }, (_, i) => `<path d=\"M${25 + i * 50} 0 V100\"/>`).join(\"\")}</g>\n<rect x=\"0\" y=\"96\" width=\"1000\" height=\"16\" fill=\"#fff6dc\" ${o}/>\n<rect x=\"-6\" y=\"-6\" width=\"1012\" height=\"812\" rx=\"12\" fill=\"none\" stroke=\"${INK}\" stroke-width=\"12\"/>\n<!-- windows -->\n<g ${o}><rect x=\"610\" y=\"14\" width=\"120\" height=\"74\" rx=\"6\" fill=\"#8fd3ff\"/><path d=\"M670 14 V88 M610 51 H730\" stroke-width=\"5\"/>\n  <rect x=\"60\" y=\"14\" width=\"100\" height=\"74\" rx=\"6\" fill=\"#8fd3ff\"/><path d=\"M110 14 V88 M60 51 H160\" stroke-width=\"5\"/></g>\n<!-- stairs up (9,0) -->\n<g ${o}><rect x=\"910\" y=\"6\" width=\"84\" height=\"94\" rx=\"6\" fill=\"#7a4a1e\"/><path d=\"M918 30 H986 M918 52 H986 M918 74 H986\" stroke=\"#d79a5a\" stroke-width=\"5\"/><path d=\"M952 82 l-12 -14 h24 z\" fill=\"#ffc93c\" stroke-width=\"3\"/></g>\n<!-- door mat (6..7,7) -->\n<g ${o}><rect x=\"612\" y=\"716\" width=\"176\" height=\"76\" rx=\"12\" fill=\"#d63a4a\"/><rect x=\"626\" y=\"728\" width=\"148\" height=\"52\" rx=\"8\" fill=\"none\" stroke=\"#ffd0c4\" stroke-width=\"4\" stroke-dasharray=\"12 8\"/></g>\n<!-- kitchen counters: stove, sink, fridge (0..2,1) -->\n<g ${o}>\n  <rect x=\"6\" y=\"110\" width=\"94\" height=\"94\" rx=\"8\" fill=\"#e9eef8\"/><circle cx=\"36\" cy=\"140\" r=\"14\" fill=\"#3a3f52\"/><circle cx=\"72\" cy=\"140\" r=\"14\" fill=\"#3a3f52\"/><rect x=\"20\" y=\"170\" width=\"66\" height=\"20\" rx=\"4\" fill=\"#ffc93c\"/>\n  <rect x=\"100\" y=\"110\" width=\"100\" height=\"94\" rx=\"8\" fill=\"#c98446\"/><rect x=\"118\" y=\"124\" width=\"64\" height=\"40\" rx=\"10\" fill=\"#8fd3ff\"/><path d=\"M150 124 v-22 h18\" fill=\"none\" stroke-width=\"6\"/>\n  <rect x=\"200\" y=\"40\" width=\"96\" height=\"164\" rx=\"10\" fill=\"#cfe9ff\"/><path d=\"M200 112 H296\" /><rect x=\"272\" y=\"62\" width=\"10\" height=\"34\" rx=\"4\" fill=\"#fff\"/><rect x=\"272\" y=\"130\" width=\"10\" height=\"46\" rx=\"4\" fill=\"#fff\"/>\n  <!-- divider counter (3,1..3) -->\n  <rect x=\"300\" y=\"116\" width=\"96\" height=\"300\" rx=\"10\" fill=\"#c98446\"/><rect x=\"312\" y=\"128\" width=\"72\" height=\"14\" fill=\"#e2a468\" stroke=\"none\"/>\n  <circle cx=\"348\" cy=\"200\" r=\"16\" fill=\"#fff6dc\"/><rect x=\"326\" y=\"270\" width=\"44\" height=\"30\" rx=\"6\" fill=\"#ff6b5e\"/>\n</g>\n<!-- TV (4,1) -->\n<g ${o}><rect x=\"406\" y=\"48\" width=\"96\" height=\"150\" rx=\"10\" fill=\"#3a56b0\"/><rect x=\"416\" y=\"58\" width=\"76\" height=\"62\" rx=\"6\" fill=\"#0c1a44\"/><path d=\"M424 70 L484 106\" stroke=\"#6f86d6\" stroke-width=\"4\" opacity=\".6\"/>\n  <rect x=\"418\" y=\"136\" width=\"72\" height=\"46\" rx=\"6\" fill=\"#e9eef8\"/><circle cx=\"440\" cy=\"160\" r=\"8\" fill=\"#ff6b5e\"/><rect x=\"456\" y=\"150\" width=\"26\" height=\"20\" rx=\"3\" fill=\"#7be8a0\"/></g>\n<!-- cabinet with plant (5,1) -->\n<g ${o}><rect x=\"512\" y=\"104\" width=\"86\" height=\"100\" rx=\"8\" fill=\"#b8763a\"/><rect x=\"520\" y=\"112\" width=\"70\" height=\"40\" fill=\"#7a4a1e\" stroke=\"none\"/>\n  <path d=\"M555 104 C520 80 520 50 548 40 C556 66 566 80 555 104 Z M555 104 C590 84 598 56 574 38 C560 62 552 84 555 104 Z\" fill=\"#46c26f\" stroke-width=\"4\"/><rect x=\"535\" y=\"92\" width=\"40\" height=\"24\" rx=\"5\" fill=\"#ff8a6b\" stroke-width=\"4\"/></g>\n<!-- table (5..6,3..4) -->\n<g fill=\"#000\" opacity=\".16\"><ellipse cx=\"600\" cy=\"512\" rx=\"120\" ry=\"14\"/></g>\n<g ${o}><rect x=\"506\" y=\"312\" width=\"188\" height=\"188\" rx=\"16\" fill=\"#c98446\"/><rect x=\"522\" y=\"326\" width=\"156\" height=\"160\" rx=\"10\" fill=\"#ff8fa3\" opacity=\".85\" stroke-width=\"3\"/>\n  <circle cx=\"600\" cy=\"406\" r=\"42\" fill=\"#fff6dc\" stroke-width=\"4\"/><circle cx=\"600\" cy=\"406\" r=\"22\" fill=\"#ffc93c\" stroke-width=\"3\"/></g>\n</svg>`;\n};\n\n/* page/hd/art/sky.js */\n// Night sky with a big golden moon and layered hills. `dim` darkens it for menus.\nArt.sky = function () {\n  let stars = \"\";\n  let seed = 7;\n  const rnd = () => ((seed = (seed * 16807) % 2147483647) / 2147483647);\n  for (let i = 0; i < 70; i++) {\n    const x = rnd() * 1000, y = rnd() * 520, r = 1 + rnd() * 2.4;\n    stars += `<circle class=\"star\" style=\"animation-delay:${(rnd() * 4).toFixed(2)}s\" cx=\"${x.toFixed(0)}\" cy=\"${y.toFixed(0)}\" r=\"${r.toFixed(1)}\" fill=\"#fff6dc\"/>`;\n  }\n  return `<svg class=\"sky-svg\" viewBox=\"0 0 1000 900\" preserveAspectRatio=\"xMidYMid slice\" xmlns=\"http://www.w3.org/2000/svg\">\n<defs>\n<linearGradient id=\"sk\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0\" stop-color=\"#050a22\"/><stop offset=\".55\" stop-color=\"#1b2d6b\"/><stop offset=\".85\" stop-color=\"#5a4a8c\"/><stop offset=\"1\" stop-color=\"#e98a58\"/></linearGradient>\n<radialGradient id=\"moon-glow\"><stop offset=\"0\" stop-color=\"#ffd35a\" stop-opacity=\".55\"/><stop offset=\"1\" stop-color=\"#ffd35a\" stop-opacity=\"0\"/></radialGradient>\n<linearGradient id=\"moon\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"1\"><stop offset=\"0\" stop-color=\"#fff1b0\"/><stop offset=\"1\" stop-color=\"#ffb62e\"/></linearGradient>\n<linearGradient id=\"h1\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0\" stop-color=\"#3a3f86\"/><stop offset=\"1\" stop-color=\"#252a64\"/></linearGradient>\n<linearGradient id=\"h2\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0\" stop-color=\"#27346f\"/><stop offset=\"1\" stop-color=\"#17214f\"/></linearGradient>\n<linearGradient id=\"h3\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0\" stop-color=\"#1b7a5a\"/><stop offset=\"1\" stop-color=\"#0d4237\"/></linearGradient>\n</defs>\n<rect width=\"1000\" height=\"900\" fill=\"url(#sk)\"/>\n${stars}\n<circle cx=\"500\" cy=\"330\" r=\"330\" fill=\"url(#moon-glow)\"/>\n<circle cx=\"500\" cy=\"330\" r=\"150\" fill=\"url(#moon)\" stroke=\"${INK}\" stroke-width=\"6\"/>\n<circle cx=\"455\" cy=\"290\" r=\"26\" fill=\"#ffc94a\" opacity=\".55\"/><circle cx=\"548\" cy=\"372\" r=\"18\" fill=\"#ffc94a\" opacity=\".5\"/><circle cx=\"520\" cy=\"270\" r=\"11\" fill=\"#ffc94a\" opacity=\".5\"/>\n<g class=\"clouds\"><path d=\"M80 210 q30 -40 70 -10 q40 -30 70 10 z\" fill=\"#fff\" opacity=\".12\"/><path d=\"M700 160 q30 -40 70 -10 q40 -30 70 10 z\" fill=\"#fff\" opacity=\".12\"/></g>\n<path d=\"M0 640 C150 560 270 600 400 560 C560 510 720 590 1000 540 L1000 900 L0 900 Z\" fill=\"url(#h1)\" stroke=\"${INK}\" stroke-width=\"5\"/>\n<path d=\"M0 720 C180 650 330 700 520 650 C700 610 850 690 1000 660 L1000 900 L0 900 Z\" fill=\"url(#h2)\" stroke=\"${INK}\" stroke-width=\"5\"/>\n<path d=\"M0 800 C200 750 360 800 560 760 C760 725 880 790 1000 770 L1000 900 L0 900 Z\" fill=\"url(#h3)\" stroke=\"${INK}\" stroke-width=\"5\"/>\n</svg>`;\n};\n\n/* page/hd/art/terrain.js */\n// Outdoor terrain for the world scene, drawn per cell (100 x 100 units): ground, tall grass, trees, rocks, water, ledges, signs, flowers, doors.\n// Kinds used in map `cells`: . floor, g tall grass, T tree, c bush, r rock, w water, S sign, f flowers, p dirt path (an exit path carries on through the forest at the map edge), v ledge (jump down).\nArt.johto = (() => {\n  const o = `stroke=\"${INK}\" stroke-width=\"5\" stroke-linejoin=\"round\" stroke-linecap=\"round\"`;\n  const tufts = [[30, 40], [116, 30], [160, 86], [62, 124], [146, 160], [22, 176], [96, 92]]\n    .map(([x, y]) => `<path d=\"M${x} ${y} l-6 -10 M${x} ${y} l0 -13 M${x} ${y} l6 -10\"/>`).join(\"\");\n  const ground = `<rect x=\"-1\" y=\"-1\" width=\"202\" height=\"202\" fill=\"#86dc6f\"/><g stroke=\"#4fae57\" stroke-width=\"4\" stroke-linecap=\"round\" fill=\"none\">${tufts}</g>`;\n  const tree = (x, y) => `<g transform=\"translate(${x} ${y})\"><ellipse cx=\"50\" cy=\"92\" rx=\"34\" ry=\"8\" fill=\"#000\" opacity=\".2\"/>\n    <rect x=\"43\" y=\"66\" width=\"14\" height=\"28\" rx=\"3\" fill=\"#9a6a3a\" ${o}/><circle cx=\"50\" cy=\"42\" r=\"46\" fill=\"#2f9b4a\" ${o}/>\n    <circle cx=\"34\" cy=\"26\" r=\"15\" fill=\"#4fc467\"/><path d=\"M22 54 Q50 78 78 54\" fill=\"none\" stroke=\"#1f7a38\" stroke-width=\"5\" stroke-linecap=\"round\"/></g>`;\n  const bush = (x, y) => `<g transform=\"translate(${x} ${y})\"><ellipse cx=\"50\" cy=\"70\" rx=\"46\" ry=\"28\" fill=\"#3fae57\" ${o}/><ellipse cx=\"34\" cy=\"60\" rx=\"14\" ry=\"9\" fill=\"#6fd382\"/></g>`;\n  const sign = (x, y) => `<g transform=\"translate(${x} ${y})\"><rect x=\"44\" y=\"52\" width=\"12\" height=\"38\" rx=\"3\" fill=\"#9a6a3a\" ${o}/>\n    <rect x=\"16\" y=\"14\" width=\"68\" height=\"44\" rx=\"7\" fill=\"#e2a468\" ${o}/><path d=\"M28 28 H72 M28 42 H60\" stroke=\"${INK}\" stroke-width=\"4\" stroke-linecap=\"round\"/></g>`;\n  const flowers = [[44, 50, \"#ff6b5e\"], [120, 40, \"#fff6dc\"], [150, 120, \"#ffc93c\"], [60, 150, \"#ff9aa8\"], [100, 96, \"#fff6dc\"]]\n    .map(([x, y, c]) => `<circle cx=\"${x}\" cy=\"${y}\" r=\"9\" fill=\"${c}\" ${o} stroke-width=\"3\"/><circle cx=\"${x}\" cy=\"${y}\" r=\"3\" fill=\"#ffc93c\"/>`).join(\"\");\n  return { o, ground, tree, bush, sign, flowers };\n})();\n\nArt.johtoCell = (() => {\n  const { o, tree, bush } = Art.johto;\n  const tufts = [\n    [[18, 30], [64, 22], [80, 70], [30, 78]],\n    [[40, 26], [84, 40], [22, 66], [66, 82]],\n    [[24, 20], [58, 54], [86, 82], [14, 84]],\n  ];\n  const ground = (v = 0) => `<rect x=\"-1\" y=\"-1\" width=\"102\" height=\"102\" fill=\"#86dc6f\"/><g stroke=\"#4fae57\" stroke-width=\"3.5\" stroke-linecap=\"round\" fill=\"none\">${\n    tufts[v % 3].map(([x, y]) => `<path d=\"M${x} ${y} l-5 -8 M${x} ${y} l0 -11 M${x} ${y} l5 -8\"/>`).join(\"\")}</g>`;\n  const tall = `<rect x=\"-1\" y=\"-1\" width=\"102\" height=\"102\" fill=\"#58b85c\"/><g stroke-linecap=\"round\" stroke-linejoin=\"round\" fill=\"none\">${\n    [[24, 44], [72, 40], [48, 70], [16, 86], [84, 90], [52, 22]]\n      .map(([x, y]) => `<path stroke=\"#1f6b34\" stroke-width=\"5\" d=\"M${x - 14} ${y + 14} Q${x - 10} ${y - 8} ${x - 2} ${y - 20} Q${x} ${y} ${x + 4} ${y - 24} Q${x + 8} ${y} ${x + 16} ${y - 16} Q${x + 14} ${y + 6} ${x + 14} ${y + 14}Z\" fill=\"#7be07a\" opacity=\".9\"/>`).join(\"\")}</g>`;\n  const dirt = `<rect x=\"-1\" y=\"-1\" width=\"102\" height=\"102\" fill=\"#e3c88f\"/><g stroke=\"#c9a96a\" stroke-width=\"3.5\" stroke-linecap=\"round\" fill=\"none\"><path d=\"M14 30 h12 M60 22 h14 M30 70 h14 M72 78 h12 M52 50 h8\"/></g>`;\n  const rock = `<ellipse cx=\"50\" cy=\"86\" rx=\"38\" ry=\"8\" fill=\"#000\" opacity=\".2\"/><ellipse cx=\"50\" cy=\"58\" rx=\"44\" ry=\"36\" fill=\"#aeb6c8\" ${o}/><ellipse cx=\"36\" cy=\"44\" rx=\"14\" ry=\"9\" fill=\"#d5dbe8\"/><path d=\"M60 66 q10 6 22 -2\" fill=\"none\" stroke=\"#8791aa\" stroke-width=\"4\" stroke-linecap=\"round\"/>`;\n  const sandSide = `<path d=\"M-2 -2 H102 V20 Q76 34 50 20 T-2 20Z\" fill=\"#f2d9a0\" ${o} stroke-width=\"3\"/>`;\n  const water = (mask) => `<rect x=\"-1\" y=\"-1\" width=\"102\" height=\"102\" fill=\"#4fb6d9\"/><g stroke=\"#9fe0f4\" stroke-width=\"4\" stroke-linecap=\"round\" fill=\"none\"><path d=\"M18 40 q10 -8 20 0 t20 0\"/><path d=\"M40 78 q10 -8 20 0 t20 0\"/></g>${\n    [[1, 0], [2, 90], [4, 180], [8, 270]].map(([bit, deg]) => (mask & bit ? `<g transform=\"rotate(${deg} 50 50)\">${sandSide}</g>` : \"\")).join(\"\")}`;\n  const lip = (x, y, w, h) => `<rect x=\"${x}\" y=\"${y}\" width=\"${w}\" height=\"${h}\" rx=\"9\" fill=\"#b8a07a\" ${o}/><rect x=\"${x + 6}\" y=\"${y + 4}\" width=\"${Math.max(w - 12, 4)}\" height=\"5\" rx=\"2\" fill=\"#dccaa0\"/>`;\n  const ledge = { v: lip(-2, 68, 104, 24), \"<\": lip(2, -2, 24, 104), \">\": lip(74, -2, 24, 104), L: lip(-2, 68, 104, 24) + lip(2, -2, 24, 76), R: lip(-2, 68, 104, 24) + lip(74, -2, 24, 76) };\n\n  return (kind, mask = 0, v = 0) => {\n    switch (kind) {\n      case \"g\": return tall;\n      case \"p\": return dirt;\n      case \"S\": return ground(v) + Art.johto.sign(0, 0);\n      case \"f\": return ground(v) + `<g ${o} stroke-width=\"3\"><circle cx=\"28\" cy=\"40\" r=\"9\" fill=\"#ff6b5e\"/><circle cx=\"68\" cy=\"30\" r=\"9\" fill=\"#fff6dc\"/><circle cx=\"56\" cy=\"72\" r=\"9\" fill=\"#ffc93c\"/><circle cx=\"20\" cy=\"80\" r=\"8\" fill=\"#ff9aa8\"/></g>`;\n      case \"T\": return ground(v) + tree(0, 0);\n      case \"c\": return ground(v) + bush(0, 0);\n      case \"r\": return ground(v) + rock;\n      case \"w\": return water(mask);\n      case \"v\": case \"<\": case \">\": case \"L\": case \"R\": return ground(v) + ledge[kind];\n      default: return ground(v);\n    }\n  };\n})();\n\n// A door on a building wall: drawn over the wall block at each DOOR cell of the map.\nArt.johtoDoor = () => {\n  const { o } = Art.johto;\n  return `<rect x=\"18\" y=\"86\" width=\"64\" height=\"12\" rx=\"3\" fill=\"#c9c3b5\" ${o} stroke-width=\"3\"/>\n    <path d=\"M24 88 V32 Q50 4 76 32 V88Z\" fill=\"#9a6a3a\" ${o}/><circle cx=\"66\" cy=\"60\" r=\"4.5\" fill=\"#ffc93c\"/>`;\n};\n\n/* page/hd/art/willowHouse.js */\n// Willow's house, 8 x 8 cells: PC (0,1), TV (4,1), shelves (6..7,1), table (3..4,3..4), door (2..3,7).\nArt.willowHouse = function () {\n  const f = Art.furniture;\n  return Art.shell(8, 8, \"house\") + f.window(200) + f.pc(0, 120) + f.tv(400, 30) + f.plant(500, 110) + f.shelf(600, 40, 200, 160) +\n    f.rug(400, 580, 220, 80) + f.table(300, 300, 200, 200) + f.mat(200, 700, 200) + Art.roomEnd;\n};\n\n/* page/hd/art/willowLab.js */\n// Willow's lab, 10 x 12 cells: machine + counters (0..3,1..2), shelves (6..9,1), ball table (6..9,3), divider wall + shelves (rows 6-7), door (4..5,11).\nArt.willowLab = function () {\n  const f = Art.furniture;\n  return Art.shell(10, 12, \"lab\") + f.window(400) +\n    f.counter(0, 110, 400, 90) + f.counter(0, 200, 200, 90) + f.machine(200, 56) +\n    f.shelf(600, 40, 400, 160) + f.table(600, 290, 400, 110, \"#b9c6e8\", false) + f.trash(900, 290) +\n    `<rect x=\"0\" y=\"600\" width=\"400\" height=\"100\" fill=\"#6fb3d4\" stroke=\"${INK}\" stroke-width=\"5\"/><rect x=\"600\" y=\"600\" width=\"400\" height=\"100\" fill=\"#6fb3d4\" stroke=\"${INK}\" stroke-width=\"5\"/>` +\n    f.shelf(0, 620, 400, 180) + f.shelf(600, 620, 400, 180) + f.rug(500, 930, 300, 90) + f.mat(400, 1100, 200) + Art.roomEnd;\n};\n\n/* page/hd/art/world.js */\n// A whole outdoor map as one SVG (cell = 100 units): terrain per cell, buildings on top, then `margin` cells of forest all round.\n// world = { cols, rows, cells: [rows of kind chars], buildings: [{x, y, w, h, roof, wall, label, door}] } (kinds: see art/terrain.js).\nArt.world = function (world, margin) {\n  const W = world.cols + margin * 2, H = world.rows + margin * 2;\n  const kindAt = (x, y) => {\n    if (x >= 0 && x < world.cols && y >= 0 && y < world.rows) return world.cells[y][x];\n    const edge = world.cells[Math.min(Math.max(y, 0), world.rows - 1)][Math.min(Math.max(x, 0), world.cols - 1)];\n    return edge === \"p\" ? \"p\" : \"T\"; // a dirt path on the edge carries on out of the map so exits can be seen\n  };\n  const dry = (k) => k !== \"w\" && k !== \"r\"; // sand shows where water meets land\n  const symbols = new Map();\n  let uses = \"\";\n  for (let y = -margin; y < world.rows + margin; y++) {\n    for (let x = -margin; x < world.cols + margin; x++) {\n      const kind = kindAt(x, y);\n      const mask = kind === \"w\" ? (dry(kindAt(x, y - 1)) ? 1 : 0) | (dry(kindAt(x + 1, y)) ? 2 : 0) | (dry(kindAt(x, y + 1)) ? 4 : 0) | (dry(kindAt(x - 1, y)) ? 8 : 0) : 0;\n      const v = ((x * 3 + y * 5) % 3 + 3) % 3;\n      const id = `c${kind}${mask}${v}`;\n      if (!symbols.has(id)) symbols.set(id, `<symbol id=\"${id}\" viewBox=\"0 0 100 100\" overflow=\"visible\">${Art.johtoCell(kind, mask, v)}</symbol>`);\n      uses += `<use href=\"#${id}\" x=\"${(x + margin) * 100}\" y=\"${(y + margin) * 100}\" width=\"100\" height=\"100\"/>`;\n    }\n  }\n  const buildings = (world.buildings || []).map((b) => Art.building({ ...b, x: b.x + margin, y: b.y + margin })).join(\"\");\n  return `<svg class=\"world-svg\" viewBox=\"0 0 ${W * 100} ${H * 100}\" xmlns=\"http://www.w3.org/2000/svg\"><defs>${[...symbols.values()].join(\"\")}</defs>${uses}${buildings}</svg>`;\n};\n\n/* page/hd/scenes/battle.js */\n// Battle screen. Moves animate from state.battle.fx = { n, who, type, kind } (attacker lunges, the target gets a type-coloured burst or a stat arrow);\n// the player's card shows an EXP bar from me.xp (0..1). state.battle = { foe, me: { species, name, level, hp, max }, menu: { kind, cols, items: [{label, sel}] } | null, net: { shakes, caught } | null }.\n// Menu buttons answer taps through Game.pick(index); messages use the shared dialogue box.\nScenes.battle = function (root) {\n  const el = h(`<div class=\"scene battle\">\n    <div class=\"bt-bg\"></div>\n    <div class=\"bt-side foe\"><i class=\"plat\"></i><div class=\"mon\"></div><div class=\"bt-net\" hidden>${Art.net()}</div><div class=\"fx\"></div></div>\n    <div class=\"bt-side me\"><i class=\"plat\"></i><div class=\"mon\"></div><div class=\"fx\"></div></div>\n    <div class=\"bt-card foe\"><b class=\"nm\"></b><i class=\"gd\"></i><span class=\"lv\"></span><div class=\"hp\"><i></i></div></div>\n    <div class=\"bt-card me\"><b class=\"nm\"></b><i class=\"gd\"></i><span class=\"lv\"></span><div class=\"hp\"><i></i></div><span class=\"num\"></span><div class=\"xp\" title=\"EXP\"><i></i></div></div>\n    <div class=\"bt-menu\" hidden></div>\n  </div>`);\n  root.appendChild(el);\n  const dlg = dialogue(el);\n  const menus = popups(el);\n  const side = (cls) => ({ mon: el.querySelector(`.bt-side.${cls} .mon`), card: el.querySelector(`.bt-card.${cls}`), fx: el.querySelector(`.bt-side.${cls} .fx`), species: null, hp: null });\n  const sides = { foe: side(\"foe\"), me: side(\"me\") };\n  const menu = el.querySelector(\".bt-menu\"), net = el.querySelector(\".bt-net\"), foeMon = sides.foe.mon;\n  let lastMenu = \"\", lastNet = null, lastFx = 0, lastLevel = 0;\n  const COLORS = { normal: \"#e8e0d0\", fire: \"#ff7a3c\", water: \"#4fb6ff\", grass: \"#6fd35a\", electric: \"#ffe03c\", dark: \"#7a5aa8\", flying: \"#a8c8ff\", poison: \"#b45ad9\", ground: \"#d9a860\", rock: \"#b8a078\", bug: \"#a8d83c\", ghost: \"#8a6ac8\", psychic: \"#ff7ab8\", ice: \"#9fe8ff\", fighting: \"#e0523c\", steel: \"#b8c4d8\", dragon: \"#6a5aff\" };\n  const burst = (c) => `<svg viewBox=\"-50 -50 100 100\"><g fill=\"${c}\" stroke=\"#14213d\" stroke-width=\"3\" stroke-linejoin=\"round\"><path d=\"M0 -44 L10 -14 L42 -18 L18 4 L34 38 L2 20 L-28 40 L-16 8 L-44 -12 L-10 -14Z\"/></g><circle r=\"9\" fill=\"#fff\"/></svg>`;\n  const arrows = (c, up) => `<svg viewBox=\"0 0 100 100\" class=\"${up ? \"up\" : \"down\"}\"><g fill=\"none\" stroke=\"${c}\" stroke-width=\"12\" stroke-linecap=\"round\" stroke-linejoin=\"round\">${[26, 52, 78].map((y) => `<path d=\"M26 ${up ? y + 10 : y - 10} L50 ${up ? y - 10 : y + 10} L74 ${up ? y + 10 : y - 10}\"/>`).join(\"\")}</g></svg>`;\n  const play = (fx) => {\n    const att = sides[fx.who], tgt = sides[fx.who === \"me\" ? \"foe\" : \"me\"];\n    att.mon.classList.remove(\"lunge-me\", \"lunge-foe\"); void att.mon.offsetWidth;\n    const target = fx.kind === \"hit\" ? tgt : fx.kind === \"up\" ? att : tgt;\n    if (fx.kind === \"hit\") att.mon.classList.add(`lunge-${fx.who}`);\n    const box = target.fx;\n    box.innerHTML = fx.kind === \"hit\" ? burst(COLORS[fx.type] || \"#fff\") : arrows(fx.kind === \"up\" ? \"#46c26f\" : \"#ff6b5e\", fx.kind === \"up\");\n    box.classList.remove(\"go\"); void box.offsetWidth; box.classList.add(\"go\");\n  };\n  menu.addEventListener(\"pointerdown\", (e) => { const b = e.target.closest(\"button\"); if (b) Game.pick(+b.dataset.i); });\n\n  const update = (who, mon) => {\n    const s = sides[who];\n    if (mon.species !== s.species) {\n      s.species = mon.species;\n      s.mon.innerHTML = Art.creature(mon.species);\n      s.mon.classList.remove(\"enter\"); void s.mon.offsetWidth; s.mon.classList.add(\"enter\");\n    }\n    if (s.hp !== null && mon.hp < s.hp) { s.mon.classList.remove(\"hit\"); void s.mon.offsetWidth; s.mon.classList.add(\"hit\"); }\n    s.hp = mon.hp;\n    s.mon.classList.toggle(\"faint\", mon.hp === 0);\n    s.card.querySelector(\".nm\").textContent = mon.name;\n    const gd = s.card.querySelector(\".gd\");\n    gd.textContent = mon.gender === \"F\" ? \"♀\" : mon.gender === \"M\" ? \"♂\" : \"\";\n    gd.className = `gd ${mon.gender === \"F\" ? \"f\" : \"m\"}`;\n    s.card.querySelector(\".lv\").textContent = `Lv ${mon.level}`;\n    const pct = mon.max ? Math.round((mon.hp / mon.max) * 100) : 0, bar = s.card.querySelector(\".hp i\");\n    bar.style.width = `${pct}%`;\n    bar.dataset.level = pct > 50 ? \"ok\" : pct > 20 ? \"warn\" : \"low\";\n    const xp = s.card.querySelector(\".xp i\");\n    if (xp) {\n      xp.style.transition = mon.level !== s.level ? \"none\" : \"\"; // the bar jumps back to empty on a level-up, it does not drain\n      xp.style.width = `${Math.round((mon.xp || 0) * 100)}%`;\n    }\n    s.level = mon.level;\n    const num = s.card.querySelector(\".num\");\n    if (num) num.textContent = `${mon.hp} / ${mon.max}`;\n  };\n\n  return {\n    update(state) {\n      const b = state.battle;\n      if (!b) return;\n      if (b.fx && b.fx.n !== lastFx) { lastFx = b.fx.n; play(b.fx); }\n      update(\"foe\", b.foe);\n      update(\"me\", b.me);\n      dlg.update(state.dialogue);\n      menus.update(state.boxes);\n      const nkey = JSON.stringify(b.net);\n      if (nkey !== lastNet) {\n        lastNet = nkey;\n        net.hidden = !b.net;\n        foeMon.classList.toggle(\"netted\", !!b.net);\n        if (b.net) { net.style.setProperty(\"--shakes\", b.net.shakes + 1); net.classList.remove(\"go\"); void net.offsetWidth; net.classList.add(\"go\"); }\n      }\n      const key = JSON.stringify(b.menu);\n      if (key === lastMenu) return;\n      lastMenu = key;\n      menu.hidden = !b.menu;\n      if (b.menu) {\n        menu.className = `bt-menu ${b.menu.kind} cols${b.menu.cols}`;\n        menu.innerHTML = b.menu.items.map((i, n) => `<button data-i=\"${n}\" class=\"${i.sel ? \"sel\" : \"\"}\">${esc(i.label)}</button>`).join(\"\");\n      }\n    },\n  };\n};\n\n/* page/hd/scenes/intro.js */\n// Opening cinematic: four 6s acts (sea, meadow, night, finale) timed by CSS from mount.\n// The ROM waits INTRO_FRAMES (engine/movie/hd_intro.asm) then moves on, so keep it <= 25s.\nScenes.intro = function (root) {\n  const many = (n, make) => Array.from({ length: n }, (_, i) => make(i)).join(\"\");\n  const el = h(`<div class=\"scene intro\">\n    <div class=\"act\" style=\"--i:0\">${Art.introSea()}\n      <div class=\"swim s1\">${Art.chomplet()}</div><div class=\"swim s2\">${Art.chomplet()}</div><div class=\"swim s3\">${Art.chomplet()}</div>\n      ${many(14, (i) => `<i class=\"bub\" style=\"--x:${(i * 71) % 96}cqw;--d:${(i % 5) * 0.7}s;--s:${1.4 + (i % 4)}cqw\"></i>`)}\n      <p class=\"cap\">Out in the deep blue…</p></div>\n    <div class=\"act\" style=\"--i:1\">${Art.introMeadow()}\n      <div class=\"roll\"><div>${Art.bramblet()}</div></div>\n      <p class=\"cap\">…across the green meadows…</p></div>\n    <div class=\"act\" style=\"--i:2\"><div class=\"nightbg\"></div>\n      <div class=\"pop\">${Art.bandit()}</div>\n      ${many(18, (i) => `<i class=\"ember\" style=\"--x:${30 + ((i * 23) % 40)}cqw;--d:${(i % 6) * 0.45}s\"></i>`)}\n      <p class=\"cap\">…under a golden moon…</p></div>\n    <div class=\"act\" style=\"--i:3\"><div class=\"burst\"></div>\n      <div class=\"jump j1\">${Art.bramblet()}</div><div class=\"jump j2\">${Art.bandit()}</div><div class=\"jump j3\">${Art.chomplet()}</div>\n      <p class=\"cap big\">…your adventure begins!</p></div>\n    <div class=\"skip\">Tap or press any button to skip</div>\n  </div>`);\n  el.querySelector(\".nightbg\").appendChild(h(`<div class=\"sky\">${Art.sky()}</div>`));\n  root.appendChild(el);\n  return { update() {} };\n};\n\n/* page/hd/scenes/menu.js */\n// Title menu: New Game / Continue. state.menu = { items: [{label, selected}], info }.\nScenes.menu = function (root) {\n  const el = h(`<div class=\"scene menu\">\n    <div class=\"logo small\">${Art.logo()}</div>\n    <ul class=\"menu-list\"></ul>\n    <div class=\"chip\" hidden></div>\n  </div>`);\n  el.prepend(sky());\n  root.appendChild(el);\n  const list = el.querySelector(\"ul\"), chip = el.querySelector(\".chip\");\n  let last = \"\";\n  return {\n    update(state) {\n      const key = JSON.stringify(state.menu);\n      if (key === last) return;\n      last = key;\n      list.innerHTML = state.menu.items.map((i) => `<li class=\"${i.selected ? \"sel\" : \"\"}\"><b></b>${i.label}</li>`).join(\"\");\n      chip.hidden = !state.menu.info;\n      chip.textContent = state.menu.info || \"\";\n    },\n  };\n};\n\n/* page/hd/scenes/prof.js */\n// Professor Willow's welcome talk. state.prof = { who: \"professor\" | \"hero\", species?: number }; text comes from state.dialogue.\nScenes.prof = function (root) {\n  const el = h(`<div class=\"scene prof\">\n    <div class=\"lab\"></div>\n    <div class=\"portrait\"></div>\n    <div class=\"creature\" hidden></div>\n  </div>`);\n  el.prepend(h(`<div class=\"sky warm\"></div>`));\n  root.appendChild(el);\n  const dlg = dialogue(el, \"PROF. WILLOW\");\n  const portrait = el.querySelector(\".portrait\"), creature = el.querySelector(\".creature\");\n  let who = null, shown = null;\n  return {\n    update(state) {\n      const { who: nextWho, species } = state.prof;\n      if (nextWho !== who) {\n        who = nextWho;\n        portrait.innerHTML = Art[who]();\n        dlg.setTag(who === \"hero\" ? (Game.player.name || \"YOU\") : \"PROF. WILLOW\");\n      }\n      dlg.update(state.dialogue);\n      if (species !== shown) {\n        shown = species;\n        creature.hidden = !shown;\n        creature.innerHTML = shown ? Art.creature(shown) : \"\";\n      }\n    },\n  };\n};\n\n/* page/hd/scenes/room.js */\n// Single-screen rooms, keyed by map key. Cell (x, y) is 100 art units; people are positioned from game state (ui/actors.js).\n// Rooms by map key; each game/ map file adds its own entry through Game.register (see game/core.js).\nconst ROOMS = {};\n\nScenes.room = function (root) {\n  const el = h(`<div class=\"scene room\"><div class=\"vignette\"></div><div class=\"room-wrap\"></div><div class=\"loc\"></div></div>`);\n  root.appendChild(el);\n  const wrap = el.querySelector(\".room-wrap\"), loc = el.querySelector(\".loc\");\n  const dlg = dialogue(el);\n  const menus = popups(el);\n  const pic = picLayer(el);\n  const panel = panelLayer(el);\n  let map = null, people = null;\n\n  const build = (key) => {\n    const room = ROOMS[key];\n    map = key;\n    wrap.innerHTML = Art[room.art]();\n    loc.textContent = room.label;\n    people = actorLayer(wrap, { w: room.cols * 100 + 40, h: room.rows * 100 + 40, ox: 20, oy: 20 });\n  };\n\n  return {\n    update(state) {\n      if (state.map.key !== map) build(state.map.key);\n      people.update(state);\n      // Rooms taller than the stage scroll to keep the hero in view.\n      const stageH = el.clientHeight, roomH = wrap.offsetHeight, view = stageH * 0.68;\n      if (roomH > view) {\n        const heroY = (parseFloat(people.hero.style.top) / 100) * roomH;\n        wrap.style.transform = \"translateX(-50%)\";\n        wrap.style.top = `${Math.min(stageH * 0.04, Math.max(view - roomH + stageH * 0.04, stageH * 0.34 - heroY))}px`;\n      } else { wrap.style.transform = \"\"; wrap.style.top = \"\"; }\n      dlg.update(state.dialogue);\n      menus.update(state.boxes);\n      pic.update(state.pic);\n      panel.update(state.panel);\n    },\n  };\n};\n\n/* page/hd/scenes/splash.js */\n// \"Brock Family Presents\" studio splash (~5.5s, driven by CSS timing from mount).\nScenes.splash = function (root) {\n  const word = (text, cls) => [...text].map((c, i) =>\n    c === \" \" ? `<i class=\"sp\"></i>` : `<span class=\"${cls}\" style=\"--i:${i}\">${c}</span>`).join(\"\");\n  const el = h(`<div class=\"scene splash\">\n    <div class=\"rays\"></div>\n    <div class=\"crest\">${Art.badger()}<i class=\"shine\"></i></div>\n    <div class=\"name\">${word(\"BROCK FAMILY\", \"ltr\")}</div>\n    <div class=\"presents\">${word(\"PRESENTS\", \"pl\")}</div>\n    ${Array.from({ length: 10 }, (_, i) => `<i class=\"spark\" style=\"--i:${i}\"></i>`).join(\"\")}\n  </div>`);\n  root.appendChild(el);\n  return { update() {} };\n};\n\n/* page/hd/scenes/title.js */\n// Title screen: logo, the three starters and \"PRESS START\".\nScenes.title = function (root) {\n  const el = h(`<div class=\"scene title\">\n    <div class=\"logo\">${Art.logo()}</div>\n    <div class=\"trio\">\n      <div class=\"mon m1\">${Art.bramblet()}</div><div class=\"mon m2\">${Art.bandit()}</div><div class=\"mon m3\">${Art.chomplet()}</div>\n    </div>\n    <div class=\"press\">PRESS START</div>\n  </div>`);\n  el.prepend(sky());\n  for (let i = 0; i < 14; i++) {\n    const f = h(`<i class=\"fly\" style=\"left:${(i * 73) % 100}%;top:${48 + ((i * 37) % 40)}%;animation-delay:${(i * 0.7) % 5}s\"></i>`);\n    el.appendChild(f);\n  }\n  root.appendChild(el);\n  return { update() {} };\n};\n\n/* page/hd/scenes/world.js */\n// Outdoor maps (WORLDS, filled by Game.register). One cell = 10cqw; the camera keeps the hero centred.\nconst WORLDS = {};\nconst WORLD_MARGIN = 6; // cells of forest drawn around the map\n\nScenes.world = function (root) {\n  const el = h(`<div class=\"scene world\"><div class=\"world-map\"></div><div class=\"loc\"></div></div>`);\n  root.appendChild(el);\n  const view = el.querySelector(\".world-map\"), loc = el.querySelector(\".loc\");\n  const dlg = dialogue(el);\n  const menus = popups(el);\n  const pic = picLayer(el);\n  const panel = panelLayer(el);\n  let map = null, people = null;\n\n  const build = (key) => {\n    const w = WORLDS[key];\n    map = key;\n    view.innerHTML = Art.world(w, WORLD_MARGIN);\n    view.style.width = `${(w.cols + WORLD_MARGIN * 2) * 10}cqw`;\n    loc.textContent = w.label;\n    const edge = WORLD_MARGIN * 100;\n    people = actorLayer(view, { w: (w.cols + WORLD_MARGIN * 2) * 100, h: (w.rows + WORLD_MARGIN * 2) * 100, ox: edge, oy: edge });\n    view.style.transition = \"none\"; // no glide on the first placement\n    requestAnimationFrame(() => requestAnimationFrame(() => (view.style.transition = \"\")));\n  };\n\n  return {\n    update(state) {\n      if (state.map.key !== map) build(state.map.key);\n      const cell = (n) => (n + WORLD_MARGIN + 0.5) * 10; // cell centre, in cqw from the map's top-left\n      view.style.transform = `translate(calc(50cqw - ${cell(state.x)}cqw), calc(44cqh - ${cell(state.y)}cqw))`;\n      people.update(state);\n      dlg.update(state.dialogue);\n      menus.update(state.boxes);\n      pic.update(state.pic);\n      panel.update(state.panel);\n    },\n  };\n};\n\n/* page/hd/core/hd.js */\n// The renderer: 30 times a second asks the game for its state and shows the matching scene.\n// state.screen names a full-screen scene (\"splash\", \"intro\", \"title\", \"menu\", \"prof\"); otherwise the current map's room is shown.\nconst HD = (() => {\n  let root, scenes, current = null, currentId = null;\n\n  const pick = (state) => state.screen || (ROOMS[state.map.key] ? \"room\" : WORLDS[state.map.key] ? \"world\" : null);\n\n  function show(id) {\n    if (id === currentId) return;\n    if (current && current.destroy) current.destroy();\n    for (const el of root.querySelectorAll(\":scope > .scene\")) el.remove(); // keep overlays such as the text-entry form\n    current = id ? scenes[id](root) : null;\n    currentId = id;\n    root.dataset.scene = id || \"\";\n  }\n\n  return {\n    last: null,\n    start(rootEl, sceneTable, getState) {\n      root = rootEl; scenes = sceneTable;\n      setInterval(() => {\n        const state = getState();\n        show(pick(state));\n        if (current) current.update(state);\n        HD.last = state;\n      }, 1000 / 30);\n    },\n  };\n})();\n\n/* game/core.js */\n// The game engine: grid movement like Gold's (docs/ENGINE.md). Its `state` is what the HD scenes draw.\n// Map module: { room: {art, cols, rows, label}, solid: [rows of \"#\"/\".\"], warps: [{x,y,to,tx,ty,dir}],\n//   npcs: [{id, name, x, y, dir, script, hideIf}], signs: [{x, y, script}], coords: [{x, y, script}] (run when stepped on), enter: async (s) => {} }\n// Outdoor maps give `world: {label, cols, rows, cells, buildings}` instead of `room`; buildings carry their door's warp (to, tx, ty).\nconst Game = (() => {\n  const STEP = 16, TURN = 6; // frames per step (~0.27s at 60 fps), frames spent turning on the spot\n  const DX = [0, 0, -1, 1], DY = [1, -1, 0, 0]; // down, up, left, right\n  const maps = {};\n  const G = {\n    maps, root: null, running: false, player: null, script: null,\n    state: { screen: \"splash\", map: { key: \"\" }, x: 0, y: 0, dir: 0, objects: [], dialogue: null, boxes: [], menu: null, prof: null, pic: null, panel: null },\n  };\n  let moving = 0, turning = 0;\n  G.msgMs = 900; // how long battle messages stay up (tests shorten it)\n  G.picked = null; // set by tapping a menu button (see scenes/battle.js)\n  G.pick = (i) => { G.picked = i; };\n\n  const here = () => maps[G.state.map.key];\n  const kindAt = (x, y) => { const w = here().world; return w && y >= 0 && y < w.rows && x >= 0 && x < w.cols ? w.cells[y][x] : null; };\n  const npcAt = (x, y) => G.state.objects.find((o) => o.x === x && o.y === y);\n  const blocked = (x, y) => {\n    const m = here();\n    return x < 0 || y < 0 || y >= m.solid.length || x >= m.solid[0].length || m.solid[y][x] === \"#\" || !!npcAt(x, y);\n  };\n\n  // Outdoor maps give `world` (see art/world.js); solid cells and building doors are derived from it.\n  const BLOCKING = \"TcrwSv\";\n  const fromWorld = (w) => {\n    const solid = w.cells.map((row) => [...row].map((k) => (BLOCKING.includes(k) ? \"#\" : \".\")));\n    const warps = [];\n    for (const b of w.buildings || []) {\n      for (let y = b.y; y < b.y + b.h; y++) for (let x = b.x; x < b.x + b.w; x++) solid[y][x] = \"#\";\n      const dx = b.x + b.door, dy = b.y + b.h - 1;\n      solid[dy][dx] = \".\";\n      warps.push({ x: dx, y: dy, to: b.to, tx: b.tx, ty: b.ty, dir: b.dir ?? 1 });\n    }\n    return { solid: solid.map((r) => r.join(\"\")), warps };\n  };\n  // Money is \"BUDS\" (Gold starts you with 3000, so do we).\n  G.CURRENCY = \"BUDS\";\n  G.newPlayer = () => ({ name: \"\", id: 10000 + rand(90000), money: 3000, play: 0, options: { speed: \"mid\" }, flags: {}, bag: {}, party: [], box: [] });\n  G.register = (key, def) => {\n    if (def.world) {\n      Object.assign(def, fromWorld(def.world), { warps: [...fromWorld(def.world).warps, ...(def.warps || [])] });\n      WORLDS[key] = def.world;\n    } else ROOMS[key] = def.room;\n    for (const n of def.npcs || []) if (n.trainer && !n.script) n.script = G.trainerScript(n);\n    maps[key] = def;\n  };\n\n  // A script that says each line in turn (a line may be a function of the script API, e.g. to use the player's name).\n  G.talk = (...lines) => async (s) => { for (const l of lines) await s.say(typeof l === \"function\" ? l(s) : l); };\n\n  G.step = (a, d) => { a.x += DX[d]; a.y += DY[d]; };\n\n  // Shortest walk (list of directions) from (x, y) to (tx, ty) through free cells; used by scripts to send people to the player.\n  G.path = (x, y, tx, ty) => {\n    const free = (cx, cy) => !blocked(cx, cy) && !(cx === G.state.x && cy === G.state.y);\n    const from = new Map([[`${x},${y}`, null]]), queue = [[x, y]];\n    while (queue.length) {\n      const [cx, cy] = queue.shift();\n      if (cx === tx && cy === ty) break;\n      for (let d = 0; d < 4; d++) {\n        const nx = cx + DX[d], ny = cy + DY[d], k = `${nx},${ny}`;\n        if (!from.has(k) && (free(nx, ny) || (nx === tx && ny === ty))) { from.set(k, [cx, cy, d]); queue.push([nx, ny]); }\n      }\n    }\n    const out = [];\n    for (let at = from.get(`${tx},${ty}`); at; at = from.get(`${at[0]},${at[1]}`)) out.unshift(at[2]);\n    return out;\n  };\n\n  // People that wander when idle: wander \"spin\" turns on the spot, \"vertical\" / \"horizontal\" pace one cell either way from where they stand.\n  function wander() {\n    for (const o of G.state.objects) {\n      if (!o.wander) continue;\n      o.home ||= { x: o.x, y: o.y };\n      o.wait = (o.wait ?? 40 + Math.random() * 120) - 1;\n      if (o.wait > 0) continue;\n      o.wait = 60 + Math.random() * 180;\n      if (o.wander === \"spin\") { o.dir = Math.floor(Math.random() * 4); continue; }\n      const d = (o.wander === \"horizontal\" ? 2 : 0) + (Math.random() < 0.5 ? 0 : 1), nx = o.x + DX[d], ny = o.y + DY[d];\n      if (Math.abs(nx - o.home.x) <= 1 && Math.abs(ny - o.home.y) <= 1 && !blocked(nx, ny) && !(nx === G.state.x && ny === G.state.y)) { o.dir = d; o.x = nx; o.y = ny; }\n    }\n  }\n\n  G.warp = async (key, x, y, dir) => {\n    const def = maps[key];\n    Object.assign(G.state, { map: { key }, x, y, dir, boxes: [], objects: (def.npcs || []).filter((n) => (!n.hideIf || !G.player.flags[n.hideIf]) && (!n.showIf || G.player.flags[n.showIf])).map((n) => ({ ...n })) });\n    moving = turning = 0;\n    if (def.enter) await G.run(def.enter);\n  };\n\n  G.run = async (fn) => {\n    if (G.script) return;\n    G.script = fn;\n    try { await fn(scriptApi(G)); } finally { G.state.dialogue = null; G.state.boxes = []; G.script = null; Input.clear(); }\n  };\n\n  // Wild encounters, as in Gold: on tall grass each step rolls against the map's rate for the time of day; the species comes\n  // from 7 slots weighted 30/30/20/10/5/4/1 %, and the level is bumped by 0-4.\n  const PROBS = [30, 60, 80, 90, 95, 99, 100];\n  function encounter(m) {\n    const wild = m.wild;\n    if (!wild || kindAt(G.state.x, G.state.y) !== \"g\" || rand(256) >= Math.floor((wild.rate * 256) / 100)) return;\n    const roll = rand(100) + 1, [level, species] = wild[timeOfDay()][PROBS.findIndex((p) => roll <= p)];\n    const r = rand(256), bump = r < 89 ? 0 : r < 166 ? 1 : r < 217 ? 2 : r < 242 ? 3 : 4; // 35 / 65 / 85 / 95 percent of 256\n    G.run(async (s) => {\n      if ((await Game.battle(s, makeMon(species, level + bump))) === \"lost\") await Game.whiteout(s);\n    });\n  }\n  // Out of usable buddymon: lose half your money, everyone is healed, and you wake up at home.\n  G.whiteout = async (s) => {\n    await s.say(`${G.player.name} is out of usable BUDDYMON!`);\n    G.player.money = Math.floor(G.player.money / 2);\n    await s.say(`${G.player.name} panicked and dropped half of their ${G.CURRENCY}...`);\n    for (const m of G.player.party) { m.hp = statsFor(m).hp; for (const mv of m.moves) mv.pp = MOVES[mv.id].pp; }\n    const home = G.player.lastCenter || { map: \"livingroom\", x: 7, y: 6, dir: 1 }; // the last Center you healed at, else home\n    G.state.map = { key: home.map };\n    Object.assign(G.state, { x: home.x, y: home.y, dir: home.dir, objects: (maps[home.map].npcs || []).map((n) => ({ ...n })) });\n  };\n\n  function interact() {\n    const { x, y, dir } = G.state, tx = x + DX[dir], ty = y + DY[dir];\n    const npc = npcAt(tx, ty);\n    if (npc) {\n      if (npc.faces !== false) npc.dir = [1, 0, 3, 2][dir]; // look back at the player\n      if (npc.script) G.run(npc.script);\n      return;\n    }\n    const sign = (here().signs || []).find((g) => g.x === tx && g.y === ty);\n    if (sign) G.run(sign.script);\n  }\n\n  function tick() {\n    Input.poll();\n    if (G.script || G.state.screen) return;\n    const { state } = G;\n    wander();\n    if (moving) {\n      if (--moving > 0) return;\n      const m = here(), w = (m.warps || []).find((g) => g.x === state.x && g.y === state.y);\n      if (w) G.warp(w.to, w.tx, w.ty, w.dir);\n      else { const c = (m.coords || []).find((g) => g.x === state.x && g.y === state.y), t = !c && G.trainerSees(); if (c) G.run(c.script); else if (t) G.run(t.script); else encounter(m); }\n      return;\n    }\n    if (Input.pressed(\"START\")) return G.run(Game.startMenu);\n    if (Input.pressed(\"A\")) return interact();\n    const d = Input.dir();\n    if (d === null) return;\n    if (d !== state.dir) { state.dir = d; turning = TURN; return; }\n    if (turning > 0) { turning--; return; }\n    const nx = state.x + DX[d], ny = state.y + DY[d];\n    // A ledge is jumped one way only (down): you land two cells on, past the lip.\n    if (d === 0 && kindAt(nx, ny) === \"v\" && !blocked(nx, ny + 1)) { state.x = nx; state.y = ny + 1; moving = STEP + 8; return; }\n    if (blocked(nx, ny)) return;\n    G.step(state, d);\n    moving = STEP;\n  }\n\n  // Starts the frame loop and the renderer. Screens before the first map (splash, title...) are driven by game/flow.js.\n  G.start = (rootEl, player) => {\n    G.root = rootEl;\n    G.player = player;\n    if (G.running) return;\n    G.running = true;\n    let last = performance.now(), acc = 0;\n    const loop = (now) => {\n      acc += Math.min(now - last, 100); last = now;\n      for (; acc >= 1000 / 60; acc -= 1000 / 60) tick();\n      requestAnimationFrame(loop);\n    };\n    requestAnimationFrame(loop);\n    HD.start(rootEl, Scenes, () => G.state);\n  };\n  return G;\n})();\n\n/* game/lib/flow.js */\n// Start-up flow: splash -> intro cinematic -> title -> menu -> (new game) Willow's welcome talk and name entry.\nGame.flow = (() => {\n  const frame = () => new Promise((ok) => requestAnimationFrame(ok));\n  const anyPress = () => [\"A\", \"B\", \"START\"].some((k) => Input.pressed(k));\n  // Shows a screen for `ms` (or until a button when skippable).\n  const hold = async (screen, ms, skippable = true) => {\n    Game.state.screen = screen;\n    Input.clear();\n    for (const t0 = performance.now(); performance.now() - t0 < ms;) {\n      Input.poll();\n      if (skippable && anyPress()) break;\n      await frame();\n    }\n  };\n  const menu = async (items) => {\n    let i = 0;\n    const show = () => (Game.state.menu = { items: items.map((it, n) => ({ label: it.label, selected: n === i })), info: items[i].info || \"\" });\n    Game.state.screen = \"menu\";\n    show();\n    for (Input.clear(); ;) {\n      Input.poll();\n      if (Input.pressed(\"UP\")) { i = (i + items.length - 1) % items.length; show(); }\n      if (Input.pressed(\"DOWN\")) { i = (i + 1) % items.length; show(); }\n      if (Input.pressed(\"A\") || Input.pressed(\"START\")) return items[i].id;\n      await frame();\n    }\n  };\n\n  const welcome = async (s) => {\n    s.screen(\"prof\", { prof: { who: \"professor\" } });\n    await s.say(\"Hello there! Welcome to the world of BUDDYMON!\");\n    await s.say(\"My name is WILLOW. People call me the BUDDYMON PROF!\");\n    await s.say(\"This world is full of creatures called BUDDYMON. Some people keep them as friends. Others battle with them.\");\n    await s.say(\"As for me, I study BUDDYMON for a living. But first, tell me a little about yourself.\");\n    s.G.player.name = await s.prompt(\"What is your name?\", 7);\n    s.screen(\"prof\", { prof: { who: \"hero\" } });\n    await s.say(`${s.name}! Your very own BUDDYMON story is about to unfold. A world of dreams and adventure is waiting. Let's go!`);\n    s.screen(null, { prof: null });\n  };\n\n  // Runs everything up to the first map. `saved` is the loaded save or null.\n  return async (saved) => {\n    await hold(\"splash\", 5500, false);\n    await hold(\"intro\", 24000);\n    await hold(\"title\", 1e9);\n    const items = [{ id: \"new\", label: \"New Game\" }];\n    if (saved) items.unshift({ id: \"continue\", label: \"Continue\", info: `${saved.player.name}` });\n    if ((await menu(items)) === \"continue\") return saved;\n    Game.player = Game.newPlayer();\n    await Game.run(welcome);\n    return null;\n  };\n})();\n\n/* game/lib/input.js */\n// Player input for the native engine: pad and gesture presses (`held` from pad.js) plus the keyboard.\nconst Input = (() => {\n  const KEYS = { ArrowUp: \"UP\", ArrowDown: \"DOWN\", ArrowLeft: \"LEFT\", ArrowRight: \"RIGHT\", z: \"B\", x: \"A\", Enter: \"START\", Shift: \"SELECT\" };\n  const down = {}, prev = {}, edge = {};\n  let last = null; // the direction pressed most recently wins when several are held\n  addEventListener(\"keydown\", (e) => { const k = KEYS[e.key]; if (k && !(e.target instanceof HTMLInputElement)) { down[k] = true; e.preventDefault(); } });\n  addEventListener(\"keyup\", (e) => { const k = KEYS[e.key]; if (k) down[k] = false; });\n  const isDown = (k) => !!down[k] || (typeof held !== \"undefined\" && !!held[k]);\n  const DIRS = [\"DOWN\", \"UP\", \"LEFT\", \"RIGHT\"]; // same order as `dir` (0 down, 1 up, 2 left, 3 right)\n  return {\n    // Call once per frame: turns level into presses.\n    poll() {\n      for (const k of Object.values(KEYS)) {\n        const now = isDown(k);\n        if (now && !prev[k]) { edge[k] = true; if (DIRS.includes(k)) last = k; }\n        prev[k] = now;\n      }\n    },\n    pressed(k) { const v = !!edge[k]; edge[k] = false; return v; },\n    clear() { for (const k in edge) edge[k] = false; },\n    dir() {\n      if (last && isDown(last)) return DIRS.indexOf(last);\n      const d = DIRS.findIndex(isDown);\n      return d < 0 ? null : d;\n    },\n  };\n})();\n\n/* game/lib/rival.js */\n// Your rival: his starter counters yours (original pairing), and his name stays \"???\" until you give it to the officer in Willow's lab.\nGame.rivalSpecies = (P) => ({ bramblet: \"bandit\", bandit: \"chomplet\", chomplet: \"bramblet\" })[P.party[0] ? P.party[0].species : \"bramblet\"];\nGame.rivalName = (P) => P.rival || \"???\";\n\n/* game/lib/script.js */\n// Scripts are async functions taking `s`: the same verbs Gold's scripts use (text, yes/no, flags, movement, warps).\n// Only one script runs at a time; the player cannot move while it does.\nfunction scriptApi(G) {\n  const frame = () => new Promise((ok) => requestAnimationFrame(ok));\n  const press = async (k) => { Input.clear(); while (!Input.pressed(k)) { Input.poll(); await frame(); } };\n  const actor = (who) => (who === \"player\" ? G.state : G.state.objects.find((o) => o.id === who));\n  const s = {\n    G,\n    screen: (name, extra) => Object.assign(G.state, { screen: name, ...extra }),\n    get name() { return G.player.name; },\n    flag: (name, v) => (v === undefined ? !!G.player.flags[name] : void (G.player.flags[name] = v)),\n    // Show a line for `ms` (a press of A skips ahead): battle messages that flow by without waiting for a button.\n    async msg(text, ms = Game.msgMs) {\n      G.state.dialogue = { text, more: false };\n      Input.clear();\n      for (const t0 = performance.now(); performance.now() - t0 < ms;) { Input.poll(); if (Input.pressed(\"A\")) break; await frame(); }\n    },\n    // A button menu in the battle screen: arrows + A, or tap a button. Returns the index, or -1 for B.\n    async menu(items, cols = 1, kind = \"cmd\") {\n      let i = 0;\n      G.state.dialogue = null; // the menu takes the message box's place, leaving the battle screen clear\n      const B = G.state.battle, show = () => (B.menu = { kind, cols, items: items.map((label, n) => ({ label, sel: n === i })) });\n      G.picked = null; show();\n      for (Input.clear(); ;) {\n        Input.poll();\n        const n = items.length;\n        if (Input.pressed(\"UP\")) i = (i - cols + n) % n;\n        if (Input.pressed(\"DOWN\")) i = (i + cols) % n;\n        if (cols > 1 && Input.pressed(\"LEFT\")) i = (i + n - 1) % n;\n        if (cols > 1 && Input.pressed(\"RIGHT\")) i = (i + 1) % n;\n        show();\n        if (Input.pressed(\"A\")) break;\n        if (Input.pressed(\"B\")) { i = -1; break; }\n        if (G.picked !== null) { i = G.picked; G.picked = null; break; }\n        await frame();\n      }\n      B.menu = null;\n      return i;\n    },\n    async say(text) {\n      G.state.dialogue = { text, more: true };\n      await press(\"A\");\n      G.state.dialogue = { text, more: false };\n    },\n    // Yes/No over a question; resolves 0 for yes, like ask(), but with the question shown in the box.\n    async confirm(text) { G.state.dialogue = { text, more: false }; return s.ask(); },\n    // Opens the phone's own keyboard on a real input.\n    prompt(label, max = 10) {\n      return new Promise((ok) => {\n        const box = h(`<form class=\"ask\"><label>${label}</label><input maxlength=\"${max}\" autocomplete=\"off\" autocapitalize=\"words\" spellcheck=\"false\"><button>OK</button></form>`);\n        G.root.appendChild(box);\n        const input = box.querySelector(\"input\");\n        input.focus();\n        box.addEventListener(\"submit\", (e) => { e.preventDefault(); const v = input.value.trim(); if (v) { box.remove(); ok(v); } });\n      });\n    },\n    // Walk one person along `dirs` (0 down, 1 up, 2 left, 3 right); `face` keeps them looking that way while they move.\n    async move(who, dirs, face) {\n      const a = actor(who);\n      for (const d of dirs) { a.dir = face ?? d; G.step(a, d); await s.wait(16); }\n    },\n    // Several people walking together: pairs of [who, dirs], moved in the order given each step.\n    async walk(pairs) {\n      const n = Math.max(...pairs.map(([, dirs]) => dirs.length));\n      for (let i = 0; i < n; i++) {\n        for (const [who, dirs] of pairs) if (i < dirs.length) { const a = actor(who); a.dir = dirs[i]; G.step(a, dirs[i]); }\n        await s.wait(16);\n      }\n    },\n    // The player follows `who` along `dirs`, one cell behind (Gold's \"follow\"): used for the Guide Gent's tour.\n    async follow(who, dirs) {\n      const a = actor(who), trail = [];\n      for (const d of dirs) {\n        trail.push({ x: a.x, y: a.y });\n        a.dir = d; G.step(a, d);\n        const t = trail.shift(), p = G.state;\n        if (t.x !== p.x || t.y !== p.y) { p.dir = t.x > p.x ? 3 : t.x < p.x ? 2 : t.y > p.y ? 0 : 1; p.x = t.x; p.y = t.y; }\n        await s.wait(16);\n      }\n    },\n    // A \"!\" over someone's head for a moment.\n    async emote(who) { const a = actor(who); a.emote = true; await s.wait(36); a.emote = false; },\n    // Send someone to stand next to the player (on the given side: 0 below, 1 above, 2 left, 3 right).\n    approach: (who, side = 3) => {\n      const a = actor(who), p = G.state, off = [[0, 1], [0, -1], [-1, 0], [1, 0]][side];\n      return s.move(who, G.path(a.x, a.y, p.x + off[0], p.y + off[1]));\n    },\n    // The big picture of a buddymon (like Gold's pokepic) until unpic().\n    pic: (species) => { G.state.pic = species; },\n    unpic: () => { G.state.pic = null; },\n    // A short pause with a message when something is restored or given.\n    async notify(text) { await s.say(text); },\n    turn(who, d) { actor(who).dir = d; },\n    wait: async (frames) => { for (let i = 0; i < frames; i++) await frame(); },\n    warp: (map, x, y, dir) => G.warp(map, x, y, dir),\n    give(item, n = 1) { G.player.bag[item] = (G.player.bag[item] || 0) + n; },\n    addBuddy(species, level) { G.player.party.push(makeMon(species, level)); (G.player.dex ||= {})[species] = \"caught\"; },\n    hide(id) { G.state.objects = G.state.objects.filter((o) => o.id !== id); },\n  };\n  return Object.assign(s, menuVerbs(G, s));\n}\n\n/* game/lib/shared.js */\n// Small scripts maps share: berry trees (one berry a day) and hidden items (found once).\nGame.berryTree = (flag) => async (s) => {\n  const today = new Date().toDateString(), flags = s.G.player.flags;\n  if (flags[flag] === today) return s.say(\"The tree has no more berries today.\");\n  flags[flag] = today;\n  s.give(\"berry\");\n  await s.say(`${s.name} picked a SWEET BERRY from the tree!`);\n};\nGame.hiddenItem = (flag, item) => async (s) => {\n  if (s.flag(flag)) return;\n  s.flag(flag, true);\n  s.give(item);\n  await s.say(`${s.name} found a ${ITEMS[item].name}!`);\n};\n\n/* game/lib/start.js */\n// Boot and saves. A save is JSON ({ at, player, map, x, y, dir }) kept on the device and, when the server is reachable, in the cloud (/api/save).\nGame.SAVE_KEY = \"buddymon-save\";\nconst saveText = () => {\n  const { player, state } = Game;\n  return JSON.stringify({ at: Date.now(), player, map: state.map.key, x: state.x, y: state.y, dir: state.dir });\n};\nlet lastCloud = 0;\nGame.save = (force) => {\n  if (Game.state.screen || !Game.state.map.key) return;\n  const text = saveText();\n  try { localStorage.setItem(Game.SAVE_KEY, text); } catch {}\n  if (force || Date.now() - lastCloud > 15000) { lastCloud = Date.now(); api(\"/api/save\", { method: \"PUT\", body: text }).catch(() => {}); }\n};\n// The newer of the device save and the cloud save.\nGame.loadSave = async () => {\n  let local = null, cloud = null;\n  try { local = JSON.parse(localStorage.getItem(Game.SAVE_KEY)); } catch {}\n  try { const res = await api(\"/api/save\"); if (res.ok) cloud = await res.json(); } catch {}\n  return [local, cloud].filter(Boolean).sort((a, b) => b.at - a.at)[0] || null;\n};\nGame.boot = async (root) => {\n  const saved = await Game.loadSave();\n  const player = saved ? { ...Game.newPlayer(), ...saved.player } : Game.newPlayer();\n  for (const m of [...player.party, ...player.box]) m.gender ||= rollGender(m.species); // saves from before genders\n  Game.start(root, player);\n  const resume = await Game.flow(saved);\n  setInterval(Game.save, 5000);\n  setInterval(() => { if (!Game.state.screen && Game.state.map.key) Game.player.play++; }, 1000); // play time, in seconds\n  Game.applyOptions();\n  addEventListener(\"pagehide\", () => { lastCloud = 0; Game.save(); });\n  Game.state.screen = null;\n  if (resume) return Game.warp(resume.map, resume.x, resume.y, resume.dir);\n  await Game.warp(\"bedroom\", 3, 3, 0);\n};\n\n/* game/lib/trainer.js */\n// Trainers: an NPC with `trainer: { name, cls, party: [[species, level]...], money, sight, seen, beaten, after, flag }`.\n// They spot you down their line of sight (`sight` cells), shout, walk up, and battle; talking to one you beat gives its `after` line.\nGame.trainerScript = (n) => async (s) => {\n  const t = n.trainer, flags = s.G.player.flags, me = () => s.G.state.objects.find((o) => o.id === n.id);\n  if (flags[t.flag]) return s.say(t.after);\n  const p = s.G.state, o = me();\n  await s.emote(n.id);\n  // Face the player and close the distance along the line between you.\n  o.dir = o.x === p.x ? (o.y < p.y ? 0 : 1) : o.x < p.x ? 3 : 2;\n  await s.approach(n.id, [1, 0, 3, 2][o.dir]);\n  await s.say(t.seen);\n  const result = await Game.battle(s, t.party.map(([species, level]) => makeMon(species, level)), { trainer: { name: `${t.cls} ${t.name}`, money: t.money ?? 16, win: t.beaten } });\n  if (result === \"lost\") return Game.whiteout(s);\n  flags[t.flag] = true;\n  s.G.state.dialogue = null;\n};\n\n// After each step: does a trainer who has not been beaten see the player down their line of sight?\nGame.trainerSees = () => {\n  const { state, player } = Game, DX = [0, 0, -1, 1], DY = [1, -1, 0, 0];\n  const m = Game.maps[state.map.key];\n  const solid = (x, y) => y < 0 || x < 0 || y >= m.solid.length || x >= m.solid[0].length || m.solid[y][x] === \"#\";\n  return state.objects.find((o) => {\n    if (!o.trainer || player.flags[o.trainer.flag]) return false;\n    for (let k = 1; k <= (o.trainer.sight ?? 4); k++) {\n      const x = o.x + DX[o.dir] * k, y = o.y + DY[o.dir] * k;\n      if (x === state.x && y === state.y) return true;\n      if (solid(x, y) || state.objects.some((q) => q !== o && q.x === x && q.y === y)) return false;\n    }\n    return false;\n  });\n};\n\n/* game/data/items.js */\n// Items. net: catch multiplier of a buddy net; heal: HP restored; price in BUDS (selling gives half).\nconst ITEMS = {\n  buddy_net: { name: \"BUDDY NET\", net: 1, pocket: \"nets\", price: 200 },\n  tonic: { name: \"TONIC\", heal: 20, pocket: \"items\", price: 300 },\n  tide_charm: { name: \"TIDE CHARM\", pocket: \"items\" },\n  mystery_egg: { name: \"MYSTERY EGG\", pocket: \"key\" },\n  berry: { name: \"SWEET BERRY\", heal: 10, pocket: \"items\", price: 100 },\n};\n\n/* game/data/moves.js */\n// Moves. power 0 = status move. effect: { stat, stages, target: \"foe\" | \"self\" } changes a stat stage. priority 1 goes first.\nconst MOVES = {\n  tackle: { name: \"TACKLE\", type: \"normal\", power: 35, acc: 95, pp: 35 },\n  scratch: { name: \"SCRATCH\", type: \"normal\", power: 40, acc: 100, pp: 35 },\n  quick_strike: { name: \"QUICK STRIKE\", type: \"normal\", power: 40, acc: 100, pp: 30, priority: 1 },\n  sharp_fang: { name: \"SHARP FANG\", type: \"normal\", power: 80, acc: 90, pp: 15 },\n  growl: { name: \"GROWL\", type: \"normal\", power: 0, acc: 100, pp: 40, effect: { stat: \"atk\", stages: -1, target: \"foe\" } },\n  leer: { name: \"LEER\", type: \"normal\", power: 0, acc: 100, pp: 30, effect: { stat: \"def\", stages: -1, target: \"foe\" } },\n  tail_wag: { name: \"TAIL WAG\", type: \"normal\", power: 0, acc: 100, pp: 30, effect: { stat: \"def\", stages: -1, target: \"foe\" } },\n  curl_up: { name: \"CURL UP\", type: \"normal\", power: 0, acc: 100, pp: 40, effect: { stat: \"def\", stages: 1, target: \"self\" } },\n  dust_kick: { name: \"DUST KICK\", type: \"ground\", power: 0, acc: 100, pp: 15, effect: { stat: \"acc\", stages: -1, target: \"foe\" } },\n  string_shot: { name: \"STRING SHOT\", type: \"bug\", power: 0, acc: 95, pp: 40, effect: { stat: \"spe\", stages: -1, target: \"foe\" } },\n  harden: { name: \"HARDEN\", type: \"normal\", power: 0, acc: 100, pp: 30, effect: { stat: \"def\", stages: 1, target: \"self\" } },\n  breeze: { name: \"BREEZE\", type: \"flying\", power: 40, acc: 100, pp: 35 },\n  peck: { name: \"PECK\", type: \"flying\", power: 35, acc: 100, pp: 35 },\n  night_nip: { name: \"NIGHT NIP\", type: \"dark\", power: 40, acc: 100, pp: 25 },\n  splash_jet: { name: \"SPLASH JET\", type: \"water\", power: 40, acc: 100, pp: 25 },\n  leaf_cutter: { name: \"LEAF CUTTER\", type: \"grass\", power: 55, acc: 95, pp: 25 },\n};\n\n/* game/data/species.js */\n// Species: types, base stats (hp, atk, def, spe, spa, spd), catch rate, base experience, growth curve, learnset by level, female (chance 0-1 of a female; 1 = always).\n// Art is looked up by key in Art (art/<key>.js). Add evolutions here when the line is built.\nconst SPECIES = {\n  bramblet: { name: \"BRAMBLET\", female: 0.125, types: [\"grass\"], base: [45, 49, 65, 45, 49, 65], catchRate: 45, exp: 64, growth: \"slow\", moves: { 1: [\"tackle\", \"growl\"], 8: [\"leaf_cutter\"] } },\n  bandit: { name: \"BANDIT\", female: 1, types: [\"dark\"], base: [45, 55, 45, 60, 50, 50], catchRate: 45, exp: 64, growth: \"slow\", moves: { 1: [\"scratch\", \"growl\"], 9: [\"night_nip\"], 15: [\"quick_strike\"] } },\n  chomplet: { name: \"CHOMPLET\", female: 0.125, types: [\"water\"], base: [50, 65, 64, 43, 44, 48], catchRate: 45, exp: 66, growth: \"slow\", moves: { 1: [\"scratch\", \"leer\"], 13: [\"splash_jet\"] } },\n  chirplet: { name: \"CHIRPLET\", female: 0.5, types: [\"normal\", \"flying\"], base: [40, 45, 40, 56, 35, 35], catchRate: 255, exp: 55, growth: \"slow\", moves: { 1: [\"tackle\"], 5: [\"dust_kick\"], 9: [\"breeze\"], 13: [\"quick_strike\"] } },\n  nibblet: { name: \"NIBBLET\", female: 0.5, types: [\"normal\"], base: [30, 56, 35, 72, 25, 35], catchRate: 255, exp: 57, growth: \"fast\", moves: { 1: [\"tackle\", \"tail_wag\"], 7: [\"quick_strike\"], 13: [\"sharp_fang\"] } },\n  peekat: { name: \"PEEKAT\", female: 0.5, types: [\"normal\"], base: [35, 46, 34, 20, 35, 45], catchRate: 255, exp: 57, growth: \"fast\", moves: { 1: [\"scratch\"], 7: [\"curl_up\"], 12: [\"quick_strike\"] } },\n  grublet: { name: \"GRUBLET\", female: 0.5, types: [\"bug\"], base: [45, 30, 35, 45, 20, 20], catchRate: 255, exp: 53, growth: \"fast\", moves: { 1: [\"tackle\", \"string_shot\"] } },\n  cocoonet: { name: \"COCOONET\", female: 0.5, types: [\"bug\"], base: [50, 20, 55, 30, 25, 25], catchRate: 120, exp: 72, growth: \"fast\", moves: { 1: [\"harden\"], 7: [\"tackle\"] } },\n  spinlet: { name: \"SPINLET\", female: 0.5, types: [\"bug\", \"poison\"], base: [40, 60, 40, 30, 40, 40], catchRate: 255, exp: 95, growth: \"fast\", moves: { 1: [\"tackle\", \"string_shot\"] } },\n  hootling: { name: \"HOOTLING\", female: 0.5, types: [\"normal\", \"flying\"], base: [60, 30, 30, 50, 36, 56], catchRate: 255, exp: 58, growth: \"fast\", moves: { 1: [\"tackle\", \"growl\"], 11: [\"peck\"] } },\n};\n\n/* game/data/types.js */\n// Type chart (same matchups as Gold): TYPE_CHART[attacker][defender] = multiplier when not 1. Fire, water, grass, electric, ice, psychic, dark and dragon moves are special.\nconst TYPE_CHART = {\n  normal: { rock: 0.5, steel: 0.5, ghost: 0 },\n  fire: { grass: 2, ice: 2, bug: 2, steel: 2, fire: 0.5, water: 0.5, rock: 0.5, dragon: 0.5 },\n  water: { fire: 2, ground: 2, rock: 2, water: 0.5, grass: 0.5, dragon: 0.5 },\n  electric: { water: 2, flying: 2, electric: 0.5, grass: 0.5, dragon: 0.5, ground: 0 },\n  grass: { water: 2, ground: 2, rock: 2, fire: 0.5, grass: 0.5, poison: 0.5, flying: 0.5, bug: 0.5, dragon: 0.5, steel: 0.5 },\n  ice: { grass: 2, ground: 2, flying: 2, dragon: 2, fire: 0.5, water: 0.5, ice: 0.5, steel: 0.5 },\n  fighting: { normal: 2, ice: 2, rock: 2, dark: 2, steel: 2, poison: 0.5, flying: 0.5, psychic: 0.5, bug: 0.5, ghost: 0 },\n  poison: { grass: 2, poison: 0.5, ground: 0.5, rock: 0.5, ghost: 0.5, steel: 0 },\n  ground: { fire: 2, electric: 2, poison: 2, rock: 2, steel: 2, grass: 0.5, bug: 0.5, flying: 0 },\n  flying: { grass: 2, fighting: 2, bug: 2, electric: 0.5, rock: 0.5, steel: 0.5 },\n  psychic: { fighting: 2, poison: 2, psychic: 0.5, steel: 0.5, dark: 0 },\n  bug: { grass: 2, psychic: 2, dark: 2, fire: 0.5, fighting: 0.5, poison: 0.5, flying: 0.5, ghost: 0.5, steel: 0.5 },\n  rock: { fire: 2, ice: 2, flying: 2, bug: 2, fighting: 0.5, ground: 0.5, steel: 0.5 },\n  ghost: { psychic: 2, ghost: 2, dark: 0.5, steel: 0.5, normal: 0 },\n  dragon: { dragon: 2, steel: 0.5 },\n  dark: { psychic: 2, ghost: 2, fighting: 0.5, dark: 0.5, steel: 0.5 },\n  steel: { ice: 2, rock: 2, fire: 0.5, water: 0.5, electric: 0.5, steel: 0.5 },\n};\nconst SPECIAL_TYPES = new Set([\"fire\", \"water\", \"grass\", \"electric\", \"ice\", \"psychic\", \"dark\", \"dragon\"]);\nconst typeMultiplier = (moveType, defTypes) => defTypes.reduce((m, t) => m * (TYPE_CHART[moveType][t] ?? 1), 1);\n\n/* game/battle/battle.js */\n// A battle, scripted like Gold's: intro, command menu (Fight / Pack / Buddymon / Run), turn order by priority then speed,\n// catching with buddy nets (wild only), experience. Game.battle(s, foe, opts) -> \"won\" | \"lost\" | \"ran\" | \"caught\". Run it inside a script.\n// opts.tutorial = { lines } is Gold's catching lesson: a scripted fight then net, the foe never attacks and nothing is kept.\n// foe is a mon (wild) or, with opts.trainer = { name, money, win }, a list of mons: no nets, no running, prize money on a win.\nGame.battle = async (s, foeMon, opts = {}) => {\n  const trainer = opts.trainer, foes = [].concat(foeMon);\n  foeMon = foes[0];\n  const P = s.G.player, state = s.G.state;\n  const fresh = () => ({ atk: 0, def: 0, spa: 0, spd: 0, spe: 0, acc: 0, eva: 0 });\n  const side = (mon, label) => ({ mon, label, stats: statsFor(mon), stages: fresh() });\n  const alive = () => P.party.filter((m) => m.hp > 0);\n  const speed = (x) => x.stats.spe * stageMult(x.stages.spe);\n  const fought = new Set();\n  const foeLabel = (mon) => (trainer ? `${trainer.name}'s ${SPECIES[mon.species].name}` : `Wild ${SPECIES[mon.species].name}`);\n  let them = side(foeMon, foeLabel(foeMon));\n  let me = side(alive()[0], alive()[0].nick), ended = null, tries = 0;\n\n  const info = (x) => ({ species: x.mon.species, name: x.mon.nick, gender: x.mon.gender, level: x.mon.level, hp: x.mon.hp, max: statsFor(x.mon).hp, xp: xpBar(x.mon) });\n  const refresh = () => { state.battle.foe = info(them); state.battle.me = info(me); };\n  const partyMenu = async (forced) => {\n    for (;;) {\n      const i = await s.menu(P.party.map((m) => `${m.nick}  Lv${m.level}  ${m.hp}/${statsFor(m).hp}`), 1, \"party\");\n      if (i < 0 && !forced) return -1;\n      if (i < 0) continue;\n      if (P.party[i].hp <= 0) { await s.msg(`${P.party[i].nick} has no energy left to battle!`); continue; }\n      if (P.party[i] === me.mon) { await s.msg(`${me.mon.nick} is already out!`); continue; }\n      return i;\n    }\n  };\n  const sendOut = async (mon) => { me = side(mon, mon.nick); fought.add(mon); refresh(); await s.msg(`Go! ${mon.nick}!`); };\n\n  const lesson = opts.tutorial ? [{ type: \"fight\", slot: null }, { type: \"item\", id: \"buddy_net\" }] : null;\n  const choose = async () => {\n    if (lesson) {\n      const step = lesson.shift();\n      await s.say(opts.tutorial.lines[step.type === \"fight\" ? 0 : 1]);\n      if (step.type === \"fight\") step.slot = me.mon.moves[0];\n      return step;\n    }\n    for (;;) {\n      const c = await s.menu([\"FIGHT\", \"PACK\", \"BUDDYMON\", \"RUN\"], 2, \"cmd\");\n      if (c === 0) {\n        const m = me.mon.moves, i = await s.menu(m.map((x) => `${MOVES[x.id].name}  ${x.pp}/${MOVES[x.id].pp}`), 2, \"moves\");\n        if (i < 0) continue;\n        if (m[i].pp <= 0) { await s.msg(\"No PP left for this move!\"); continue; }\n        return { type: \"fight\", slot: m[i] };\n      }\n      if (c === 1) {\n        const ids = Object.keys(P.bag).filter((k) => P.bag[k] > 0 && ITEMS[k]);\n        if (!ids.length) { await s.msg(\"Your PACK is empty!\"); continue; }\n        const i = await s.menu([...ids.map((k) => `${ITEMS[k].name} x${P.bag[k]}`), \"CANCEL\"], 1, \"pack\");\n        if (i < 0 || i >= ids.length) continue;\n        return { type: \"item\", id: ids[i] };\n      }\n      if (c === 2) { const i = await partyMenu(false); if (i >= 0) return { type: \"switch\", mon: P.party[i] }; continue; }\n      if (c === 3) return { type: \"run\" };\n    }\n  };\n\n  // A hit may have fainted someone: experience for a win, a forced switch or defeat for a loss.\n  const settle = async () => {\n    if (them.mon.hp <= 0) {\n      await s.msg(`${them.label} fainted!`);\n      await awardExp(s, P.party, fought, them.mon, !trainer, refresh);\n      const next = foes[foes.indexOf(them.mon) + 1];\n      if (!next) ended = \"won\";\n      else {\n        them = side(next, foeLabel(next));\n        fought.clear(); fought.add(me.mon);\n        refresh();\n        await s.msg(`${trainer.name} sent out ${SPECIES[next.species].name}!`);\n      }\n    } else if (me.mon.hp <= 0) {\n      await s.msg(`${me.mon.nick} fainted!`);\n      if (!alive().length) return (ended = \"lost\");\n      await sendOut(P.party[await partyMenu(true)]);\n    }\n    return !!ended;\n  };\n  let fxN = 0; // each move bumps this so the screen plays one animation per use: who attacks, the move's type, and hit / up / down\n  const attack = async (a, d, slot) => { await useMove(s, a, d, slot, refresh, (kind) => (state.battle.fx = { n: ++fxN, who: a === me ? \"me\" : \"foe\", type: MOVES[slot.id].type, kind })); return settle(); };\n  const foeSlot = () => { const u = them.mon.moves.filter((m) => m.pp > 0); return u.length ? u[rand(u.length)] : { id: \"tackle\", pp: 1 }; };\n\n  const useNet = async (id) => {\n    if (!opts.tutorial) P.bag[id]--;\n    await s.msg(`${opts.tutorial ? \"DUDE\" : P.name} threw a ${ITEMS[id].name}!`);\n    const rate = catchRate(them.mon, them.stats.hp, ITEMS[id].net), { caught, shakes } = opts.tutorial ? { caught: true, shakes: 3 } : throwNet(rate);\n    state.battle.net = { shakes, caught };\n    await s.wait(40 + 30 * shakes);\n    state.battle.net = null;\n    if (!caught) return s.msg([\"Oh no! It broke free!\", \"Aww! It appeared to be caught!\", \"Aargh! Almost had it!\", \"Shoot! It was so close too!\"][shakes]);\n    await s.msg(`Gotcha! ${them.label.replace(\"Wild \", \"\")} was caught!`);\n    if (opts.tutorial) return (ended = \"caught\");\n    const mon = them.mon;\n    if ((await s.confirm(`Give a nickname to ${mon.nick}?`)) === 0) mon.nick = await s.prompt(`Nickname for ${mon.nick}?`, 10);\n    (P.party.length < 6 ? P.party : (P.box ||= [])).push(mon);\n    dex[mon.species] = \"caught\";\n    ended = \"caught\";\n  };\n\n  const dex = (P.dex ||= {});\n  for (const f of foes) dex[f.species] ||= \"seen\";\n  state.screen = \"battle\";\n  state.battle = { foe: null, me: null, menu: null, net: null, fx: null };\n  refresh();\n  if (trainer) {\n    await s.msg(`${trainer.name} wants to battle!`, Math.max(Game.msgMs, 900));\n    await s.msg(`${trainer.name} sent out ${SPECIES[foeMon.species].name}!`);\n  } else await s.msg(`${them.label} appeared!`, Math.max(Game.msgMs, 600));\n  await sendOut(me.mon);\n\n  while (!ended) {\n    const act = await choose();\n    if (act.type === \"fight\") {\n      const mp = MOVES[act.slot.id].priority || 0, fs = foeSlot(), fp = MOVES[fs.id].priority || 0;\n      const meFirst = mp !== fp ? mp > fp : speed(me) !== speed(them) ? speed(me) > speed(them) : rand(2) === 0;\n      if (opts.tutorial) { if (await attack(me, them, act.slot)) break; continue; }\n      if (meFirst) { if (await attack(me, them, act.slot)) break; if (await attack(them, me, fs)) break; }\n      else { if (await attack(them, me, fs)) break; if (await attack(me, them, act.slot)) break; }\n    } else {\n      if (act.type === \"switch\") { await s.msg(`Come back, ${me.mon.nick}!`); await sendOut(act.mon); }\n      else if (act.type === \"item\" && ITEMS[act.id].net && trainer) await s.msg(\"The trainer blocked the net! Don't be a thief!\");\n      else if (act.type === \"item\" && ITEMS[act.id].net) await useNet(act.id);\n      else if (act.type === \"item\") {\n        const max = me.stats.hp;\n        if (me.mon.hp >= max) { await s.msg(\"It won't have any effect.\"); continue; }\n        P.bag[act.id]--;\n        me.mon.hp = Math.min(max, me.mon.hp + ITEMS[act.id].heal);\n        refresh();\n        await s.msg(`${me.mon.nick} regained health!`);\n      } else if (act.type === \"run\") {\n        if (trainer) { await s.msg(\"No! There's no running from a trainer battle!\"); continue; }\n        tries++;\n        if (speed(me) >= speed(them) || rand(256) < Math.floor((speed(me) * 128) / speed(them)) + 30 * tries) { await s.msg(\"Got away safely!\"); ended = \"ran\"; break; }\n        await s.msg(\"Can't escape!\");\n      }\n      if (ended) break;\n      if (opts.tutorial) continue;\n      if (await attack(them, me, foeSlot())) break;\n    }\n  }\n  if (trainer && ended === \"won\") {\n    if (trainer.win) await s.say(trainer.win);\n    const prize = (trainer.money || 20) * foes[foes.length - 1].level;\n    P.money += prize;\n    await s.say(`${P.name} got ${prize} ${Game.CURRENCY} for winning!`);\n  }\n  state.screen = null; state.battle = null; state.dialogue = null;\n  return ended;\n};\n\n/* game/battle/calc.js */\n// Battle maths, the same formulas Gold uses (docs/ENGINE.md). All pure functions.\nconst rand = (n) => Math.floor(Math.random() * n); // 0..n-1\n\nconst growthExp = (kind, n) => (kind === \"fast\" ? Math.floor((4 * n ** 3) / 5) : Math.floor((6 * n ** 3) / 5 - 15 * n ** 2 + 100 * n - 140)); // medium fast / medium slow\nconst levelFor = (kind, exp) => { let l = 1; while (l < 100 && growthExp(kind, l + 1) <= exp) l++; return l; };\n\nconst statOf = (base, dv, level, isHp) => Math.floor(((base + dv) * 2 * level) / 100) + (isHp ? level + 10 : 5);\n// stats object { hp, atk, def, spe, spa, spd } for a mon ({ species, level, dv })\nconst statsFor = (mon) => {\n  const b = SPECIES[mon.species].base, dv = mon.dv, names = [\"hp\", \"atk\", \"def\", \"spe\", \"spa\", \"spd\"];\n  const dvs = [((dv.atk & 1) << 3) | ((dv.def & 1) << 2) | ((dv.spe & 1) << 1) | (dv.spa & 1), dv.atk, dv.def, dv.spe, dv.spa, dv.spa];\n  return Object.fromEntries(names.map((n, i) => [n, statOf(b[i], dvs[i], mon.level, i === 0)]));\n};\n\nconst stageMult = (s) => (s >= 0 ? (2 + s) / 2 : 2 / (2 - s));\n// acc/evasion use the 3/3.. table of Gold (data/battle/accuracy_multipliers.asm), here the usual 3+s / 3\nconst accMult = (s) => (s >= 0 ? (3 + s) / 3 : 3 / (3 - s));\n\n// Damage of one hit. att/def: { mon, stats, stages }. Returns { damage, crit, mult }.\nconst damageOf = (att, def, move) => {\n  const special = SPECIAL_TYPES.has(move.type);\n  const A = (special ? att.stats.spa : att.stats.atk) * stageMult(att.stages[special ? \"spa\" : \"atk\"]);\n  const D = (special ? def.stats.spd : def.stats.def) * stageMult(def.stages[special ? \"spd\" : \"def\"]);\n  const crit = rand(256) < 17;\n  let dmg = Math.floor((Math.floor((2 * att.mon.level) / 5 + 2) * move.power * Math.floor(A)) / Math.max(1, Math.floor(D)) / 50);\n  if (crit) dmg *= 2;\n  dmg = Math.min(dmg, 997) + 2;\n  const types = SPECIES[att.mon.species].types;\n  if (types.includes(move.type)) dmg = Math.floor(dmg * 1.5); // same-type bonus\n  const mult = typeMultiplier(move.type, SPECIES[def.mon.species].types);\n  dmg = Math.floor(dmg * mult);\n  if (mult > 0) dmg = Math.max(1, Math.floor((dmg * (217 + rand(39))) / 255)); // 85-100% spread\n  return { damage: dmg, crit, mult };\n};\n\nconst expGain = (foe, wild = true) => Math.floor(((SPECIES[foe.species].exp * foe.level) / 7) * (wild ? 1 : 1.5));\n\n// Catch chance, as in PokeBallEffect: ((3*max - 2*hp) * rate * net) / (3*max), + status bonus, capped at 255.\nconst catchRate = (foe, maxHp, net) => {\n  let r = Math.floor(((3 * maxHp - 2 * foe.hp) * SPECIES[foe.species].catchRate * net) / (3 * maxHp));\n  r = Math.max(1, r) + (foe.status === \"sleep\" || foe.status === \"freeze\" ? 10 : foe.status ? 5 : 0);\n  return Math.min(255, r);\n};\n// chance (out of 255) that the net keeps shaking for a final catch rate (data/battle/wobble_probabilities.asm)\nconst WOBBLE = [[1, 63], [2, 75], [3, 84], [4, 90], [5, 95], [7, 103], [10, 113], [15, 126], [20, 134], [30, 149], [40, 160], [50, 169], [60, 177], [80, 191], [100, 201], [120, 211], [140, 220], [160, 227], [180, 234], [200, 240], [220, 246], [240, 251], [254, 253], [255, 255]];\n// -> { caught, shakes } for one throw\nconst throwNet = (rate) => {\n  if (rand(256) <= rate) return { caught: true, shakes: 3 };\n  const p = (WOBBLE.find(([r]) => r >= rate) || [0, 255])[1];\n  let shakes = 0;\n  while (shakes < 3 && rand(256) < p) shakes++;\n  return { caught: false, shakes };\n};\n\n// Which period of the day the device clock is in (Gold: morning 4-10, day 10-18, night otherwise).\nconst timeOfDay = () => { const h = new Date().getHours(); return h >= 4 && h < 10 ? \"morn\" : h < 18 && h >= 10 ? \"day\" : \"nite\"; };\n\nconst rollGender = (species) => (Math.random() < SPECIES[species].female ? \"F\" : \"M\");\nconst genderMark = (mon) => (mon.gender === \"F\" ? \"♀\" : \"♂\");\n\n// A fresh buddymon of `species` at `level`: random individual values, full HP, the last four moves it would know.\nconst makeMon = (species, level) => {\n  const dv = { atk: rand(16), def: rand(16), spe: rand(16), spa: rand(16) };\n  const sp = SPECIES[species], learned = [];\n  for (const [lv, list] of Object.entries(sp.moves)) if (+lv <= level) learned.push(...list);\n  const moves = learned.slice(-4).map((id) => ({ id, pp: MOVES[id].pp }));\n  const mon = { species, nick: sp.name, gender: rollGender(species), level, dv, exp: growthExp(sp.growth, level), moves, status: null };\n  mon.hp = statsFor(mon).hp;\n  return mon;\n};\n\n/* game/battle/growth.js */\n// After a win: experience, level-ups and new moves (Gold: exp = base exp * foe level / 7, shared by buddymon that fought).\n// xpBar: how far through the current level a buddymon is, 0..1 (the thin bar under the HP bar on the battle screen).\nconst xpBar = (mon) => { const g = SPECIES[mon.species].growth, a = growthExp(g, mon.level), b = growthExp(g, mon.level + 1); return Math.max(0, Math.min(1, (mon.exp - a) / (b - a || 1))); };\n\nasync function awardExp(s, party, fought, foe, wild, refresh) {\n  const gain = Math.max(1, Math.floor(expGain(foe, wild) / fought.size));\n  for (const mon of [...fought]) {\n    if (mon.hp <= 0) continue;\n    mon.exp += gain;\n    refresh(); // the bar fills (to the brim when a level is earned)\n    await s.msg(`${mon.nick} gained ${gain} EXP. Points!`);\n    const growth = SPECIES[mon.species].growth;\n    while (mon.level < 100 && levelFor(growth, mon.exp) > mon.level) {\n      const before = statsFor(mon).hp;\n      mon.level++;\n      mon.hp += statsFor(mon).hp - before;\n      refresh();\n      await s.msg(`${mon.nick} grew to level ${mon.level}!`);\n      for (const id of SPECIES[mon.species].moves[mon.level] || []) await learn(s, mon, id);\n    }\n  }\n}\n\n// A new move: takes a free slot, otherwise asks which old move to forget.\nasync function learn(s, mon, id) {\n  if (mon.moves.some((m) => m.id === id)) return;\n  if (mon.moves.length < 4) { mon.moves.push({ id, pp: MOVES[id].pp }); return s.msg(`${mon.nick} learned ${MOVES[id].name}!`); }\n  await s.say(`${mon.nick} wants to learn ${MOVES[id].name}, but it already knows four moves. Forget one?`);\n  const pick = await s.menu([...mon.moves.map((m) => MOVES[m.id].name), `Don't learn it`], 1, \"forget\");\n  if (pick < 0 || pick >= mon.moves.length) return s.say(`${mon.nick} did not learn ${MOVES[id].name}.`);\n  await s.say(`${mon.nick} forgot ${MOVES[mon.moves[pick].id].name} and learned ${MOVES[id].name}!`);\n  mon.moves[pick] = { id, pp: MOVES[id].pp };\n}\n\n/* game/battle/moves.js */\n// Using a move in battle: accuracy, damage, stat changes and their messages. `att` and `def` are battle sides:\n// { mon, stats, stages, label } where label is how the game names them in text (\"Wild PIDGEY\", \"BRAMBLET\").\nconst STAT_NAMES = { atk: \"ATTACK\", def: \"DEFENSE\", spa: \"SP. ATK\", spd: \"SP. DEF\", spe: \"SPEED\", acc: \"ACCURACY\", eva: \"EVASION\" };\n\nasync function useMove(s, att, def, slot, refresh, fx) {\n  const mv = MOVES[slot.id];\n  slot.pp--;\n  await s.msg(`${att.label} used ${mv.name}!`);\n  const acc = Math.min(255, Math.floor((mv.acc * 255 / 100) * accMult(att.stages.acc - def.stages.eva)));\n  if (rand(256) >= acc) return s.msg(`${att.label}'s attack missed!`);\n  if (mv.power) {\n    fx(\"hit\"); await s.wait(34);\n    const { damage, crit, mult } = damageOf(att, def, mv);\n    if (mult === 0) return s.msg(`It doesn't affect ${def.label}...`);\n    def.mon.hp = Math.max(0, def.mon.hp - damage);\n    refresh();\n    await s.wait(24);\n    if (crit) await s.msg(\"A critical hit!\");\n    if (mult > 1) await s.msg(\"It's super effective!\");\n    else if (mult < 1) await s.msg(\"It's not very effective...\");\n  }\n  const e = mv.effect;\n  if (e) {\n    if (!mv.power) { fx(e.stages > 0 ? \"up\" : \"down\"); await s.wait(34); }\n    const t = e.target === \"self\" ? att : def, now = t.stages[e.stat], next = Math.max(-6, Math.min(6, now + e.stages));\n    if (next === now) return s.msg(`Nothing happened!`);\n    t.stages[e.stat] = next;\n    await s.msg(`${t.label}'s ${STAT_NAMES[e.stat]} ${e.stages > 0 ? \"rose\" : \"fell\"}!`);\n  }\n}\n\n/* game/menu/card.js */\n// Trainer card, BuddyGear (the clock) and Options.\nGame.cardScreen = async (s) => {\n  const P = s.G.player, owned = new Set([...P.party, ...(P.box || [])].map((m) => m.species)).size;\n  const mins = Math.floor(P.play / 60), time = `${Math.floor(mins / 60)}:${String(mins % 60).padStart(2, \"0\")}`;\n  await s.panel({\n    title: \"TRAINER CARD\", rows: [],\n    lines: [`NAME  ${P.name}`, `ID NO.  ${String(P.id).padStart(5, \"0\")}`, `${Game.CURRENCY}  ${P.money}`, `BUDDYDEX  ${owned} caught`, `PLAY TIME  ${time}`, `BADGES  0 / 8`],\n  });\n};\n\n// BuddyGear shows the device's own clock and date.\nGame.gearScreen = async (s) => {\n  const now = new Date(), day = now.toLocaleDateString(undefined, { weekday: \"long\" });\n  const time = now.toLocaleTimeString(undefined, { hour: \"numeric\", minute: \"2-digit\" });\n  const contacts = [\"MOM\", ...(s.flag(\"GOT_WILLOW_NUMBER\") ? [\"PROF. WILLOW\"] : [])];\n  await s.panel({ title: \"BUDDYGEAR\", rows: [], lines: [time, day, \"\", `Phone: ${contacts.join(\", \")}`] });\n};\n\n// Options: text speed (how long battle messages stay up). Left/right changes the value.\nGame.SPEEDS = { slow: 1500, mid: 900, fast: 450 };\nGame.applyOptions = () => { Game.msgMs = Game.SPEEDS[Game.player.options.speed] ?? 900; };\nGame.optionsScreen = async (s) => {\n  const o = s.G.player.options, names = Object.keys(Game.SPEEDS);\n  for (;;) {\n    const r = await s.panel({ title: \"OPTION\", rows: [{ label: \"TEXT SPEED\", right: `◀ ${o.speed.toUpperCase()} ▶` }], hint: \"Left / right to change\" });\n    if (r.key === \"B\") return;\n    if (r.key === \"L\" || r.key === \"R\" || r.key === \"A\") {\n      o.speed = names[(names.indexOf(o.speed) + (r.key === \"L\" ? names.length - 1 : 1)) % names.length];\n      Game.applyOptions();\n    }\n  }\n};\n\n/* game/menu/center.js */\n// The Buddymon Center nurse: heals the whole party and makes this the place you wake up after a whiteout.\nGame.nurse = async (s, spot) => {\n  await s.say(\"Welcome to our BUDDYMON CENTER! We heal your BUDDYMON back to perfect health.\");\n  if ((await s.confirm(\"Shall we heal your BUDDYMON?\")) !== 0) return s.say(\"We hope to see you again!\");\n  await s.say(\"OK, I'll take your BUDDYMON for a few seconds.\");\n  s.G.state.dialogue = null;\n  for (const m of s.G.player.party) { m.hp = statsFor(m).hp; for (const mv of m.moves) mv.pp = MOVES[mv.id].pp; }\n  s.G.player.lastCenter = spot;\n  await s.wait(90);\n  await s.say(\"Thank you for waiting. We've restored your BUDDYMON to full health.\");\n  await s.say(\"We hope to see you again!\");\n};\n\n/* game/menu/dex.js */\n// BUDDYDEX: every species in order, \"-----\" until you have seen it; a dot for seen, a ball of net for caught.\nGame.dexScreen = async (s) => {\n  const dex = s.G.player.dex || {}, keys = Object.keys(SPECIES);\n  let at = 0;\n  for (;;) {\n    const seen = keys.filter((k) => dex[k]).length, caught = keys.filter((k) => dex[k] === \"caught\").length;\n    const r = await s.panel({\n      title: \"BUDDYDEX\", lines: [`Seen ${seen}   Caught ${caught}`],\n      rows: keys.map((k, n) => ({ label: `No.${String(n + 1).padStart(3, \"0\")}  ${dex[k] ? SPECIES[k].name : \"-----\"}`, right: dex[k] === \"caught\" ? \"caught\" : dex[k] ? \"seen\" : \"\", dim: !dex[k] })),\n    }, at);\n    if (r.key === \"B\") return;\n    if (r.key !== \"A\" || !dex[keys[r.i]]) continue;\n    at = r.i;\n    const sp = SPECIES[keys[at]];\n    await s.panel({ title: sp.name, art: keys[at], rows: [], lines: [`No.${String(at + 1).padStart(3, \"0\")}  ·  ${sp.types.join(\" / \").toUpperCase()}`, dex[keys[at]] === \"caught\" ? \"You have caught this BUDDYMON.\" : \"You have only seen this BUDDYMON so far.\"] });\n  }\n};\n\n/* game/menu/pack.js */\n// Pack screen: three pockets (Items, Nets, Key items) switched with left/right or the tabs; a chosen item offers USE.\nGame.packScreen = async (s) => {\n  const P = s.G.player, POCKETS = [\"items\", \"nets\", \"key\"], LABELS = [\"ITEMS\", \"NETS\", \"KEY ITEMS\"];\n  let tab = 0, at = 0;\n  const keyItems = () => [\n    ...(s.flag(\"GOT_BUDDYGEAR\") ? [{ key: \"buddygear\", name: \"BUDDYGEAR\", count: 0 }] : []),\n    ...(s.flag(\"GOT_MAP_CARD\") ? [{ key: \"mapcard\", name: \"MAP CARD\", count: 0 }] : []),\n    ...Object.keys(P.bag).filter((k) => P.bag[k] > 0 && ITEMS[k] && ITEMS[k].pocket === \"key\").map((k) => ({ key: k, name: ITEMS[k].name, count: 0 })),\n  ];\n  const entries = (pocket) => (pocket === \"key\"\n    ? keyItems()\n    : Object.keys(P.bag).filter((k) => P.bag[k] > 0 && ITEMS[k] && ITEMS[k].pocket === pocket).map((k) => ({ key: k, name: ITEMS[k].name, count: P.bag[k] })));\n  for (;;) {\n    const list = entries(POCKETS[tab]);\n    const r = await s.panel({\n      title: \"PACK\", tabs: LABELS.map((label, n) => ({ label, sel: n === tab })), rows: list.map((e) => ({ label: e.name, right: e.count ? `x${e.count}` : \"\" })),\n      lines: list.length ? [] : [\"Nothing here yet.\"], hint: \"Left / right to change pocket\",\n    }, at);\n    if (r.key === \"B\") return;\n    if (r.key === \"L\" || r.key === \"R\") { tab = (tab + (r.key === \"R\" ? 1 : 2)) % 3; at = 0; continue; }\n    at = r.i;\n    const item = list[r.i];\n    if ((await s.choose([\"USE\", \"CANCEL\"], { c0: 13, r0: 5, cancel: 1 })) !== 0) continue;\n    if (item.key === \"buddygear\") await Game.gearScreen(s);\n    else if (item.key === \"mapcard\" || ITEMS[item.key].pocket === \"key\") await s.say(\"It can't be used here.\");\n    else if (ITEMS[item.key].net) await s.say(\"Nets are for throwing at wild BUDDYMON in battle.\");\n    else {\n      const who = await s.panel({ title: `Use ${ITEMS[item.key].name} on...`, rows: P.party.map((m) => { const max = statsFor(m).hp; return { label: m.nick, g: m.gender, sub: `Lv ${m.level}`, right: `${m.hp}/${max}`, bar: m.hp / max, art: m.species }; }) });\n      if (who.key === \"A\") await Game.useOn(s, item.key, P.party[who.i]);\n    }\n  }\n};\n\n/* game/menu/party.js */\n// Party screen: the list with HP bars; a chosen buddymon offers STATS, SWITCH, ITEM, CANCEL (as in Gold).\n// Using a healing item is shared with the Pack: Game.useOn(s, itemKey, mon).\nGame.useOn = async (s, key, mon) => {\n  const it = ITEMS[key], max = statsFor(mon).hp;\n  if (!it.heal || mon.hp <= 0 || mon.hp >= max) return s.say(\"It won't have any effect.\");\n  const gain = Math.min(it.heal, max - mon.hp);\n  mon.hp += gain;\n  s.G.player.bag[key]--;\n  await s.say(`${mon.nick} regained ${gain} HP.`);\n};\n\nGame.partyScreen = async (s) => {\n  const P = s.G.player, partyRows = () => P.party.map((m) => { const max = statsFor(m).hp; return { label: m.nick, g: m.gender, sub: `Lv ${m.level}`, right: `${m.hp}/${max}`, bar: m.hp / max, art: m.species, dim: m.hp <= 0 }; });\n  const summary = async (m) => {\n    const st = statsFor(m), sp = SPECIES[m.species], next = growthExp(sp.growth, m.level + 1) - m.exp;\n    await s.panel({\n      title: m.nick, g: m.gender, art: m.species, rows: [],\n      lines: [`Lv ${m.level}  ·  ${sp.types.join(\" / \").toUpperCase()}`, `HP ${m.hp}/${st.hp}  ATK ${st.atk}  DEF ${st.def}`, `SP.ATK ${st.spa}  SP.DEF ${st.spd}  SPEED ${st.spe}`, `EXP ${m.exp}  ·  ${next} to next level`, ...m.moves.map((x) => `${MOVES[x.id].name}  ${x.pp}/${MOVES[x.id].pp}`)],\n    });\n  };\n  let at = 0;\n  for (;;) {\n    const r = await s.panel({ title: \"BUDDYMON\", rows: partyRows(), hint: \"Pick one\" }, at);\n    if (r.key === \"B\") return;\n    if (r.key !== \"A\") continue;\n    at = r.i;\n    const mon = P.party[at], pick = await s.choose([\"STATS\", \"SWITCH\", \"ITEM\", \"CANCEL\"], { c0: 12, r0: 5, cancel: 3 });\n    if (pick === 0) await summary(mon);\n    else if (pick === 1 && P.party.length > 1) {\n      const to = await s.panel({ title: `Switch ${mon.nick} with...`, rows: partyRows() }, at);\n      if (to.key === \"A\" && to.i !== at) { [P.party[at], P.party[to.i]] = [P.party[to.i], P.party[at]]; at = to.i; }\n    } else if (pick === 2) {\n      const keys = Object.keys(P.bag).filter((k) => P.bag[k] > 0 && ITEMS[k] && ITEMS[k].heal);\n      if (!keys.length) { await s.say(\"You have nothing to use.\"); continue; }\n      const it = await s.choose([...keys.map((k) => `${ITEMS[k].name} x${P.bag[k]}`), \"CANCEL\"], { c0: 8, r0: 5, cancel: keys.length });\n      if (it < keys.length) await Game.useOn(s, keys[it], mon);\n    }\n  }\n};\n\n/* game/menu/shop.js */\n// Marts: Game.shop(s, stock) where stock is a list of item keys. BUY / SELL / QUIT like Gold's clerk, quantity picked with left/right.\nGame.shop = async (s, stock) => {\n  const P = s.G.player, money = () => `${P.money} ${Game.CURRENCY}`;\n  // How many? Left/right change it, A confirms, B cancels. Returns 0 for cancel.\n  const howMany = async (key, unit, max) => {\n    let q = 1;\n    for (;;) {\n      const r = await s.panel({ title: `${ITEMS[key].name}`, lines: [`You have ${money()}`], rows: [{ label: `x ${q}`, right: `${unit * q} ${Game.CURRENCY}` }], hint: \"Left / right to change\" });\n      if (r.key === \"B\") return 0;\n      if (r.key === \"L\") q = q > 1 ? q - 1 : max;\n      else if (r.key === \"R\") q = q < max ? q + 1 : 1;\n      else return q;\n    }\n  };\n  const buy = async () => {\n    for (;;) {\n      const r = await s.panel({ title: \"BUY\", lines: [`You have ${money()}`], rows: stock.map((k) => ({ label: ITEMS[k].name, right: `${ITEMS[k].price} ${Game.CURRENCY}` })) });\n      if (r.key === \"B\") return;\n      const key = stock[r.i], price = ITEMS[key].price, max = Math.min(99, Math.floor(P.money / price));\n      if (!max) { await s.say(\"You don't have enough money.\"); continue; }\n      const q = await howMany(key, price, max);\n      if (!q) continue;\n      if ((await s.confirm(`${ITEMS[key].name} x${q} will be ${price * q} ${Game.CURRENCY}. Okay?`)) !== 0) continue;\n      P.money -= price * q;\n      s.give(key, q);\n      await s.say(\"Here you are! Thank you!\");\n    }\n  };\n  const sell = async () => {\n    for (;;) {\n      const keys = Object.keys(P.bag).filter((k) => P.bag[k] > 0 && ITEMS[k] && ITEMS[k].price);\n      if (!keys.length) { await s.say(\"You don't have anything to sell.\"); return; }\n      const r = await s.panel({ title: \"SELL\", lines: [`You have ${money()}`], rows: keys.map((k) => ({ label: ITEMS[k].name, sub: `x${P.bag[k]}`, right: `${ITEMS[k].price >> 1} ${Game.CURRENCY}` })) });\n      if (r.key === \"B\") return;\n      const key = keys[r.i], unit = ITEMS[key].price >> 1, q = await howMany(key, unit, P.bag[key]);\n      if (!q) continue;\n      if ((await s.confirm(`I can pay ${unit * q} ${Game.CURRENCY}. Is that okay?`)) !== 0) continue;\n      P.bag[key] -= q;\n      P.money += unit * q;\n      await s.say(`${s.name} sold the ${ITEMS[key].name}.`);\n    }\n  };\n  await s.say(\"Welcome! How may I help you?\");\n  for (;;) {\n    const c = await s.choose([\"BUY\", \"SELL\", \"QUIT\"], { c0: 13, r0: 5, cancel: 2 });\n    s.G.state.dialogue = null;\n    if (c === 0) await buy();\n    else if (c === 1) await sell();\n    else break;\n    s.G.state.panel = null;\n  }\n  s.G.state.panel = null;\n  await s.say(\"Please come again!\");\n};\n\n/* game/menu/startmenu.js */\n// The Start menu: Buddymon, Pack, BuddyGear (once you have it), your name card, Save, Option, Exit. Like Gold's list down the right side.\nGame.startMenu = async (s) => {\n  const P = s.G.player;\n  const save = async () => {\n    if ((await s.confirm(\"Would you like to save the game?\")) !== 0) return;\n    Game.save(true);\n    await s.say(`${s.name} saved the game!`);\n  };\n  for (;;) {\n    const entries = [];\n    if (s.flag(\"GOT_BUDDYDEX\")) entries.push([\"BUDDYDEX\", Game.dexScreen]);\n    if (P.party.length) entries.push([\"BUDDYMON\", Game.partyScreen]);\n    entries.push([\"PACK\", Game.packScreen]);\n    if (s.flag(\"GOT_BUDDYGEAR\")) entries.push([\"BUDDYGEAR\", Game.gearScreen]);\n    entries.push([P.name, Game.cardScreen], [\"SAVE\", save], [\"OPTION\", Game.optionsScreen], [\"EXIT\", null]);\n    const i = await s.choose(entries.map((e) => e[0]), { c0: 10, r0: 0, pos: \"top\", cancel: entries.length - 1 });\n    s.G.state.dialogue = null;\n    if (!entries[i][1]) return;\n    await entries[i][1](s);\n    s.G.state.panel = null;\n  }\n};\n\n/* game/menu/verbs.js */\n// Menu verbs for scripts: choose() draws a small list box (Start menu, Yes/No) and panel() a full-height list screen\n// (party, pack, trainer card...). Arrows + A, B to cancel, or tap a row (Game.pick). Added to the script API by scriptApi().\nfunction menuVerbs(G, s) {\n  const frame = () => new Promise((ok) => requestAnimationFrame(ok));\n  return {\n    // A list box over the scene: pos \"low\" sits just above the message box, \"top\" at the top; c0 >= 7 puts it on the right. Returns the index;\n    // B returns `cancel` when given (e.g. the last row for Yes/No), else B is ignored.\n    async choose(options, { c0 = 14, r0 = 6, pos = \"low\", cancel } = {}) {\n      let i = 0;\n      const show = () => (G.state.boxes = [{ c0, r0, c1: 19, r1: r0 + options.length * 2 + 1, rows: options.map((text, n) => ({ text, selected: n === i })), pos }]);\n      G.picked = null; show();\n      for (Input.clear(); ;) {\n        Input.poll();\n        if (Input.pressed(\"UP\")) { i = (i + options.length - 1) % options.length; show(); }\n        if (Input.pressed(\"DOWN\")) { i = (i + 1) % options.length; show(); }\n        if (Input.pressed(\"A\")) break;\n        if ((Input.pressed(\"B\") || Input.pressed(\"START\")) && cancel !== undefined) { i = cancel; break; }\n        if (G.picked !== null) { i = G.picked; G.picked = null; break; }\n        await frame();\n      }\n      G.state.boxes = [];\n      return i;\n    },\n    ask: (options = [\"YES\", \"NO\"]) => s.choose(options, { cancel: options.length - 1 }),\n    // A full list screen: spec = { title, art, tabs, lines, rows: [{label, right, bar, art, dim}], hint }. Returns { i, key } where key is\n    // \"A\" (row chosen), \"B\" (back), or \"L\"/\"R\" (left/right arrows, for tabs and values). Rows start with `start` selected.\n    async panel(spec, start = 0) {\n      let i = Math.min(start, Math.max(0, spec.rows.length - 1));\n      const show = () => (G.state.panel = { ...spec, sel: i });\n      G.picked = null; show();\n      let out;\n      for (Input.clear(); !out;) {\n        Input.poll();\n        const n = spec.rows.length;\n        if (n && Input.pressed(\"UP\")) i = (i + n - 1) % n;\n        if (n && Input.pressed(\"DOWN\")) i = (i + 1) % n;\n        show();\n        if (n && Input.pressed(\"A\")) out = { i, key: \"A\" };\n        else if (Input.pressed(\"B\")) out = { i, key: \"B\" };\n        else if (Input.pressed(\"LEFT\")) out = { i, key: \"L\" };\n        else if (Input.pressed(\"RIGHT\")) out = { i, key: \"R\" };\n        else if (G.picked !== null) { out = G.picked < 0 ? { i, key: \"B\" } : { i: (i = G.picked), key: \"A\" }; G.picked = null; }\n        else await frame();\n      }\n      return out;\n    },\n  };\n}\n\n/* game/cherrygrove.js */\n// Cherrygrove City: the Mart, the Buddymon Center, the Guide Gent's house and two talk houses around a sea front. 36 x 18 cells, original layout.\n// Gold: CherrygroveCity.asm (read before editing: object positions, connections, terrain; note what we change on purpose)\n// Gold's beats: the Guide Gent shows you around (and gives a MAP CARD), your rival jumps you at the entrance, and you can't leave west or north yet.\n(() => {\n  const cols = 36, rows = 18;\n  const cells = Array.from({ length: rows }, () => Array(cols).fill(\".\"));\n  const put = (kind, ...pts) => pts.forEach(([x, y]) => (cells[y][x] = kind));\n  const fill = (kind, x0, y0, x1, y1) => { for (let y = y0; y <= y1; y++) for (let x = x0; x <= x1; x++) cells[y][x] = kind; };\n  for (let x = 0; x < cols; x++) put(\"T\", [x, 0], [x, 1], [x, rows - 1]);\n  for (let y = 0; y < rows; y++) put(\"T\", [0, y], [cols - 1, y]);\n  for (let x = 28; x < cols; x++) put(\"p\", [x, 9], [x, 10]); // dirt road east to Route 29\n  for (let x = 0; x <= 5; x++) put(\"p\", [x, 9], [x, 10]); // dirt road west (Route 31, not open yet)\n  for (let y = 0; y <= 6; y++) put(\"p\", [15, y], [16, y]); // dirt road north to Route 30\n  fill(\"w\", 5, 12, 17, 16); // the sea: wide, with a west bank across it where the fisher stands (Gold puts him on the far shore)\n  put(\"f\", [12, 9], [14, 4], [33, 5], [2, 8], [26, 16], [4, 11]);\n  put(\"S\", [17, 9], [23, 7], [23, 15], [27, 7]);\n  put(\"T\", [3, 3], [4, 3], [3, 2], [33, 13], [34, 13], [33, 14]);\n\n  const talk = Game.talk;\n  const G = Game;\n\n  // The Guide Gent walks you around town, then gives you a MAP CARD and goes home.\n  const gent = async (s) => {\n    await s.say(\"You're a rookie trainer, aren't you? I can tell! That's OK! Everyone is a rookie at some point! If you'd like, I can teach you a few things.\");\n    if ((await s.ask()) !== 0) return s.say(\"Oh... Fine. Anyway, if you need help, come find me.\");\n    await s.say(\"OK, then! Follow me!\");\n    const GENT = 1, who = () => s.G.state.objects.find((o) => o.id === GENT), at = (x, y) => G.path(who().x, who().y, x, y);\n    await s.follow(GENT, at(29, 8));\n    s.turn(\"player\", 1);\n    await s.say(\"This is a BUDDYMON CENTER. They heal your BUDDYMON in no time at all. You'll be relying on them a lot, so you better learn about them.\");\n    await s.follow(GENT, at(22, 8));\n    s.turn(\"player\", 1);\n    await s.say(\"This is a BUDDYMON MART. They sell NETS for catching wild BUDDYMON and other useful items.\");\n    await s.follow(GENT, at(16, 3));\n    s.turn(\"player\", 1);\n    await s.say(\"ROUTE 30 is out this way. Trainers will be battling their prized BUDDYMON there.\");\n    await s.follow(GENT, at(12, 11));\n    s.turn(\"player\", 2);\n    await s.say(\"This is the sea, as you can see. Some BUDDYMON are found only in water.\");\n    await s.follow(GENT, at(22, 15));\n    s.turn(GENT, 2); s.turn(\"player\", 3);\n    await s.say(\"Here, I'll give you something for your trip.\");\n    s.flag(\"GOT_MAP_CARD\", true);\n    await s.say(`${s.name} got a MAP CARD!`);\n    await s.say(\"It adds a map to your BUDDYGEAR. Now you can find your way around!\");\n    s.turn(\"player\", 1);\n    await s.move(GENT, [...at(21, 15), 1]); // home through his front door\n    s.hide(GENT);\n    s.flag(\"GENT_GONE_HOME\", true);\n  };\n\n  // Your rival ambushes you at the east entrance with his own starter, then shoves past.\n  const RIVAL = 6;\n    const rival = async (s) => {\n    if (!s.flag(\"GOT_EGG\") || s.flag(\"RIVAL_CHERRYGROVE_DONE\")) return; // he waits for you on the way back from the errand\n    s.G.state.objects.push({ id: RIVAL, name: \"RIVAL\", x: 35, y: s.G.state.y, dir: 2 });\n    s.turn(\"player\", 3);\n    await s.approach(RIVAL, 3);\n    await s.say(`${Game.rivalName(s.G.player)}: ...Hold it. You got a BUDDYMON at the LAB. What a waste. A wimp like you with a BUDDYMON? ...Let's see how good you are.`);\n    const result = await Game.battle(s, makeMon(Game.rivalSpecies(s.G.player), 6), { trainer: { name: Game.rivalName(s.G.player), money: 60, win: \"...Humph. You got lucky. Don't get cocky.\" } });\n    if (result === \"lost\") {\n      for (const m of s.G.player.party) { m.hp = statsFor(m).hp; for (const mv of m.moves) mv.pp = MOVES[mv.id].pp; }\n      await s.say(`${Game.rivalName(s.G.player)}: Ha! I knew it. Weaklings like you don't deserve BUDDYMON.`);\n    }\n    for (const m of s.G.player.party) { m.hp = statsFor(m).hp; for (const mv of m.moves) mv.pp = MOVES[mv.id].pp; }\n    await s.move(\"player\", [1], 3); // he barges past, shoving you aside, and walks off into town\n    await s.move(RIVAL, [2, 2, 2, 2, 2, 2, 2, 2]);\n    s.hide(RIVAL);\n    s.flag(\"RIVAL_CHERRYGROVE_DONE\", true);\n  };\n\n  Game.register(\"cherrygrove\", {\n    world: {\n      label: \"Cherrygrove City\", cols, rows, cells: cells.map((r) => r.join(\"\")),\n      buildings: [\n        { x: 20, y: 3, w: 5, h: 4, door: 2, to: \"cgmart\", tx: 2, ty: 6, dir: 1, roof: \"#3a8fd9\", label: \"MART\" },\n        { x: 27, y: 3, w: 5, h: 4, door: 2, to: \"cgcenter\", tx: 3, ty: 6, dir: 1, roof: \"#e04a5a\", label: \"HEAL\" },\n        { x: 6, y: 4, w: 5, h: 4, door: 2, to: \"cggym\", tx: 2, ty: 6, dir: 1, roof: \"#9a6ad9\" },\n        { x: 19, y: 11, w: 5, h: 4, door: 2, to: \"cggent\", tx: 2, ty: 6, dir: 1, roof: \"#d9a03a\" },\n        { x: 28, y: 11, w: 5, h: 4, door: 2, to: \"cgevo\", tx: 2, ty: 6, dir: 1, roof: \"#5aa860\" },\n      ],\n    },\n    warps: [9, 10].map((y) => ({ x: 35, y, to: \"route29\", tx: 1, ty: y, dir: 2 })).concat([15, 16].map((x) => ({ x, y: 0, to: \"route30\", tx: x, ty: 38, dir: 1 }))),\n    coords: [\n      ...[9, 10].map((y) => ({ x: 33, y, script: rival })),\n      ...[9, 10].map((y) => ({ x: 0, y, script: async (s) => { await s.say(\"ROUTE 31 is not open yet. Come back soon!\"); await s.move(\"player\", [3]); } })),\n    ],\n    npcs: [\n      { id: 1, name: \"GRAMPS\", x: 31, y: 8, dir: 0, hideIf: \"GENT_GONE_HOME\", script: gent },\n      { id: 2, name: \"TEACHER\", x: 26, y: 12, dir: 2, wander: \"horizontal\", script: talk((s) => (s.flag(\"GOT_MAP_CARD\") ? \"Did you get a MAP CARD? It makes finding your way around much easier.\" : \"Did you meet the old man? He's a bit of a talker, but he knows the town.\")) },\n      { id: 3, name: \"YOUNGSTER\", x: 22, y: 9, dir: 3, wander: \"horizontal\", script: talk((s) => (s.flag(\"GOT_BUDDYDEX\") ? \"I see you have a BUDDYDEX. You must be good!\" : \"I'm going to be a great trainer! I just need a BUDDYDEX first, they say.\")) },\n      {\n        id: 4, name: \"FISHER\", x: 3, y: 13, dir: 3,\n        script: async (s) => {\n          if (s.flag(\"GOT_TIDE_CHARM\")) return s.say(\"That TIDE CHARM is a keepsake from the sea. Water BUDDYMON love it.\");\n          await s.say(\"You're a trainer too? Collecting them, eh? I like your style! Here, take this. It's a TIDE CHARM from the deep sea.\");\n          s.give(\"tide_charm\");\n          s.flag(\"GOT_TIDE_CHARM\", true);\n          await s.say(`${s.name} got a TIDE CHARM!`);\n        },\n      },\n    ],\n    signs: [\n      { x: 17, y: 9, script: talk(\"CHERRYGROVE CITY. A city of sea breezes and blooming cherries.\") },\n      { x: 23, y: 7, script: talk(\"BUDDYMON MART\") },\n      { x: 27, y: 7, script: talk(\"BUDDYMON CENTER\") },\n      { x: 23, y: 15, script: talk(\"GUIDE GENT'S HOUSE\") },\n    ],\n  });\n})();\n\n/* game/cherryhouses.js */\n// Cherrygrove's interiors: the Mart (a clerk behind the counter), the Buddymon Center (the nurse), and three small houses.\n// Gold: CherrygroveMart.asm, CherrygrovePokecenter1F.asm, GuideGentsHouse.asm, CherrygroveGymSpeechHouse.asm, CherrygroveEvolutionSpeechHouse.asm (read before editing: object positions, connections, terrain; note what we change on purpose)\n// Counter cells act as the clerk/nurse: face them and press A, as in Gold.\n(() => {\n  const rect = (x0, y0, x1, y1) => { const o = []; for (let y = y0; y <= y1; y++) for (let x = x0; x <= x1; x++) o.push(`${x},${y}`); return o; };\n  const grid = (w, h, blocked) => Array.from({ length: h }, (_, y) => Array.from({ length: w }, (_, x) => (blocked.has(`${x},${y}`) ? \"#\" : \".\")).join(\"\"));\n  const talk = Game.talk;\n  const exit = (xs, to, tx, ty, y = 7) => xs.map((x) => ({ x, y, to, tx, ty, dir: 0 }));\n\n  // --- Mart (12 x 8): shelves along the back wall, counter at (0..2,4), clerk behind it\n  const clerk = async (s) => { await Game.shop(s, s.flag(\"GAVE_EGG\") ? [\"tonic\", \"buddy_net\"] : [\"tonic\"]); };\n  Game.register(\"cgmart\", {\n    room: { art: \"cherrygroveMart\", cols: 12, rows: 8, label: \"Cherrygrove · Mart\" },\n    solid: grid(12, 8, new Set([...rect(0, 0, 11, 0), ...rect(3, 1, 11, 1), ...rect(0, 4, 2, 4)])),\n    warps: exit([2, 3], \"cherrygrove\", 22, 7),\n    npcs: [\n      { id: 1, name: \"CLERK\", x: 1, y: 3, dir: 0, faces: false, script: clerk },\n      { id: 2, name: \"COOLTRAINER_M\", x: 7, y: 6, dir: 2, wander: \"horizontal\", script: talk((s) => (s.flag(\"GAVE_EGG\") ? \"BUDDY NETS are in stock! Now I can catch BUDDYMON!\" : \"They're fresh out of BUDDY NETS! When will they get more of them?\")) },\n      { id: 3, name: \"YOUNGSTER\", x: 2, y: 5, dir: 0, script: talk(\"When I was walking in the grass, a bug BUDDYMON poisoned my BUDDYMON! I just kept going, but then my BUDDYMON fainted. You should keep an ANTIDOTE with you.\") },\n    ],\n    signs: [0, 1, 2].map((x) => ({ x, y: 4, script: clerk })),\n  });\n\n  // --- Center (10 x 8): counter (0..5,2), nurse at (3,1), machine and PC against the wall\n  const nurse = (s) => Game.nurse(s, { map: \"cgcenter\", x: 3, y: 6, dir: 1 });\n  Game.register(\"cgcenter\", {\n    room: { art: \"pokecenter\", cols: 10, rows: 8, label: \"Cherrygrove · Buddymon Center\" },\n    solid: grid(10, 8, new Set([...rect(0, 0, 9, 0), ...rect(0, 1, 2, 1), ...rect(5, 1, 5, 1), ...rect(9, 1, 9, 1), ...rect(0, 2, 5, 2), ...rect(7, 5, 8, 5), ...rect(7, 7, 8, 7)])),\n    warps: exit([3, 4], \"cherrygrove\", 29, 7),\n    npcs: [\n      { id: 1, name: \"NURSE\", x: 3, y: 1, dir: 0, faces: false, script: nurse },\n      { id: 2, name: \"FISHER\", x: 2, y: 3, dir: 1, script: talk(\"It's great. I can store any number of BUDDYMON, and it's all free.\") },\n      { id: 3, name: \"GENTLEMAN\", x: 8, y: 6, dir: 1, script: talk(\"That PC is free for any trainer to use.\") },\n      { id: 4, name: \"TEACHER\", x: 1, y: 6, dir: 3, script: talk((s) => (s.flag(\"GAVE_EGG\") ? \"The COMMUNICATION CENTER upstairs was just built. It should open soon.\" : \"The COMMUNICATION CENTER upstairs was just built. But they're still finishing it up.\")) },\n    ],\n    signs: [\n      ...[0, 1, 2, 3, 4, 5].map((x) => ({ x, y: 2, script: nurse })),\n      { x: 9, y: 1, script: talk((s) => `${s.name} turned on the PC.`, \"The BUDDYMON storage system is not online yet.\") },\n    ],\n  });\n\n  // --- Small houses: all share the 8 x 8 living room art (shelves (0..1,1), TV (2,1), table (3..4,3..4), radio (7,1))\n  const house = (key, out, label, npcs, signs = []) => Game.register(key, {\n    room: { art: \"neighborHouse\", cols: 8, rows: 8, label: `Cherrygrove · ${label}` },\n    solid: grid(8, 8, new Set([...rect(0, 0, 7, 0), ...rect(0, 1, 2, 1), ...rect(7, 1, 7, 1), ...rect(3, 3, 4, 4), ...rect(0, 6, 0, 7), ...rect(7, 6, 7, 7)])),\n    warps: exit([2, 3], \"cherrygrove\", out[0], out[1]),\n    npcs,\n    signs: [0, 1].map((x) => ({ x, y: 1, script: talk(\"A shelf of BUDDYMON books and magazines.\") })).concat(signs),\n  });\n  house(\"cggent\", [21, 15], \"Guide Gent's House\", [\n    { id: 1, name: \"GRAMPS\", x: 2, y: 3, dir: 3, script: talk(\"When I was a wee lad, I was a hotshot trainer! Here's a word of advice: Catch lots of BUDDYMON! Treat them all with kindness!\") },\n  ]);\n  house(\"cggym\", [8, 8], \"Gym Talk House\", [\n    { id: 1, name: \"POKEFAN_M\", x: 2, y: 3, dir: 0, script: talk(\"You're trying to see how good you are as a BUDDYMON trainer? You better visit the BUDDYMON GYMS all over JOHTO and collect BADGES.\") },\n    { id: 2, name: \"BUG_CATCHER\", x: 5, y: 5, dir: 2, wander: \"horizontal\", script: talk(\"When I get older, I'm going to be a GYM LEADER! I make my BUDDYMON battle with my friend's to make them tougher!\") },\n  ]);\n  house(\"cgevo\", [30, 15], \"Evolution Talk House\", [\n    { id: 1, name: \"LASS\", x: 3, y: 5, dir: 2, script: talk(\"BUDDYMON change? I would be shocked if one did that!\") },\n    { id: 2, name: \"YOUNGSTER\", x: 2, y: 5, dir: 3, script: talk(\"BUDDYMON gain experience in battle and change their form.\") },\n  ]);\n})();\n\n/* game/home.js */\n// Scene 1: your room (upstairs) and the living room. Original text; same beats as Gold's start.\n// Gold: PlayersHouse1F.asm, PlayersHouse2F.asm (read before editing: object positions, connections, terrain; note what we change on purpose)\n// Cells match the art in art/room.js and art/room1F.js.\n(() => {\n  const solidGrid = (w, h, blocked) => Array.from({ length: h }, (_, y) => Array.from({ length: w }, (_, x) => (blocked.has(`${x},${y}`) ? \"#\" : \".\")).join(\"\"));\n  const rect = (x0, y0, x1, y1) => { const out = []; for (let y = y0; y <= y1; y++) for (let x = x0; x <= x1; x++) out.push(`${x},${y}`); return out; };\n  const talk = Game.talk;\n\n  Game.register(\"bedroom\", {\n    room: { art: \"room\", cols: 8, rows: 6, label: \"Home · Your Room\" },\n    solid: solidGrid(8, 6, new Set([...rect(0, 0, 6, 0), ...rect(2, 1, 5, 1), ...rect(4, 2, 4, 2), ...rect(4, 4, 5, 4), ...rect(0, 4, 0, 5)])),\n    warps: [{ x: 7, y: 0, to: \"livingroom\", tx: 9, ty: 1, dir: 0 }],\n    signs: [\n      { x: 2, y: 1, script: talk(\"The PC is off. Nothing to do on it yet.\") },\n      { x: 3, y: 1, script: talk(\"An old radio. Only static right now.\") },\n      { x: 4, y: 2, script: talk((s) => `${s.name} played a game for a while. Time to stop!`) },\n      { x: 5, y: 1, script: talk(\"A shelf full of picture books about buddymon.\") },\n    ],\n  });\n\n  Game.register(\"livingroom\", {\n    room: { art: \"room1F\", cols: 10, rows: 8, label: \"Home · Living Room\" },\n    solid: solidGrid(10, 8, new Set([...rect(0, 0, 8, 0), ...rect(0, 1, 5, 1), ...rect(3, 2, 3, 3), ...rect(5, 3, 6, 4)])),\n    warps: [{ x: 9, y: 0, to: \"bedroom\", tx: 7, ty: 1, dir: 0 }, { x: 6, y: 7, to: \"newbark\", tx: 5, ty: 9, dir: 0 }, { x: 7, y: 7, to: \"newbark\", tx: 5, ty: 9, dir: 0 }],\n    npcs: [{\n      id: 1, name: \"MOM\", x: 7, y: 3, dir: 2,\n      script: async (s) => {\n        if (!s.flag(\"GOT_BUDDYGEAR\")) return;\n        await s.say(s.flag(\"GOT_STARTER\") ? \"Welcome home! Tell me all about your buddymon.\" : \"PROF. WILLOW is waiting for you. Hurry up!\");\n      },\n    }],\n    signs: [\n      { x: 4, y: 1, script: talk(\"The TV is showing a show about faraway towns.\") },\n      { x: 0, y: 1, script: talk(\"The stove is warm. Something smells good.\") },\n      { x: 1, y: 1, script: talk(\"The sink is spotless.\") },\n      { x: 2, y: 1, script: talk(\"The fridge hums quietly. It is full of food.\") },\n    ],\n    // Like Gold: Mom spots you on the stairs, walks over to give you the BUDDYGEAR, then walks back.\n    enter: async (s) => {\n      if (s.flag(\"GOT_BUDDYGEAR\")) return;\n      s.turn(1, 1);\n      await s.wait(30);\n      await s.move(1, [3, 3, 1]);\n      s.turn(\"player\", 0);\n      await s.say(`Oh, ${s.name}! PROF. WILLOW from next door was looking for you.`);\n      await s.say(\"He wants you to do something for him. Oh, and your BUDDYGEAR came back from the repair shop!\");\n      s.flag(\"GOT_BUDDYGEAR\", true);\n      await s.say(`${s.name} got the BUDDYGEAR!`);\n      await s.say(\"It is a handy device. You can use it to call your friends. Now go see PROF. WILLOW. His lab is just next door!\");\n      await s.move(1, [0, 2, 2]);\n      s.turn(1, 2);\n    },\n  });\n})();\n\n/* game/mrbuddymon.js */\n// Mr. Buddymon's house: Willow's errand. He hands you the MYSTERY EGG, PROF. ASPEN drops in and gives you the BUDDYDEX, and your\n// Gold: MrPokemonsHouse.asm (read before editing: object positions, connections, terrain; note what we change on purpose)\n// buddymon get a rest. Then BuddyGear rings: someone broke into the lab. (Same beats as Gold; the rival \"steals\" the starter you didn't pick.)\n(() => {\n  const rect = (x0, y0, x1, y1) => { const o = []; for (let y = y0; y <= y1; y++) for (let x = x0; x <= x1; x++) o.push(`${x},${y}`); return o; };\n  const blocked = new Set([...rect(0, 0, 7, 0), ...rect(0, 1, 1, 1), ...rect(6, 1, 7, 1), ...rect(4, 3, 7, 3), ...rect(4, 4, 5, 4), ...rect(0, 6, 0, 7)]);\n  const talk = Game.talk;\n  const MR = 1, ASPEN = 2;\n\n  const errand = async (s) => {\n    if (s.flag(\"GOT_EGG\")) return;\n    await s.emote(MR);\n    s.turn(MR, 0);\n    await s.say(`Hello, hello! You must be ${s.name}. PROF. WILLOW said that you would visit.`);\n    await s.move(\"player\", [3]);\n    s.turn(\"player\", 1);\n    await s.say(\"This is what I want PROF. WILLOW to examine.\");\n    s.give(\"mystery_egg\");\n    await s.say(`${s.name} received the MYSTERY EGG.`);\n    s.flag(\"GOT_EGG\", true);\n    s.G.player.lastCenter = { map: \"cgcenter\", x: 3, y: 6, dir: 1 }; // blackouts now bring you back to Cherrygrove\n    await s.say(\"I know a couple who run a BUDDYMON DAY-CARE service. They gave me that EGG. I was intrigued, so I sent mail to PROF. WILLOW.\");\n    await s.say(\"For BUDDYMON evolution, PROF. WILLOW is the authority.\");\n    s.turn(MR, 3);\n    await s.say(\"Even PROF. ASPEN here recognizes that.\");\n    s.turn(MR, 0);\n    s.turn(ASPEN, 2);\n    await s.say(\"If my assumption is correct, PROF. WILLOW will know it.\");\n    await s.move(ASPEN, [0, 2, 2]);\n    s.turn(\"player\", 3);\n    await s.say(`ASPEN: Aha! So you're ${s.name}! I'm ASPEN! A BUDDYMON researcher. I was just visiting my old friend MR. BUDDYMON.`);\n    await s.say(\"I heard you were running an errand for PROF. WILLOW, so I waited here. Oh! What's this? A rare BUDDYMON egg!\");\n    await s.say(\"Hm, I see! I understand why PROF. WILLOW gave you a BUDDYMON for this errand. To researchers like PROF. WILLOW and I, BUDDYMON are our friends. He saw that you would treat your BUDDYMON with love and care.\");\n    await s.say(\"...Ah! You seem to be dependable. How would you like to help me out? See? This is the latest version of BUDDYDEX. It automatically records data on BUDDYMON you've seen or caught. It's a hi-tech encyclopedia!\");\n    s.flag(\"GOT_BUDDYDEX\", true);\n    await s.say(`${s.name} received BUDDYDEX!`);\n    await s.say(`Go meet many kinds of BUDDYMON and complete that BUDDYDEX! But I've stayed too long. I have to get to GOLDENROD for my usual radio show. ${s.name}, I'm counting on you!`);\n    s.turn(\"player\", 0);\n    await s.move(ASPEN, [0, 2]);\n    s.hide(ASPEN);\n    await s.wait(15);\n    s.turn(\"player\", 1);\n    await s.say(\"You are returning to PROF. WILLOW? Here. Your BUDDYMON should have some rest.\");\n    s.G.state.dialogue = null;\n    for (const m of s.G.player.party) { m.hp = statsFor(m).hp; for (const mv of m.moves) mv.pp = MOVES[mv.id].pp; }\n    await s.wait(60);\n    await s.say(\"I'm depending on you!\");\n    // Back at the lab someone has broken in and taken the starter you did not choose... the one your rival picked.\n    s.flag(\"TOOK_\" + Game.rivalSpecies(s.G.player), true);\n    s.flag(\"RIVAL_NEWBARK_GONE\", true);\n    s.flag(\"COP_IN_LAB\", true);\n    await s.say(\"BUDDYGEAR is ringing...\");\n    await s.say(`PROF. WILLOW: ${s.name}, it's WILLOW! Something terrible has happened! Someone broke into the lab and stole a BUDDYMON! I'd like you to come back to the lab as soon as you can.`);\n  };\n\n  Game.register(\"mrbuddy\", {\n    room: { art: \"mrBuddymonHouse\", cols: 8, rows: 8, label: \"Route 30 · Mr. Buddymon's House\" },\n    solid: Array.from({ length: 8 }, (_, y) => Array.from({ length: 8 }, (_, x) => (blocked.has(`${x},${y}`) ? \"#\" : \".\")).join(\"\")),\n    warps: [2, 3].map((x) => ({ x, y: 7, to: \"route30\", tx: 16, ty: 7, dir: 0 })),\n    npcs: [\n      {\n        id: MR, name: \"GENTLEMAN\", x: 3, y: 5, dir: 3,\n        script: talk((s) => (s.flag(\"GAVE_EGG\") ? \"Life is delightful! Always, new discoveries to be made!\" : \"I'm depending on you!\")),\n      },\n      { id: ASPEN, name: \"ASPEN\", x: 6, y: 5, dir: 1, hideIf: \"GOT_EGG\", script: talk(\"...\") },\n    ],\n    signs: [\n      ...[0, 1].map((x) => ({ x, y: 1, script: talk(\"It's packed with foreign magazines. Can't even read their titles...\") })),\n      ...[6, 7].map((x) => ({ x, y: 1, script: talk(\"It's a big computer. Hmm. It's broken.\") })),\n      { x: 6, y: 4, script: talk(\"A whole pile of strange coins! Maybe they're from another country...\") },\n    ],\n    enter: errand,\n  });\n})();\n\n/* game/neighbor.js */\n// The neighbor's house (cells match art/neighborHouse.js): shelves (0..1,1), TV (2,1), radio (7,1), table (3..4,3..4). The neighbor's daughter is the only one home.\n// Gold: PlayersNeighborsHouse.asm (read before editing: object positions, connections, terrain; note what we change on purpose)\n(() => {\n  const rect = (x0, y0, x1, y1) => { const o = []; for (let y = y0; y <= y1; y++) for (let x = x0; x <= x1; x++) o.push(`${x},${y}`); return o; };\n  const blocked = new Set([...rect(0, 0, 7, 0), ...rect(0, 1, 2, 1), ...rect(7, 1, 7, 1), ...rect(3, 3, 4, 4), ...rect(0, 6, 0, 7), ...rect(7, 6, 7, 7)]);\n  const talk = Game.talk;\n  Game.register(\"neighbor\", {\n    room: { art: \"neighborHouse\", cols: 8, rows: 8, label: \"New Bark Town · Neighbors' House\" },\n    solid: Array.from({ length: 8 }, (_, y) => Array.from({ length: 8 }, (_, x) => (blocked.has(`${x},${y}`) ? \"#\" : \".\")).join(\"\")),\n    warps: [2, 3].map((x) => ({ x, y: 7, to: \"newbark\", tx: 5, ty: 16, dir: 0 })),\n    npcs: [{\n      id: 1, name: \"COOLTRAINER_F\", x: 2, y: 3, dir: 3,\n      script: talk(\"A buddymon that evolves is a wonder. I was amazed by PROF. WILLOW's findings.\", \"He's so famous for his research on BUDDYMON evolution. ...sigh... I wish I could be a researcher like him...\"),\n    }],\n    signs: [\n      { x: 0, y: 1, script: talk(\"A shelf of magazines about BUDDYMON trainers.\") },\n      { x: 1, y: 1, script: talk(\"A shelf of magazines about BUDDYMON trainers.\") },\n      {\n        x: 7, y: 1,\n        script: async (s) => {\n          await s.say(\"Tuning in to BUDDYMON TALK with PROF. ASPEN...\");\n          await s.say(\"...BUDDYMON CHANNEL!\");\n        },\n      },\n    ],\n  });\n})();\n\n/* game/newbark.js */\n// New Bark Town: four buildings (your house, the neighbor's, Willow's lab and Willow's house), a pond, and the road west to Route 29.\n// Gold: NewBarkTown.asm (read before editing: object positions, connections, terrain; note what we change on purpose)\n// Same beats as Gold's town: a teacher who stops you leaving without a buddymon, a villager who paces, and a rival lurking by the lab.\n// 22 x 18 cells, original layout.\n(() => {\n  const cols = 22, rows = 18;\n  const cells = Array.from({ length: rows }, () => Array(cols).fill(\".\"));\n  const put = (kind, ...pts) => pts.forEach(([x, y]) => (cells[y][x] = kind));\n  for (let x = 0; x < cols; x++) put(\"T\", [x, 0], [x, 1], [x, rows - 1]);\n  for (let y = 0; y < rows; y++) put(\"T\", [cols - 1, y], [0, y]);\n  for (let y = 13; y <= 15; y++) for (let x = 9; x <= 11; x++) put(\"w\", [x, y]);\n  for (let x = 0; x <= 9; x++) put(\"p\", [x, 9], [x, 10]); // the dirt road west, wide and open to the edge\n  put(\"f\", [2, 7], [9, 5], [20, 9], [18, 13], [12, 16], [6, 3], [1, 15]);\n  put(\"S\", [10, 9], [8, 7], [12, 5], [13, 14], [8, 14]); // signs stand beside buildings, never in front of a door: town, your house, lab, Willow's house, neighbors'\n  put(\"T\", [1, 14], [2, 14], [1, 13]);\n\n  const talk = Game.talk;\n  const hasMon = (s) => s.flag(\"GOT_STARTER\");\n\n  // Without a buddymon the teacher runs over, scolds you, and walks you back into town.\n  const teacherStops = async (s) => {\n    if (hasMon(s)) return;\n    const t = 1;\n    await s.say(\"Wait, \" + s.name + \"!\");\n    await s.approach(t, 3);\n    s.turn(\"player\", 3);\n    await s.say(\"What do you think you're doing?\");\n    await s.walk([[t, [3, 3, 3, 3]], [\"player\", [3, 3, 3, 3]]]);\n    s.turn(t, 2);\n    await s.say(\"It's dangerous to go out without a BUDDYMON! Wild BUDDYMON jump out of the grass on the way to the next town.\");\n  };\n\n  // The rival lurks beside the lab, grumbles, and shoves you away.\n  const rival = async (s) => {\n    await s.say(\"...So this is the famous WILLOW BUDDYMON LAB...\");\n    s.turn(3, 2);\n    await s.say(\"...What are you staring at?\");\n    s.turn(3, 0);\n    const away = [1, 0, 3, 2][s.G.state.dir]; // shoved straight back from where you stood\n    await s.move(\"player\", [away, away], s.G.state.dir);\n    s.turn(3, 3);\n  };\n\n  Game.register(\"newbark\", {\n    world: {\n      label: \"New Bark Town\", cols, rows, cells: cells.map((r) => r.join(\"\")),\n      buildings: [\n        { x: 13, y: 2, w: 7, h: 5, door: 3, to: \"willowlab\", tx: 4, ty: 11, dir: 1, roof: \"#5aa860\", wall: \"#eaf3ff\", label: \"LAB\" },\n        { x: 3, y: 5, w: 5, h: 4, door: 2, to: \"livingroom\", tx: 7, ty: 6, dir: 1 },\n        { x: 3, y: 12, w: 5, h: 4, door: 2, to: \"neighbor\", tx: 3, ty: 6, dir: 1, roof: \"#3a8fd9\" },\n        { x: 14, y: 12, w: 5, h: 4, door: 2, to: \"willowhouse\", tx: 3, ty: 6, dir: 1, roof: \"#9a6ad9\" },\n      ],\n    },\n    npcs: [\n      {\n        id: 1, name: \"TEACHER\", x: 7, y: 11, dir: 2, wander: \"spin\",\n        script: async (s) => { await s.say(hasMon(s) ? \"Oh! Your BUDDYMON is adorable! I wish I had one!\" : \"Wow, your BUDDYGEAR is impressive! Did your mom get it for you?\"); },\n      },\n      { id: 2, name: \"FISHER\", x: 11, y: 9, dir: 0, wander: \"vertical\", script: talk((s) => `Yo, ${s.name}! I hear PROF. WILLOW discovered some new BUDDYMON.`) },\n      { id: 3, name: \"RIVAL\", x: 12, y: 4, dir: 3, hideIf: \"RIVAL_NEWBARK_GONE\", script: rival },\n    ],\n    signs: [\n      { x: 10, y: 9, script: talk(\"NEW BARK TOWN. The town where the winds of a new beginning blow.\") },\n      { x: 8, y: 7, script: talk((s) => `${s.name}'s house`) },\n      { x: 12, y: 5, script: talk(\"WILLOW BUDDYMON LAB\") },\n      { x: 13, y: 14, script: talk(\"WILLOW'S HOUSE\") },\n      { x: 8, y: 14, script: talk(\"The neighbors' house\") },\n    ],\n    coords: [\n      ...[9, 10].map((y) => ({ x: 1, y, script: teacherStops })),\n    ],\n    warps: [9, 10].map((y) => ({ x: 0, y, to: \"route29\", tx: 54, ty: y, dir: 2 })), // the road west: Route 29\n  });\n})();\n\n/* game/route29.js */\n// Route 29: the road west of New Bark Town to Cherrygrove. Tall grass with wild buddymon (Gold's table), a ledge, an item,\n// Gold: Route29.asm (read before editing: object positions, connections, terrain; note what we change on purpose)\n// a berry tree, a gate north to Route 46, and travellers to talk to. 56 x 16 cells, original layout.\n(() => {\n  const cols = 56, rows = 16;\n  const cells = Array.from({ length: rows }, () => Array(cols).fill(\".\"));\n  const put = (kind, ...pts) => pts.forEach(([x, y]) => (cells[y][x] = kind));\n  const fill = (kind, x0, y0, x1, y1) => { for (let y = y0; y <= y1; y++) for (let x = x0; x <= x1; x++) cells[y][x] = kind; };\n  for (let x = 0; x < cols; x++) put(\"T\", [x, 0], [x, 1], [x, rows - 1], [x, rows - 2]);\n  for (let y = 0; y < rows; y++) put(\"T\", [0, y], [cols - 1, y]);\n  // Two lanes. West-bound you walk the south lane, and it is all tall grass. East-bound you can walk the north lane (no grass) and hop\n  // the ledge at its east end back down to the New Bark side. The ledge only goes down, so from the south lane you cannot get up to it.\n  fill(\"T\", 8, 7, 40, 7); fill(\"v\", 41, 7, 46, 7);\n  fill(\"T\", 47, 7, 54, 7);\n  fill(\"g\", 8, 8, 40, 13);\n  fill(\"p\", 47, 9, 55, 10); fill(\"p\", 0, 9, 7, 10); // dirt road at both ends, running out of the map\n  put(\"T\", [24, 10], [25, 10], [24, 11], [16, 12], [31, 8], [10, 4], [11, 4], [34, 5], [3, 3], [4, 3], [3, 4], [50, 12], [51, 12], [45, 11], [46, 11], [46, 12]);\n  put(\"f\", [4, 11], [20, 3], [48, 11], [53, 12], [2, 5], [28, 6]);\n  put(\"S\", [52, 8], [3, 8]);\n\n  const talk = Game.talk;\n  const wild = (a, b, c, d, e, f, g) => [a, b, c, d, e, f, g];\n  const MORN = wild([2, \"chirplet\"], [3, \"peekat\"], [3, \"chirplet\"], [2, \"peekat\"], [4, \"nibblet\"], [4, \"chirplet\"], [4, \"chirplet\"]);\n  const NITE = wild([2, \"hootling\"], [3, \"hootling\"], [3, \"hootling\"], [2, \"nibblet\"], [4, \"nibblet\"], [4, \"hootling\"], [4, \"hootling\"]);\n\n  // Gold's catching lesson: after the egg errand the dude at the New Bark end walks over and shows you how, in a scripted battle.\n  const lesson = async (s) => {\n    if (!s.flag(\"GAVE_EGG\") || s.flag(\"LEARNED_TO_CATCH\")) return;\n    const DUDE = 1, dude = () => s.G.state.objects.find((o) => o.id === DUDE);\n    await s.emote(DUDE);\n    await s.approach(DUDE, 1);\n    s.turn(\"player\", 1);\n    await s.say(\"I've seen you a couple times. How many BUDDYMON have you caught? Would you like me to show you how to catch BUDDYMON?\");\n    if ((await s.ask()) !== 0) return s.say(\"Oh. Fine, then. Anyway, if you want to catch BUDDYMON, you have to walk a lot.\");\n    await s.say(\"OK, watch closely! Follow me.\");\n    await s.follow(DUDE, s.G.path(dude().x, dude().y, 44, 10));\n    await Game.battle(s, makeMon(\"nibblet\", 5), { tutorial: { lines: [\"DUDE: First, weaken the BUDDYMON by battling it. A weak BUDDYMON is easier to catch.\", \"DUDE: Now! Throw a BUDDY NET at it!\"] } });\n    s.turn(DUDE, 1);\n    await s.say(\"That's how you do it. If you weaken them first, BUDDYMON are easier to catch.\");\n    s.flag(\"LEARNED_TO_CATCH\", true);\n  };\n\n  Game.register(\"route29\", {\n    world: {\n      label: \"Route 29\", cols, rows, cells: cells.map((r) => r.join(\"\")),\n      buildings: [{ x: 24, y: 2, w: 5, h: 3, door: 2, to: \"gate29\", tx: 4, ty: 6, dir: 1, roof: \"#8a6ad9\" }],\n    },\n    wild: { rate: 10, morn: MORN, day: MORN, nite: NITE }, // Gold's Route 29 table: day is the same as morning\n    warps: [9, 10].map((y) => ({ x: 55, y, to: \"newbark\", tx: 1, ty: y, dir: 3 })).concat([9, 10].map((y) => ({ x: 0, y, to: \"cherrygrove\", tx: 34, ty: y, dir: 2 }))),\n    coords: [9, 10].map((y) => ({ x: 53, y, script: lesson })),\n    npcs: [\n      { id: 1, name: \"COOLTRAINER_M\", x: 50, y: 11, dir: 0, wander: \"spin\", script: async (s) => { if (s.flag(\"GAVE_EGG\") && !s.flag(\"LEARNED_TO_CATCH\")) return lesson(s); await s.say(\"BUDDYMON hide in the grass. Who knows when they'll pop out...\"); } },\n      { id: 2, name: \"YOUNGSTER\", x: 43, y: 10, dir: 0, wander: \"vertical\", script: talk(\"Yo. How are your BUDDYMON? If they're weak and not ready for battle, keep out of the grass.\") },\n      { id: 3, name: \"TEACHER\", x: 38, y: 5, dir: 3, wander: \"horizontal\", script: talk(\"See those ledges? It's scary to jump off them. But you can get back to NEW BARK without walking through the grass.\") },\n      { id: 4, name: \"FRUIT_TREE\", x: 12, y: 3, dir: 0, faces: false, script: Game.berryTree(\"TREE_R29\") },\n      { id: 5, name: \"FISHER\", x: 29, y: 5, dir: 1, script: talk(\"I wanted to take a break, so I saved my game to record my progress.\") },\n      {\n        id: 6, name: \"COOLTRAINER_M\", x: 20, y: 5, dir: 0,\n        script: async (s) => { await s.say(`I'm waiting for BUDDYMON that appear only at ${timeOfDay() === \"nite\" ? \"dawn\" : \"night\"}.`); },\n      },\n      {\n        id: 7, name: \"SACK\", x: 44, y: 3, dir: 0, faces: false, hideIf: \"GOT_R29_TONIC\",\n        script: async (s) => { s.hide(7); s.flag(\"GOT_R29_TONIC\", true); s.give(\"tonic\"); await s.say(`${s.name} found a TONIC!`); },\n      },\n    ],\n    signs: [\n      { x: 52, y: 8, script: talk(\"ROUTE 29. CHERRYGROVE CITY - NEW BARK TOWN\") },\n      { x: 3, y: 8, script: talk(\"ROUTE 29. CHERRYGROVE CITY - NEW BARK TOWN\") },\n    ],\n  });\n\n  // The gate house on the road: leads north to Route 46 (not open yet).\n  const walls = new Set(); for (let x = 0; x < 10; x++) if (x !== 4 && x !== 5) walls.add(`${x},0`); walls.add(\"0,6\"); walls.add(\"9,6\");\n  Game.register(\"gate29\", {\n    room: { art: \"gate\", cols: 10, rows: 8, label: \"Route 29 · Gate\" },\n    solid: Array.from({ length: 8 }, (_, y) => Array.from({ length: 10 }, (_, x) => (walls.has(`${x},${y}`) ? \"#\" : \".\")).join(\"\")),\n    warps: [4, 5].map((x) => ({ x, y: 7, to: \"route29\", tx: 26, ty: 5, dir: 0 })),\n    coords: [4, 5].map((x) => ({ x, y: 0, script: async (s) => { await s.say(\"ROUTE 46 is closed for now.\"); await s.move(\"player\", [0]); } })),\n    npcs: [\n      { id: 1, name: \"OFFICER\", x: 0, y: 4, dir: 3, script: talk(\"This gate leads north to ROUTE 46. Anyone heading that way should have a BUDDYMON ready!\") },\n      { id: 2, name: \"YOUNGSTER\", x: 6, y: 4, dir: 0, wander: \"vertical\", script: talk(\"I'm waiting for my friend. He's late again!\") },\n    ],\n  });\n})();\n\n/* game/route30.js */\n// Route 30: the road north from Cherrygrove to Mr. Buddymon's house. Three trainers watch the road, grass with Gold's wild table,\n// Gold: Route30.asm (read before editing: object positions, connections, terrain; note what we change on purpose)\n// berry trees and a hidden tonic. 32 x 40 cells, original layout.\n(() => {\n  const cols = 32, rows = 40;\n  const cells = Array.from({ length: rows }, () => Array(cols).fill(\".\"));\n  const put = (kind, ...pts) => pts.forEach(([x, y]) => (cells[y][x] = kind));\n  const fill = (kind, x0, y0, x1, y1) => { for (let y = y0; y <= y1; y++) for (let x = x0; x <= x1; x++) cells[y][x] = kind; };\n  fill(\"T\", 0, 0, 31, 1); fill(\"T\", 0, 0, 7, 39); fill(\"T\", 26, 0, 31, 39); fill(\"T\", 0, 39, 31, 39);\n  fill(\"p\", 15, 35, 16, 39); // south: Cherrygrove\n  fill(\"g\", 8, 24, 13, 30); fill(\"g\", 20, 14, 25, 20); fill(\"g\", 8, 6, 12, 10); fill(\"g\", 20, 34, 25, 37);\n  fill(\"T\", 8, 16, 11, 19); fill(\"T\", 21, 25, 25, 28); fill(\"T\", 8, 33, 11, 36);\n  put(\"f\", [14, 9], [18, 22], [13, 32], [24, 30], [10, 12], [24, 11]);\n  put(\"S\", [14, 22], [13, 6], [14, 36], [20, 34]);\n  put(\"T\", [22, 4], [23, 4], [9, 3], [10, 3]);\n\n  const talk = Game.talk;\n  const mon = (species, level) => [species, level];\n  const trainer = (cls, name, party, seen, beaten, after, flag, sight = 4) => ({ name, cls, party, seen, beaten, after, flag, sight });\n  const MORN = [[2, \"chirplet\"], [3, \"grublet\"], [4, \"grublet\"], [4, \"cocoonet\"], [4, \"chirplet\"], [4, \"chirplet\"], [4, \"chirplet\"]];\n  const DAY = [[2, \"chirplet\"], [3, \"grublet\"], [4, \"chirplet\"], [4, \"cocoonet\"], [4, \"grublet\"], [5, \"cocoonet\"], [5, \"cocoonet\"]];\n  const NITE = [[3, \"spinlet\"], [3, \"nibblet\"], [4, \"hootling\"], [4, \"nibblet\"], [4, \"hootling\"], [4, \"hootling\"], [4, \"hootling\"]];\n\n  Game.register(\"route30\", {\n    world: {\n      label: \"Route 30\", cols, rows, cells: cells.map((r) => r.join(\"\")),\n      buildings: [{ x: 14, y: 3, w: 5, h: 4, door: 2, to: \"mrbuddy\", tx: 2, ty: 6, dir: 1, roof: \"#e0a03a\" }],\n    },\n    wild: { rate: 10, morn: MORN, day: DAY, nite: NITE },\n    warps: [15, 16].map((x) => ({ x, y: 39, to: \"cherrygrove\", tx: x, ty: 1, dir: 0 })),\n    npcs: [\n      { id: 1, name: \"YOUNGSTER\", x: 19, y: 30, dir: 2, trainer: trainer(\"YOUNGSTER\", \"JOEY\", [mon(\"nibblet\", 4)], \"I just lost, so I'm trying to find more BUDDYMON. Wait! You look weak! Come on, let's battle!\", \"Ugh. I don't have any more BUDDYMON.\", \"I have to have more BUDDYMON for battles. I'm going to catch some more!\", \"BEAT_JOEY\") },\n      { id: 2, name: \"YOUNGSTER\", x: 12, y: 21, dir: 3, trainer: trainer(\"YOUNGSTER\", \"MIKEY\", [mon(\"chirplet\", 2), mon(\"nibblet\", 4)], \"You're a BUDDYMON trainer, right? Then you have to battle!\", \"That's strange. I won before.\", \"Becoming a good trainer is really tough. I'm going to battle other people to get better.\", \"BEAT_MIKEY\", 6) },\n      { id: 3, name: \"BUG_CATCHER\", x: 19, y: 12, dir: 2, trainer: trainer(\"BUG CATCHER\", \"DON\", [mon(\"grublet\", 3), mon(\"grublet\", 3)], \"Instead of a bug BUDDYMON, I found a trainer!\", \"Argh! You're too strong!\", \"I ran out of BUDDY NETS while I was catching BUDDYMON. I should've bought some more...\", \"BEAT_DON\", 5) },\n      { id: 4, name: \"YOUNGSTER\", x: 16, y: 34, dir: 0, wander: \"horizontal\", script: talk((s) => (s.flag(\"GAVE_EGG\") ? \"Everyone's having fun battling! You should too!\" : \"MR. BUDDYMON's house? It's a bit farther ahead.\")) },\n      { id: 5, name: \"COOLTRAINER_F\", x: 21, y: 8, dir: 0, script: talk(\"I'm not a trainer. But if you look one in the eyes, prepare to battle.\") },\n      { id: 6, name: \"FRUIT_TREE\", x: 10, y: 9, dir: 0, faces: false, script: Game.berryTree(\"TREE_R30_A\") },\n      { id: 7, name: \"FRUIT_TREE\", x: 21, y: 31, dir: 0, faces: false, script: Game.berryTree(\"TREE_R30_B\") },\n    ],\n    signs: [\n      { x: 14, y: 36, script: talk(\"ROUTE 30. VIOLET CITY - CHERRYGROVE CITY\") },\n      { x: 14, y: 22, script: talk(\"MR. BUDDYMON'S HOUSE straight ahead!\") },\n      { x: 13, y: 6, script: talk(\"MR. BUDDYMON'S HOUSE\") },\n      { x: 20, y: 34, script: talk(\"TRAINER TIPS: No stealing other people's BUDDYMON! BUDDY NETS are to be thrown only at wild BUDDYMON!\") },\n      { x: 24, y: 5, script: Game.hiddenItem(\"R30_TONIC\", \"tonic\") },\n    ],\n  });\n})();\n\n/* game/willowhouse.js */\n// Willow's house (cells match art/willowHouse.js): PC (0,1), TV (4,1), shelves (6..7,1), table (3..4,3..4). His wife paces; his son dreams of the lab.\n// Gold: ElmsHouse.asm (read before editing: object positions, connections, terrain; note what we change on purpose)\n(() => {\n  const rect = (x0, y0, x1, y1) => { const o = []; for (let y = y0; y <= y1; y++) for (let x = x0; x <= x1; x++) o.push(`${x},${y}`); return o; };\n  const blocked = new Set([...rect(0, 0, 7, 0), ...rect(0, 1, 0, 1), ...rect(4, 1, 5, 1), ...rect(6, 1, 7, 1), ...rect(3, 3, 4, 4)]);\n  const talk = Game.talk;\n  Game.register(\"willowhouse\", {\n    room: { art: \"willowHouse\", cols: 8, rows: 8, label: \"New Bark Town · Willow's House\" },\n    solid: Array.from({ length: 8 }, (_, y) => Array.from({ length: 8 }, (_, x) => (blocked.has(`${x},${y}`) ? \"#\" : \".\")).join(\"\")),\n    warps: [2, 3].map((x) => ({ x, y: 7, to: \"newbark\", tx: 16, ty: 16, dir: 0 })),\n    npcs: [\n      { id: 1, name: \"TEACHER\", x: 1, y: 5, dir: 0, wander: \"vertical\", script: talk((s) => `Hi, ${s.name}! My husband's always so busy. I hope he's OK.`, \"When he's caught up in his BUDDYMON research, he even forgets to eat.\") },\n      { id: 2, name: \"BUG_CATCHER\", x: 5, y: 4, dir: 1, script: talk(\"When I grow up, I'm going to help my Dad! I'm going to be a great BUDDYMON professor!\") },\n    ],\n    signs: [\n      { x: 0, y: 1, script: talk(\"BUDDYMON. Where do they come from? Where are they going?\", \"Why has no one ever witnessed a BUDDYMON's birth? I will dedicate my life to finding out!\", \"...It's part of PROF. WILLOW's research papers.\") },\n      { x: 6, y: 1, script: talk(\"Shelves of thick BUDDYMON books. They look difficult.\") },\n      { x: 7, y: 1, script: talk(\"Shelves of thick BUDDYMON books. They look difficult.\") },\n    ],\n  });\n})();\n\n/* game/willowlab.js */\n// Willow's lab, scripted like Gold's: you walk up to the professor on your own, can't leave until you have a buddymon, pick one\n// Gold: ElmsLab.asm (read before editing: object positions, connections, terrain; note what we change on purpose)\n// (big picture first), he explains the machine and Mr. Buddymon, and his aide hands you a tonic as you head for the door.\n// Cells match art/willowLab.js. 10 x 12.\n(() => {\n  const rect = (x0, y0, x1, y1) => { const o = []; for (let y = y0; y <= y1; y++) for (let x = x0; x <= x1; x++) o.push(`${x},${y}`); return o; };\n  const blocked = new Set([...rect(0, 0, 9, 0), ...rect(0, 1, 3, 1), ...rect(0, 2, 1, 2), ...rect(6, 1, 9, 1), ...rect(6, 3, 9, 3), ...rect(0, 6, 3, 7), ...rect(6, 6, 9, 7)]);\n  const solid = Array.from({ length: 12 }, (_, y) => Array.from({ length: 10 }, (_, x) => (blocked.has(`${x},${y}`) ? \"#\" : \".\")).join(\"\"));\n  const WILLOW = 1, AIDE = 2;\n  const talk = Game.talk;\n  const tip = (n, text) => talk((s) => `${s.name} opened a book.`, `Travel Tip ${n}: ${text}`);\n\n  const STARTERS = [\n    { id: 11, species: \"bandit\", x: 6, kind: \"dark\" },\n    { id: 12, species: \"chomplet\", x: 7, kind: \"water\" },\n    { id: 13, species: \"bramblet\", x: 8, kind: \"grass\" },\n  ];\n  const choose = (st) => async (s) => {\n    if (s.flag(\"GOT_STARTER\")) return s.say(\"It holds a BUDDYMON that PROF. WILLOW caught.\");\n    const name = st.species.toUpperCase();\n    s.turn(WILLOW, 0);\n    s.pic(st.species);\n    await s.say(`WILLOW: You'll take ${name}, the ${st.kind} BUDDYMON?`);\n    const yes = (await s.ask()) === 0;\n    s.unpic();\n    if (!yes) return s.say(\"WILLOW: Think it over carefully. Your partner is important.\");\n    s.hide(st.id);\n    s.flag(`TOOK_${st.species}`, true);\n    await s.say(\"WILLOW: I think that's a great BUDDYMON too!\");\n    s.addBuddy(st.species, 5);\n    await s.say(`${s.name} received ${name}!`);\n    s.flag(\"GOT_STARTER\", true);\n    await s.move(\"player\", [...Array(Math.max(0, s.G.state.x - 5)).fill(2), 1]); // step over to the professor, as Gold does\n    s.turn(\"player\", 1);\n    await s.say(\"WILLOW: MR. BUDDYMON lives a little past CHERRYGROVE, the next town. It's almost a straight road from here.\");\n    s.turn(WILLOW, 2);\n    await s.say(\"WILLOW: If your BUDDYMON gets hurt, heal it with this machine. Feel free to use it any time.\");\n    s.turn(WILLOW, 0);\n    await s.say(\"WILLOW: Oh, here's my phone number. Call me if something comes up.\");\n    await s.say(`${s.name} got WILLOW's phone number.`);\n    s.flag(\"GOT_WILLOW_NUMBER\", true);\n  };\n\n  // The aide walks over to hand you something as you head for the door: a tonic after your first buddymon, five nets after the egg errand.\n  const aide = async (s) => {\n    const first = s.flag(\"GOT_STARTER\") && !s.flag(\"GOT_TONIC\"), second = s.flag(\"GAVE_EGG\") && !s.flag(\"GOT_NETS\");\n    if (!first && !second) return;\n    const x = s.G.state.x; // the aide stands at (2,9) and walks right until he is just below the player\n    await s.move(AIDE, Array(x - 2).fill(3));\n    s.turn(AIDE, 1);\n    s.turn(\"player\", 0);\n    if (first) {\n      await s.say(`${s.name}, I want you to have this for your errand.`);\n      s.give(\"tonic\");\n      s.flag(\"GOT_TONIC\", true);\n      await s.say(`${s.name} got a TONIC!`);\n      await s.say(\"There are only two of us, so we're always busy.\");\n    } else {\n      await s.say(`${s.name}! Use these on your BUDDYDEX quest!`);\n      s.give(\"buddy_net\", 5);\n      s.flag(\"GOT_NETS\", true);\n      await s.say(`${s.name} received 5 BUDDY NETS!`);\n      await s.say(\"To add to your BUDDYDEX, you have to catch BUDDYMON. Throw BUDDY NETS at wild BUDDYMON to get them.\");\n    }\n    await s.move(AIDE, Array(x - 2).fill(2));\n    s.turn(AIDE, 0);\n  };\n\n  // The officer is here about the theft; he asks for your rival's name (typed on your phone's keyboard) and leaves.\n  const officer = async (s) => {\n    if (!s.flag(\"COP_IN_LAB\") || s.flag(\"COP_GONE\")) return;\n    const COP = 3, x = s.G.state.x;\n    await s.move(\"player\", x === 4 ? [1, 1] : [2, 1, 1]);\n    s.turn(\"player\", 3);\n    s.turn(COP, 2);\n    await s.say(\"I heard a BUDDYMON was stolen here... I was just getting some information from PROF. WILLOW. Apparently, it was a young male with long, red hair...\");\n    await s.say(\"What? You battled a trainer like that? Did you happen to get his name?\");\n    s.G.player.rival = await s.prompt(\"What was his name?\", 7);\n    await s.say(`OK! So ${s.G.player.rival} was his name. Thanks for helping my investigation!`);\n    await s.move(COP, [0, 0, 0, 0, 0]);\n    s.hide(COP);\n    s.flag(\"COP_GONE\", true);\n  };\n\n  // Willow with the egg: he takes it, is amazed by the BUDDYDEX, and sends you off to see your mom.\n  const afterTheft = async (s) => {\n    await s.say(`WILLOW: ${s.name}, this is terrible... Oh, yes, what was MR. BUDDYMON's big discovery?`);\n    if (!s.G.player.bag.mystery_egg) return;\n    s.G.player.bag.mystery_egg--;\n    await s.say(`${s.name} handed the MYSTERY EGG to PROF. WILLOW.`);\n    await s.say(\"WILLOW: This? But... Is it a BUDDYMON EGG? If it is, it is a great discovery!\");\n    await s.say(`WILLOW: What?! PROF. ASPEN gave you a BUDDYDEX? ${s.name}, is that true? Th-that's incredible! He is superb at seeing the potential of people as trainers.`);\n    await s.say(`WILLOW: Wow, ${s.name}. You may have what it takes to become the CHAMPION. You seem to be getting on great with BUDDYMON too. You should take the BUDDYMON GYM challenge. The closest GYM would be the one in VIOLET CITY.`);\n    s.flag(\"GAVE_EGG\", true);\n    await s.say(`WILLOW: ...${s.name}. The road to the championship will be a long one. Before you leave, make sure that you talk to your mom.`);\n  };\n\n  Game.register(\"willowlab\", {\n    room: { art: \"willowLab\", cols: 10, rows: 12, label: \"New Bark Town · Willow's Lab\" },\n    solid,\n    warps: [4, 5].map((x) => ({ x, y: 11, to: \"newbark\", tx: 16, ty: 7, dir: 0 })),\n    npcs: [\n      {\n        id: WILLOW, name: \"WILLOW\", x: 5, y: 2, dir: 0,\n        script: async (s) => {\n          if (!s.flag(\"GOT_STARTER\")) return s.say(\"WILLOW: If a wild BUDDYMON appears, let your BUDDYMON battle it!\");\n          if (s.flag(\"GAVE_EGG\")) return s.say(\"WILLOW: Don't give up! I'll call if I learn anything about that EGG!\");\n          if (s.flag(\"GOT_EGG\")) return afterTheft(s);\n          await s.say(\"WILLOW: MR. BUDDYMON goes everywhere and finds rarities. Too bad they're usually rare and not very useful... \" + s.name + \", I'm counting on you!\");\n        },\n      },\n      {\n        id: AIDE, name: \"SCIENTIST\", x: 2, y: 9, dir: 0, wander: \"spin\", \n        script: talk(\"There are only two of us, so we're always busy.\"),\n      },\n      { id: 3, name: \"OFFICER\", x: 5, y: 3, dir: 1, showIf: \"COP_IN_LAB\", hideIf: \"COP_GONE\", script: talk(\"I'm investigating the break-in. Please don't touch anything.\") },\n      ...STARTERS.map((st) => ({ id: st.id, name: \"BUDDY_NET\", x: st.x, y: 3, dir: 0, faces: false, hideIf: `TOOK_${st.species}`, script: choose(st) })),\n    ],\n    signs: [\n      {\n        x: 2, y: 1,\n        script: async (s) => {\n          if (!s.flag(\"GOT_STARTER\")) return s.say(\"I wonder what this does?\");\n          await s.say(\"Heal your BUDDYMON?\");\n          if ((await s.ask()) === 0) await s.say(\"Your BUDDYMON were restored to full health!\");\n        },\n      },\n      { x: 5, y: 0, script: talk(\"The window's open. A pleasant breeze is blowing in.\") },\n      ...[6, 7, 8, 9].flatMap((x) => [1, 7].map((y) => ({ x, y, script: talk(\"Shelves of thick BUDDYMON books. They look difficult.\") }))),\n      { x: 9, y: 3, script: talk(\"The wrapper from the snack PROF. WILLOW ate is in there...\") },\n      { x: 0, y: 7, script: tip(1, \"Press START to open the MENU.\") },\n      { x: 1, y: 7, script: tip(2, \"Record your trip with SAVE!\") },\n      { x: 2, y: 7, script: tip(3, \"Open your PACK to use items.\") },\n      { x: 3, y: 7, script: tip(4, \"Check your BUDDYMON's moves in the party screen.\") },\n    ],\n    coords: [\n      ...[4, 5].map((x) => ({\n        x, y: 6,\n        script: async (s) => {\n          if (s.flag(\"GOT_STARTER\")) return;\n          s.turn(WILLOW, 0);\n          await s.say(\"WILLOW: Wait! Where are you going?\");\n          await s.move(\"player\", [1]);\n        },\n      })),\n      ...[4, 5].map((x) => ({ x, y: 8, script: aide })),\n      ...[4, 5].map((x) => ({ x, y: 5, script: officer })),\n    ],\n    // Like Gold: the first time in, you walk straight up to the professor and he explains the favor.\n    enter: async (s) => {\n      if (s.flag(\"MET_WILLOW\")) return;\n      await s.move(\"player\", Array(9).fill(1));\n      s.turn(\"player\", 3);\n      s.turn(WILLOW, 2);\n      await s.say(`WILLOW: ${s.name}! There you are! I needed to ask you a favor.`);\n      await s.say(\"WILLOW: I have an acquaintance called MR. BUDDYMON. He keeps finding weird things and raving about his discoveries.\");\n      await s.say(\"WILLOW: Anyway, I just got a message from him saying that this time it's real. It's intriguing, but we're busy with our BUDDYMON research.\");\n      await s.say(\"WILLOW: Could you look into it for us? I'll give you a BUDDYMON for a partner. They're all rare BUDDYMON that we just found.\");\n      await s.say(\"WILLOW: Go on. Pick one!\");\n      s.flag(\"MET_WILLOW\", true);\n    },\n  });\n})();\n\n/* page/app.js */\n// Page shell: tiny helpers, the optional account dialog, and the Play button that starts the game (game/start.js).\nconst $ = (id) => document.getElementById(id);\nconst setStatus = (text) => ($(\"status\").textContent = text);\nconst api = (path, options = {}) => fetch(path, { credentials: \"same-origin\", ...options });\n\nasync function ensurePlayer() {\n  const res = await api(\"/api/me\");\n  if (!res.ok) throw new Error(\"Could not reach the save server\");\n  return res.json();\n}\n\n$(\"play\").addEventListener(\"click\", async () => {\n  $(\"play\").disabled = true;\n  try {\n    await ensurePlayer();\n  } catch (err) {\n    setStatus(\"Playing offline (progress is saved on this device only)\");\n  }\n  $(\"start\").hidden = true;\n  $(\"pad\").hidden = false;\n  setStatus(\"Playing\");\n  Game.boot($(\"hd\"));\n});\n\n// Installable: register the service worker (offline play) and offer an Install button when the browser allows it.\nif (\"serviceWorker\" in navigator) navigator.serviceWorker.register(\"/sw.js\").catch(() => {});\nlet installEvent = null;\naddEventListener(\"beforeinstallprompt\", (e) => { e.preventDefault(); installEvent = e; $(\"install\").hidden = false; });\naddEventListener(\"appinstalled\", () => { $(\"install\").hidden = true; });\n$(\"install\").addEventListener(\"click\", async () => { if (!installEvent) return; installEvent.prompt(); await installEvent.userChoice; installEvent = null; $(\"install\").hidden = true; });\n\n// Optional account: a username + password that points at the same cloud player as the guest cookie.\nconst acct = { dlg: $(\"account\"), msg: $(\"acct-msg\") };\nasync function showAccount() {\n  const me = await (await api(\"/api/me\")).json();\n  $(\"account-form\").hidden = !!me.username;\n  $(\"account-in\").hidden = !me.username;\n  $(\"account-note\").textContent = me.username ? `Signed in as ${me.username}. Your game follows you to any device.` : \"Optional. Make one to keep your game on any device.\";\n  acct.msg.textContent = \"\";\n}\nasync function submitAccount(action) {\n  const res = await api(`/api/${action}`, { method: \"POST\", body: JSON.stringify({ username: $(\"acct-user\").value, password: $(\"acct-pass\").value }) });\n  const body = await res.json();\n  if (!res.ok) { acct.msg.textContent = body.error; return; }\n  $(\"acct-pass\").value = \"\";\n  await showAccount();\n  acct.msg.textContent = action === \"login\" ? \"Signed in. Reload to load your saved game.\" : \"Account created.\";\n}\n$(\"account-btn\").addEventListener(\"click\", async () => { await showAccount(); acct.dlg.showModal(); });\n$(\"acct-login\").addEventListener(\"click\", () => submitAccount(\"login\"));\n$(\"acct-register\").addEventListener(\"click\", () => submitAccount(\"register\"));\n$(\"acct-logout\").addEventListener(\"click\", async () => { await api(\"/api/logout\", { method: \"POST\" }); await showAccount(); acct.msg.textContent = \"Signed out. Reload to start as a guest.\"; });\n\n/* page/pad.js */\n// Touch input: on-screen pad and gesture mode. Needs $ and setStatus from app.js (loaded after this file).\n\n// On-screen pad: presses go into `held`, which game/input.js reads every frame. A press is held at least\n// MIN_HOLD_MS so a tap can't fall between frames.\nconst MIN_HOLD_MS = 110;\nconst held = {}, pressedAt = {}, releaseTimer = {};\n\nfunction setKey(key, down) {\n  if (down) {\n    clearTimeout(releaseTimer[key]);\n    if (held[key]) return;\n    held[key] = true;\n    pressedAt[key] = performance.now();\n  } else if (held[key]) {\n    const wait = Math.max(0, MIN_HOLD_MS - (performance.now() - pressedAt[key]));\n    releaseTimer[key] = setTimeout(() => { held[key] = false; }, wait);\n  }\n}\n\nfor (const btn of document.querySelectorAll(\"#pad [data-key]\")) {\n  const key = btn.dataset.key;\n  const up = () => { btn.classList.remove(\"down\"); setKey(key, false); };\n  btn.addEventListener(\"pointerdown\", (e) => { e.preventDefault(); btn.setPointerCapture(e.pointerId); btn.classList.add(\"down\"); setKey(key, true); });\n  btn.addEventListener(\"pointerup\", up);\n  btn.addEventListener(\"pointercancel\", up);\n}\n\n// One touch surface for the D-pad so a thumb can roll between directions.\nconst dpad = $(\"dpad\");\nlet dpadDir = null;\nfunction setDpad(dir) {\n  if (dir === dpadDir) return;\n  if (dpadDir) setKey(dpadDir, false);\n  dpad.className = dir || \"\";\n  dpadDir = dir;\n  if (dir) setKey(dir, true);\n}\nfunction dpadFromEvent(e) {\n  const r = dpad.getBoundingClientRect();\n  const dx = e.clientX - (r.left + r.width / 2), dy = e.clientY - (r.top + r.height / 2);\n  if (Math.hypot(dx, dy) < r.width * 0.12) return null;\n  return Math.abs(dx) > Math.abs(dy) ? (dx < 0 ? \"LEFT\" : \"RIGHT\") : (dy < 0 ? \"UP\" : \"DOWN\");\n}\ndpad.addEventListener(\"pointerdown\", (e) => { e.preventDefault(); dpad.setPointerCapture(e.pointerId); setDpad(dpadFromEvent(e)); });\ndpad.addEventListener(\"pointermove\", (e) => { if (dpad.hasPointerCapture(e.pointerId)) setDpad(dpadFromEvent(e)); });\ndpad.addEventListener(\"pointerup\", () => setDpad(null));\ndpad.addEventListener(\"pointercancel\", () => setDpad(null));\ndocument.addEventListener(\"contextmenu\", (e) => e.preventDefault());\n\n// Gesture mode: the whole game screen is the controller and the pad is hidden.\n//   drag / hold = walk that way (relative to where the finger went down), tap = A,\n//   two-finger tap = B, long-press = Start.\nconst GESTURE = { dead: 16, tapMs: 250, longMs: 600 };\nconst stage = $(\"stage\");\nconst fingers = new Map();\nlet gestureDir = null, twoFinger = false;\n\nfunction setGestureDir(dir) {\n  if (dir === gestureDir) return;\n  if (gestureDir) setKey(gestureDir, false);\n  gestureDir = dir;\n  if (dir) setKey(dir, true);\n}\nconst tapOnce = (key) => { setKey(key, true); setKey(key, false); };\n\nstage.addEventListener(\"pointerdown\", (e) => {\n  if (!document.body.classList.contains(\"gestures\") || !$(\"start\").hidden) return;\n  e.preventDefault();\n  stage.setPointerCapture(e.pointerId);\n  const f = { x: e.clientX, y: e.clientY, t: performance.now(), moved: false, long: false, used: false };\n  f.timer = setTimeout(() => { if (!f.moved && fingers.size === 1) { f.long = true; tapOnce(\"START\"); } }, GESTURE.longMs);\n  fingers.set(e.pointerId, f);\n  if (fingers.size === 2) { twoFinger = true; fingers.forEach((g) => clearTimeout(g.timer)); }\n});\n\nstage.addEventListener(\"pointermove\", (e) => {\n  const f = fingers.get(e.pointerId);\n  if (!f || twoFinger) return;\n  const dx = e.clientX - f.x, dy = e.clientY - f.y;\n  if (Math.hypot(dx, dy) < GESTURE.dead) return;\n  f.moved = true;\n  clearTimeout(f.timer);\n  setGestureDir(Math.abs(dx) > Math.abs(dy) ? (dx < 0 ? \"LEFT\" : \"RIGHT\") : (dy < 0 ? \"UP\" : \"DOWN\"));\n});\n\nfunction endFinger(e) {\n  const f = fingers.get(e.pointerId);\n  if (!f) return;\n  clearTimeout(f.timer);\n  fingers.delete(e.pointerId);\n  const quick = !f.moved && performance.now() - f.t < GESTURE.tapMs;\n  if (f.moved) setGestureDir(null);\n  else if (twoFinger) { if (quick && !f.used) { tapOnce(\"B\"); fingers.forEach((g) => (g.used = true)); } }\n  else if (quick && !f.long) tapOnce(\"A\");\n  if (!fingers.size) twoFinger = false;\n}\nstage.addEventListener(\"pointerup\", endFinger);\nstage.addEventListener(\"pointercancel\", endFinger);\n\n// Controls setting: \"pad\" (on-screen buttons) or \"gestures\"; remembered per device.\nconst controlsBtn = $(\"controls\");\nfunction applyControls(mode) {\n  document.body.classList.toggle(\"gestures\", mode === \"gestures\");\n  controlsBtn.textContent = mode === \"gestures\" ? \"Gesture\" : \"Pad\";\n  try { localStorage.setItem(\"controls\", mode); } catch {}\n}\nlet savedControls = \"pad\";\ntry { savedControls = localStorage.getItem(\"controls\") || \"pad\"; } catch {}\napplyControls(savedControls);\ncontrolsBtn.addEventListener(\"click\", () => {\n  const next = document.body.classList.contains(\"gestures\") ? \"pad\" : \"gestures\";\n  applyControls(next);\n  if (next === \"gestures\") setStatus(\"Drag = walk · tap = A · two fingers = B · hold = Start\");\n});\n","/style.css":"/* page/hd/ui/dialogue.css */\n/* dialogue */\n#hd .dlg { z-index:7; position:absolute; left:3.5%; right:3.5%; bottom:3.5%; min-height:15cqw; padding:3.8cqw 9cqw 3.2cqw 5cqw; border-radius:4cqw;\n  background:linear-gradient(rgba(18,32,82,.94),rgba(10,18,50,.96)); border:.7cqw solid var(--gold); box-shadow:0 0 0 .5cqw var(--ink), 0 1.6cqw 4cqw rgba(0,0,0,.5); }\n#hd .dlg[hidden] { display:none; }\n#hd .dlg p { margin:0; font-size:5.6cqw; line-height:1.28; font-weight:500; min-height:7.2cqw; text-shadow:0 .3cqw 0 rgba(0,0,0,.35); }\n#hd .dlg-tag { position:absolute; left:4cqw; top:-3.6cqw; padding:.5cqw 3cqw; font-size:3.4cqw; font-weight:700; color:var(--ink); background:linear-gradient(#ffe98a,#ffc93c); border:.5cqw solid var(--ink); border-radius:3cqw; }\n#hd .more { position:absolute; right:4cqw; bottom:2cqw; font-size:4cqw; color:var(--gold); animation:nudge .9s ease-in-out infinite; }\n@keyframes nudge { 50% { transform:translateY(.8cqw); } }\n\n\n/* text entry: the phone's own keyboard on a real input */\n#hd .ask { pointer-events:auto; position:absolute; left:8%; right:8%; top:30%; display:flex; flex-direction:column; gap:3cqw; padding:5cqw; border-radius:4cqw; z-index:5;\n  background:linear-gradient(#18224f,#0e1536); border:.7cqw solid var(--accent,#ffc93c); }\n#hd .ask label { font-size:5cqw; font-weight:600; }\n#hd .ask input { min-height:12cqw; padding:0 4cqw; font:inherit; font-size:6cqw; color:inherit; background:#0b1022; border:.4cqw solid #3a4680; border-radius:3cqw; }\n#hd .ask button { min-height:12cqw; font-size:5cqw; }\n\n/* page/hd/ui/panel.css */\n/* list screens (party, pack, trainer card, ...) */\n#hd .panel-ui { position:absolute; inset:3% 3% 3%; display:flex; flex-direction:column; gap:2cqw; padding:4cqw; border-radius:5cqw; z-index:6; pointer-events:auto;\n  background:linear-gradient(rgba(18,32,82,.97),rgba(8,14,40,.98)); border:.7cqw solid var(--gold); box-shadow:0 0 0 .5cqw var(--ink), 0 2cqw 6cqw rgba(0,0,0,.6); overflow:hidden; }\n#hd .panel-ui[hidden] { display:none; }\n#hd .panel-ui h2 { margin:0; font:400 6.4cqw 'Lilita One','Fredoka',sans-serif; letter-spacing:.2cqw; color:var(--gold); }\n#hd .pn-hero { width:42%; align-self:center; } #hd .pn-hero svg { width:100%; display:block; }\n#hd .pn-tabs { display:flex; gap:1.6cqw; } #hd .pn-tabs span { flex:1; text-align:center; padding:1.6cqw 0; font-size:4cqw; font-weight:600; border-radius:2.6cqw; background:rgba(255,246,220,.08); }\n#hd .pn-tabs span.sel { color:var(--ink); background:linear-gradient(#ffe98a,#ffc93c); }\n#hd .pn-line { margin:0; font-size:4.6cqw; line-height:1.3; }\n#hd .panel-ui ul { margin:0; padding:0; list-style:none; flex:1; min-height:0; overflow:auto; display:flex; flex-direction:column; gap:1.6cqw; }\n#hd .panel-ui li { display:flex; align-items:center; gap:3cqw; padding:2.2cqw 3cqw; border-radius:3.4cqw; background:rgba(255,246,220,.08); font-size:4.8cqw; min-height:12cqw; }\n#hd .panel-ui li.sel { color:var(--ink); background:linear-gradient(#ffe98a,#ffc93c); }\n#hd .panel-ui li.dim { opacity:.5; }\n#hd .pn-art { width:13cqw; flex:none; } #hd .pn-art svg { width:100%; display:block; }\n#hd .pn-main { flex:1; min-width:0; display:flex; flex-direction:column; gap:.8cqw; } #hd .pn-main b { font-weight:700; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }\n#hd .pn-main small { font-size:3.4cqw; opacity:.8; }\n#hd .pn-bar { display:block; height:2.2cqw; border-radius:2cqw; background:rgba(0,0,0,.3); overflow:hidden; }\n#hd .pn-bar i { display:block; height:100%; border-radius:2cqw; background:#46c26f; } #hd .pn-bar i[data-level=warn] { background:#ffc93c; } #hd .pn-bar i[data-level=low] { background:#ff6b5e; }\n#hd .panel-ui li em { font-style:normal; font-size:4cqw; white-space:nowrap; opacity:.9; }\n#hd .pn-hint { margin:0; font-size:3.6cqw; opacity:.8; }\n#hd .pn-back { align-self:flex-end; min-height:11cqw; padding:0 7cqw; font:inherit; font-weight:700; font-size:4.6cqw; color:var(--cream); border-radius:4cqw; background:rgba(255,246,220,.12); border:.5cqw solid rgba(255,246,220,.35); }\n\n#hd .gender { margin-left:1.4cqw; font-weight:700; } #hd .gender.m { color:#4aa3e8; } #hd .gender.f { color:#ff7aa8; }\n#hd .panel-ui li.sel .gender { color:var(--ink); }\n\n/* page/hd/ui/pic.css */\n/* big buddymon picture: kept to the left so it never sits under the right-hand Yes/No box */\n#hd .pic { position:absolute; left:4%; top:3%; width:36%; padding:3cqw; border-radius:5cqw; z-index:4;\n  background:linear-gradient(#26356f,#121a40); border:.7cqw solid var(--gold); text-align:center; animation:pic-in .25s ease-out; }\n#hd .pic[hidden] { display:none; }\n#hd .pic-art svg { width:100%; display:block; }\n#hd .pic-name { margin-top:1cqw; font-family:'Lilita One','Fredoka',sans-serif; font-size:5cqw; letter-spacing:.3cqw; color:var(--gold); }\n@keyframes pic-in { from { transform:scale(.85); opacity:0; } to { transform:scale(1); opacity:1; } }\n\n/* page/hd/ui/popup.css */\n/* popup menus */\n#hd .popups { position:absolute; inset:0; pointer-events:none; z-index:8; }\n#hd .popup { pointer-events:auto; }\n#hd .popup { position:absolute; margin:0; padding:2.4cqw; list-style:none; min-width:34cqw; border-radius:4cqw;\n  background:linear-gradient(rgba(18,32,82,.95),rgba(10,18,50,.96)); border:.6cqw solid var(--gold); box-shadow:0 0 0 .5cqw var(--ink), 0 1.6cqw 4cqw rgba(0,0,0,.5); }\n#hd .popup.top { top:4%; } #hd .popup.low { bottom:calc(var(--dlg-h, 0px) + 3.5% + 3cqw); } #hd .popup.right { right:4%; } #hd .popup.left { left:4%; }\n#hd .popup li { padding:1.8cqw 3.4cqw; margin-bottom:.8cqw; font-size:5cqw; font-weight:600; border-radius:2.6cqw; white-space:nowrap; }\n#hd .popup li.sel { color:var(--ink); background:linear-gradient(#ffe98a,#ffc93c); font-weight:700; }\n\n/* page/hd/ui/portrait.css */\n/* portrait (shared by prof, names, naming) */\n#hd .portrait { position:absolute; left:4%; bottom:30%; width:54%; filter:drop-shadow(0 1.6cqw 0 rgba(0,0,0,.25)); }\n#hd .portrait svg { width:100%; display:block; }\n\n/* page/hd/scenes/battle.css */\n/* battle */\n#hd .battle { background:#8fd3ff; }\n#hd .bt-bg { position:absolute; inset:0; background:\n  radial-gradient(130% 42% at 50% 100%, #46b05a 0 60%, transparent 61%) 0 52%/100% 60% no-repeat,\n  linear-gradient(#6fc4ff 0%, #d9f2ff 46%, #9be37a 46.2%, #5cc255 100%); }\n#hd .bt-side { position:absolute; }\n#hd .bt-side.foe { right:4cqw; top:13%; width:44cqw; }\n#hd .bt-side.me { left:3cqw; top:36%; width:46cqw; }\n#hd .bt-side .plat { position:absolute; left:-6%; right:-6%; bottom:-4%; height:28%; border-radius:50%; background:radial-gradient(#8de27a, #4fae57); border:.6cqw solid var(--ink); }\n#hd .bt-side .mon { position:relative; }\n#hd .bt-side .mon svg { width:100%; display:block; }\n#hd .bt-side.me .mon svg { transform:scaleX(-1); }\n#hd .mon.enter { animation:bt-enter .6s cubic-bezier(.3,1.5,.5,1) both; }\n@keyframes bt-enter { from { transform:translateY(-14cqw) scale(.6); opacity:0; } to { transform:none; opacity:1; } }\n#hd .mon.hit { animation:bt-hit .4s ease-in-out; }\n@keyframes bt-hit { 0%,100% { transform:none; filter:none; } 25% { transform:translateX(-3cqw); filter:brightness(2); } 60% { transform:translateX(2cqw); } }\n#hd .mon.faint { transition:transform .6s, opacity .6s; transform:translateY(12cqw); opacity:0; }\n#hd .mon.netted { opacity:.25; transform:scale(.7); transition:opacity .3s, transform .3s; }\n#hd .bt-net { position:absolute; left:20%; top:20%; width:60%; }\n#hd .bt-net[hidden] { display:none; }\n#hd .bt-net svg { width:100%; display:block; }\n#hd .bt-net.go { animation:net-drop .45s ease-in both, net-shake .5s .45s ease-in-out var(--shakes) both; }\n@keyframes net-drop { from { transform:translateY(-30cqw) scale(1.4); opacity:0; } to { transform:none; opacity:1; } }\n@keyframes net-shake { 0%,100% { transform:rotate(0); } 25% { transform:rotate(-12deg); } 75% { transform:rotate(12deg); } }\n#hd .bt-card { position:absolute; padding:2cqw 3cqw; border-radius:3.6cqw; background:rgba(10,18,50,.88); border:.5cqw solid rgba(255,246,220,.35); }\n#hd .bt-card.foe { left:4cqw; top:4%; width:46cqw; }\n#hd .bt-card.me { right:4cqw; top:46%; width:42cqw; }\n#hd .bt-card .nm { display:block; font-size:4.6cqw; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }\n#hd .bt-card .lv { position:absolute; right:3cqw; top:2.4cqw; font-size:3.4cqw; opacity:.85; }\n#hd .bt-card .hp { height:2.6cqw; margin-top:1.4cqw; border-radius:2cqw; background:rgba(255,246,220,.18); overflow:hidden; }\n#hd .bt-card .hp i { display:block; height:100%; border-radius:2cqw; background:#46c26f; transition:width .5s linear, background .3s; }\n#hd .bt-card .hp i[data-level=warn] { background:#ffc93c; } #hd .bt-card .hp i[data-level=low] { background:#ff6b5e; }\n#hd .bt-card .num { display:block; margin-top:1cqw; text-align:right; font-size:3.2cqw; opacity:.9; }\n/* command, move, pack and party menus: big touch buttons above the message box */\n#hd .bt-menu { position:absolute; left:4%; right:4%; bottom:calc(var(--dlg-h, 0px) + 3.5% + 3cqw); display:grid; gap:2cqw; pointer-events:auto; z-index:3; }\n#hd .bt-menu[hidden] { display:none; }\n#hd .bt-menu.cols2 { grid-template-columns:1fr 1fr; }\n#hd .bt-menu button { font:inherit; font-weight:700; font-size:4.6cqw; padding:3cqw 2cqw; min-height:12cqw; border-radius:3.6cqw; color:var(--cream); text-align:center;\n  background:rgba(10,18,50,.94); border:.5cqw solid rgba(255,246,220,.35); text-transform:none; }\n#hd .bt-menu button.sel { color:var(--ink); background:linear-gradient(#ffe98a,#ffc93c); border-color:var(--ink); box-shadow:0 .8cqw 0 var(--gold2); }\n#hd .bt-menu.cmd { left:36%; }\n#hd .bt-card .nm { display:inline-block; max-width:70%; vertical-align:bottom; } #hd .bt-card .gd { font-style:normal; font-weight:700; margin-left:1.4cqw; font-size:4.6cqw; }\n\n/* move animations and the EXP bar */\n#hd .bt-card .xp { height:1.6cqw; margin-top:1.6cqw; border-radius:1cqw; background:rgba(255,246,220,.18); overflow:hidden; }\n#hd .bt-card .xp i { display:block; height:100%; width:0; background:#4fb6ff; transition:width 1.1s ease-out; }\n#hd .bt-side .fx { position:absolute; left:25%; top:15%; width:50%; pointer-events:none; opacity:0; }\n#hd .bt-side .fx svg { width:100%; display:block; }\n#hd .bt-side .fx.go { animation:fx-pop .6s ease-out both; }\n@keyframes fx-pop { 0% { opacity:0; transform:scale(.3) rotate(-20deg); } 30% { opacity:1; transform:scale(1.15) rotate(6deg); } 100% { opacity:0; transform:scale(1.4) rotate(12deg); } }\n#hd .bt-side .fx svg.up { animation:fx-up .6s ease-out both; } #hd .bt-side .fx svg.down { animation:fx-down .6s ease-out both; }\n@keyframes fx-up { from { transform:translateY(8cqw); } to { transform:translateY(-8cqw); } } @keyframes fx-down { from { transform:translateY(-8cqw); } to { transform:translateY(8cqw); } }\n#hd .mon.lunge-me { animation:lunge-me .45s ease-in-out; } #hd .mon.lunge-foe { animation:lunge-foe .45s ease-in-out; }\n@keyframes lunge-me { 0%,100% { transform:none; } 40% { transform:translate(16cqw,-9cqw); } }\n@keyframes lunge-foe { 0%,100% { transform:none; } 40% { transform:translate(-16cqw,9cqw); } }\n\n/* page/hd/scenes/intro.css */\n/* opening cinematic: act i starts at i*6s (--t) */\n#hd .intro { background:#050a22; }\n#hd .act { --t:calc(var(--i) * 6s); position:absolute; inset:0; overflow:hidden; opacity:0; animation:ia-fade 6.4s linear var(--t) both; }\n#hd .act:last-of-type { animation-name:ia-last; }\n@keyframes ia-fade { 0% { opacity:0; } 6% { opacity:1; } 93% { opacity:1; } 100% { opacity:0; } }\n@keyframes ia-last { 0% { opacity:0; } 6% { opacity:1; } 100% { opacity:1; } }\n#hd .act .bgsvg, #hd .nightbg, #hd .nightbg .sky, #hd .burst { position:absolute; inset:0; width:100%; height:100%; }\n#hd .cap { position:absolute; left:6%; right:6%; bottom:9%; margin:0; padding:2.4cqw 4cqw; text-align:center; font:600 6cqw/1.2 'Fredoka',sans-serif; color:var(--cream);\n  border-radius:5cqw; background:rgba(10,18,50,.72); border:.5cqw solid rgba(255,246,220,.3); opacity:0; animation:ia-cap .7s calc(var(--t) + .6s) ease-out both; }\n#hd .cap.big { font-size:7.4cqw; color:var(--gold); border-color:var(--gold); }\n@keyframes ia-cap { from { opacity:0; transform:translateY(4cqw); } to { opacity:1; transform:none; } }\n#hd .skip { position:absolute; left:0; right:0; top:2.5%; text-align:center; font-size:3cqw; opacity:.55; letter-spacing:.3cqw; }\n\n/* act 1: sea */\n#hd .swim { position:absolute; left:0; width:30cqw; animation:ia-swim 6s linear var(--t) both; }\n#hd .swim svg { display:block; width:100%; animation:ia-bob 1.1s ease-in-out infinite alternate; }\n#hd .s1 { top:20%; animation-duration:6s; } #hd .s2 { top:42%; width:36cqw; animation-delay:calc(var(--t) + .6s); animation-duration:5.6s; }\n#hd .s3 { top:62%; width:26cqw; animation-delay:calc(var(--t) + 1.2s); animation-duration:5.2s; }\n@keyframes ia-swim { from { transform:translateX(-40cqw); } to { transform:translateX(125cqw); } }\n@keyframes ia-bob { from { transform:translateY(-2cqw) rotate(-4deg); } to { transform:translateY(2cqw) rotate(4deg); } }\n#hd .kelp { transform-box:fill-box; transform-origin:50% 100%; animation:ia-sway 3s ease-in-out infinite alternate; }\n@keyframes ia-sway { from { transform:rotate(-4deg); } to { transform:rotate(4deg); } }\n#hd .bub { position:absolute; bottom:-4cqw; left:var(--x); width:var(--s); height:var(--s); border-radius:50%; border:.4cqw solid rgba(255,255,255,.8); animation:ia-rise 4.5s calc(var(--t) + var(--d)) ease-in infinite; }\n@keyframes ia-rise { to { transform:translateY(-130cqw); opacity:.2; } }\n\n/* act 2: meadow */\n#hd .roll { position:absolute; left:0; bottom:20%; width:36cqw; animation:ia-run 5.4s calc(var(--t) + .3s) ease-in-out both; }\n#hd .roll > div { animation:ia-roll 5.4s calc(var(--t) + .3s) ease-in-out both; } #hd .roll svg { display:block; width:100%; }\n@keyframes ia-run { from { transform:translateX(-45cqw); } to { transform:translateX(112cqw); } }\n@keyframes ia-roll { from { transform:rotate(0); } to { transform:rotate(900deg); } }\n\n/* act 3: night */\n#hd .pop { position:absolute; left:50%; bottom:20%; width:44cqw; margin-left:-22cqw; animation:ia-pop .9s calc(var(--t) + .4s) cubic-bezier(.3,1.7,.5,1) both; }\n#hd .pop svg { display:block; width:100%; animation:ia-bob 1.4s 1.4s ease-in-out infinite alternate; }\n@keyframes ia-pop { from { transform:scale(0) translateY(10cqw); } to { transform:none; } }\n#hd .ember { position:absolute; bottom:30%; left:var(--x); width:1.4cqw; height:1.4cqw; border-radius:50%; background:#ffb13a; box-shadow:0 0 2cqw .6cqw rgba(255,150,40,.8);\n  opacity:0; animation:ia-ember 2.6s calc(var(--t) + 1s + var(--d)) ease-out infinite; }\n@keyframes ia-ember { 0% { opacity:0; transform:translateY(0); } 15% { opacity:1; } 100% { opacity:0; transform:translate(4cqw,-45cqw) scale(.3); } }\n\n/* act 4: finale */\n#hd .burst { background:radial-gradient(circle at 50% 55%, #ffe98a 0%, #ffc93c 30%, #f08a14 60%, #7a3a9c 100%); }\n#hd .burst::before { content:\"\"; position:absolute; left:50%; top:55%; width:220cqw; height:220cqw; margin:-110cqw 0 0 -110cqw; opacity:.35;\n  background:repeating-conic-gradient(from 0deg, #fff 0 8deg, transparent 8deg 22deg); animation:ia-spin 14s linear infinite; }\n@keyframes ia-spin { to { transform:rotate(360deg); } }\n#hd .jump { position:absolute; bottom:26%; width:31cqw; animation:ia-jump .8s calc(var(--t) + var(--w)) cubic-bezier(.3,1.6,.5,1) both; }\n#hd .jump svg { display:block; width:100%; animation:ia-hop 1s calc(var(--t) + var(--w) + .8s) ease-in-out infinite; }\n#hd .j1 { left:5%; --w:.3s; } #hd .j2 { left:34.5%; --w:.6s; bottom:30%; } #hd .j3 { left:64%; --w:.9s; }\n@keyframes ia-jump { from { transform:translateY(80cqw); } to { transform:none; } }\n@keyframes ia-hop { 0%,100% { transform:translateY(0); } 40% { transform:translateY(-4cqw); } 55% { transform:scale(1.04,.96); } }\n\n/* page/hd/scenes/menu.css */\n/* menu */\n#hd .menu-list { position:absolute; left:6%; top:46%; margin:0; padding:0; list-style:none; width:64%; }\n#hd .menu-list li { position:relative; margin:0 0 3cqw; padding:2.4cqw 4cqw 2.4cqw 7cqw; font-size:5.2cqw; font-weight:600; border-radius:4cqw;\n  background:rgba(10,18,50,.72); border:.5cqw solid rgba(255,246,220,.25); backdrop-filter:blur(4px); transition:transform .12s; }\n#hd .menu-list li b { position:absolute; left:3cqw; top:50%; width:2.2cqw; height:2.2cqw; margin-top:-1.1cqw; border-radius:50%; background:transparent; }\n#hd .menu-list li.sel { transform:translateX(2cqw) scale(1.04); color:var(--ink); background:linear-gradient(#ffe98a,#ffc93c); border-color:var(--ink); box-shadow:0 1cqw 0 var(--gold2), 0 0 3cqw rgba(255,201,60,.55); }\n#hd .menu-list li.sel b { background:var(--ink); }\n#hd .chip { position:absolute; right:4%; top:4%; padding:1.4cqw 3cqw; font-size:3.4cqw; border-radius:4cqw; background:rgba(10,18,50,.7); border:.4cqw solid rgba(255,246,220,.25); white-space:pre; }\n\n\n/* page/hd/scenes/prof.css */\n/* professor intro */\n#hd .creature { position:absolute; right:5%; top:6%; width:38%; padding:2cqw; border-radius:6cqw; background:rgba(255,246,220,.14); border:.5cqw solid rgba(255,246,220,.35); animation:hop 2.8s ease-in-out infinite; }\n#hd .creature[hidden] { display:none; } #hd .creature svg { width:100%; display:block; }\n\n/* page/hd/scenes/room.css */\n/* room */\n#hd .room { background:radial-gradient(90% 80% at 50% 45%, #25407a 0%, #0c1636 100%); }\n#hd .room-wrap { position:absolute; left:50%; top:44%; width:98%; transform:translate(-50%,-50%); transition:top .27s linear; filter:drop-shadow(0 2cqw 3cqw rgba(0,0,0,.5)); }\n#hd .room-svg { width:100%; display:block; }\n#hd .actor { position:absolute; width:14%; aspect-ratio:60/80; transform:translate(-50%,-100%); transition:left .27s linear, top .27s linear; }\n#hd .actor svg { width:100%; height:100%; display:block; overflow:visible; }\n/* walk cycle: one stride per step (the game takes ~0.27s per tile) */\n#hd .actor .leg { transform-box:fill-box; transform-origin:50% 0; }\n#hd .actor.walk .leg.l { animation:stride .27s ease-in-out infinite alternate; }\n#hd .actor.walk .leg.r { animation:stride .27s ease-in-out infinite alternate-reverse; }\n#hd .actor.walk svg { animation:bob-step .27s ease-in-out infinite alternate; }\n@keyframes stride { from { transform:translateY(-6%) rotate(-22deg); } to { transform:translateY(0) rotate(22deg); } }\n@keyframes bob-step { from { transform:translateY(0); } to { transform:translateY(-3%); } }\n#hd .loc { position:absolute; left:4%; top:3%; padding:1cqw 3cqw; font-size:3cqw; border-radius:3cqw; background:rgba(10,18,50,.7); border:.4cqw solid rgba(255,246,220,.25); }\n\n\n#hd .actor .emote { position:absolute; left:50%; top:-8%; transform:translateX(-50%) scale(0); font:400 7cqw 'Lilita One',sans-serif; font-style:normal; color:#fff; background:#e04a5a; border:.6cqw solid var(--ink); border-radius:50%; width:9cqw; height:9cqw; display:grid; place-items:center; transition:transform .12s; }\n#hd .actor.shout .emote { transform:translateX(-50%) scale(1); }\n\n/* page/hd/scenes/splash.css */\n/* studio splash */\n#hd .splash { background:radial-gradient(70% 55% at 50% 42%, #1f3a82 0%, #0b1330 70%, #050a22 100%); animation:sp-out .6s 4.9s ease-in both; }\n@keyframes sp-out { to { opacity:0; } }\n#hd .splash .rays { position:absolute; left:50%; top:38%; width:150cqw; height:150cqw; margin:-75cqw 0 0 -75cqw; opacity:.28;\n  background:repeating-conic-gradient(from 0deg, rgba(255,201,60,.55) 0 6deg, transparent 6deg 24deg); border-radius:50%;\n  -webkit-mask:radial-gradient(circle, #000 0, transparent 62%); mask:radial-gradient(circle, #000 0, transparent 62%); animation:sp-spin 16s linear infinite, sp-in 1s .1s both; }\n@keyframes sp-spin { to { transform:rotate(360deg); } } @keyframes sp-in { from { opacity:0; } }\n#hd .crest { position:absolute; left:50%; top:20%; width:46cqw; margin-left:-23cqw; animation:sp-drop 1s .25s cubic-bezier(.3,1.6,.5,1) both; filter:drop-shadow(0 2cqw 2cqw rgba(0,0,0,.45)); }\n#hd .crest svg { width:100%; display:block; }\n@keyframes sp-drop { 0% { transform:translateY(-80cqw) scale(.8); opacity:0; } 60% { opacity:1; } 100% { transform:none; } }\n#hd .shine { position:absolute; inset:0; border-radius:50%; overflow:hidden; pointer-events:none;\n  background:linear-gradient(105deg, transparent 40%, rgba(255,255,255,.75) 50%, transparent 60%); background-size:250% 100%; animation:sp-shine .9s 1.3s ease-out both; }\n@keyframes sp-shine { from { background-position:150% 0; opacity:1; } to { background-position:-50% 0; opacity:0; } }\n#hd .name { position:absolute; left:0; right:0; top:60%; text-align:center; font:11.5cqw/1 'Lilita One','Fredoka',sans-serif; letter-spacing:.6cqw; white-space:nowrap; }\n#hd .ltr { display:inline-block; color:var(--gold); -webkit-text-stroke:.9cqw var(--ink); paint-order:stroke fill; text-shadow:0 1cqw 0 #b84a12;\n  opacity:0; animation:sp-rise .6s calc(1.5s + var(--i) * .07s) cubic-bezier(.2,1.5,.5,1) both; }\n@keyframes sp-rise { from { opacity:0; transform:translateY(8cqw) scale(.6); } to { opacity:1; transform:none; } }\n#hd .sp { display:inline-block; width:3.6cqw; }\n#hd .presents { position:absolute; left:0; right:0; top:74%; text-align:center; font:600 5cqw/1 'Fredoka',sans-serif; letter-spacing:1.6cqw; color:var(--cream); }\n#hd .pl { display:inline-block; opacity:0; animation:sp-fade .5s calc(2.9s + var(--i) * .08s) both; }\n@keyframes sp-fade { from { opacity:0; transform:translateY(2cqw); } to { opacity:.9; transform:none; } }\n#hd .spark { position:absolute; width:1.6cqw; height:1.6cqw; background:#fff6dc; border-radius:50%; box-shadow:0 0 2cqw .8cqw rgba(255,201,60,.8);\n  left:calc(12cqw + var(--i) * 8.2cqw); top:calc(24cqw + (var(--i) % 4) * 22cqw); opacity:0; animation:sp-twinkle 1.6s calc(1.8s + var(--i) * .25s) ease-in-out infinite; }\n@keyframes sp-twinkle { 0%,100% { opacity:0; transform:scale(.3); } 50% { opacity:1; transform:scale(1); } }\n\n/* page/hd/scenes/title.css */\n/* title */\n#hd .logo { position:absolute; left:5%; right:5%; top:4%; filter:drop-shadow(0 1.4cqw 0 rgba(0,0,0,.25)); animation:bob 4.5s ease-in-out infinite; }\n#hd .logo .logo-svg { width:100%; display:block; }\n#hd .logo.small { left:3%; right:auto; width:52%; top:3%; animation:none; }\n@keyframes bob { 0%,100%{transform:translateY(0)} 50%{transform:translateY(-1.2cqw)} }\n#hd .trio { position:absolute; left:0; right:0; bottom:9%; height:36%; }\n#hd .mon { position:absolute; bottom:0; animation:hop 2.8s ease-in-out infinite; }\n#hd .mon svg { width:100%; height:100%; display:block; }\n#hd .m1 { left:10%; width:25%; animation-delay:.2s } #hd .m2 { left:37%; width:27%; bottom:2%; animation-delay:.9s } #hd .m3 { left:66%; width:25%; animation-delay:1.5s }\n@keyframes hop { 0%,100%{transform:translateY(0)} 45%{transform:translateY(-3cqw)} 60%{transform:translateY(0) scale(1.02,.97)} }\n#hd .press { position:absolute; left:0; right:0; bottom:3.2%; text-align:center; font-weight:700; font-size:4.6cqw; letter-spacing:.5cqw;\n  color:var(--cream); text-shadow:0 0 1.6cqw rgba(255,201,60,.8), 0 .5cqw 0 var(--ink); animation:blink 1.4s ease-in-out infinite; }\n@keyframes blink { 0%,100%{opacity:1} 50%{opacity:.25} }\n#hd .fly { position:absolute; width:.9cqw; height:.9cqw; border-radius:50%; background:#ffe98a; box-shadow:0 0 1.6cqw .6cqw rgba(255,233,138,.7); animation:float 6s ease-in-out infinite; }\n@keyframes float { 0%,100%{transform:translate(0,0);opacity:.2} 50%{transform:translate(3cqw,-5cqw);opacity:1} }\n\n\n/* page/hd/scenes/world.css */\n// Outdoor scene styles.\n/* outdoor world */\n#hd .world { background:#2f9b4a; }\n#hd .world-map { position:absolute; left:0; top:0; transition:transform .27s linear; will-change:transform; }\n#hd .world-svg { width:100%; display:block; }\n#hd .world .loc { z-index:2; }\n\n/* page/hd/core/base.css */\n/* Buddymon HD layer. Sized in cqw so it scales with the game screen. */\n:root { --ink:#0b1730; --gold:#ffc93c; --gold2:#f08a14; --cream:#fff6dc; --navy:#10204f; --teal:#3de0c4; --coral:#ff6b5e; }\n\n#hd { position:absolute; inset:0; container-type:size; overflow:hidden; border-radius:6px; display:block;\n  font-family:'Fredoka',system-ui,sans-serif; color:var(--cream); background:#050a22; user-select:none; pointer-events:none; }\n#hd .scene { position:absolute; inset:0; overflow:hidden; }\n#hd .sky, #hd .sky-svg { position:absolute; inset:0; width:100%; height:100%; }\n#hd .sky.dim { filter:brightness(.55) saturate(.9); }\n#hd .sky.warm { background:radial-gradient(120% 90% at 50% 100%, #ffb76b 0%, #f08a5a 38%, #7a4a9c 78%, #2b2a6b 100%); }\n#hd .star { animation:twinkle 3.6s ease-in-out infinite; }\n@keyframes twinkle { 0%,100%{opacity:.25} 50%{opacity:1} }\n#hd .clouds { animation:drift 40s linear infinite alternate; }\n@keyframes drift { to { transform:translateX(120px); } }\n\n\n@media (prefers-reduced-motion: reduce) { #hd *, #hd *::before { animation:none !important; transition:none !important; } }\n\n/* page/style.css */\n/* App shell, tuned for a phone (target: Pixel 9, 412x924). Rules: docs/UI.md */\n:root { color-scheme: dark; --bg:#0b1022; --panel:#151c3a; --btn:#222b52; --fg:#eef1ff; --accent:#ffc93c; --ink:#0b1730; }\n* { box-sizing:border-box; -webkit-tap-highlight-color:transparent; }\nhtml, body { height:100%; margin:0; }\nbody { background:var(--bg); color:var(--fg); font:16px 'Fredoka',system-ui,sans-serif; display:flex; justify-content:center; overscroll-behavior:none; }\nmain { width:100%; max-width:480px; height:100dvh; display:flex; flex-direction:column; gap:8px;\n  padding:max(8px, env(safe-area-inset-top)) 8px max(8px, env(safe-area-inset-bottom)); }\n\n#stage { position:relative; flex:1 1 0; min-height:0; display:grid; place-items:center; overflow:hidden; border-radius:16px;\n  background:radial-gradient(90% 70% at 50% 40%, #243a78, #0b1022); }\n#start { position:absolute; inset:0; z-index:2; display:flex; align-items:center; justify-content:center; background:#0b1022; }\n#start[hidden] { display:none; }\n\nbutton { min-height:48px; padding:0 18px; font:inherit; font-weight:600; color:var(--fg); background:var(--btn); border:1px solid #3a4680; border-radius:14px; }\nbutton:active { background:var(--accent); color:var(--ink); }\nbutton:disabled { opacity:.4; }\n\n/* touch pad: ~244px tall, every target >= 48px */\n#pad { flex:none; height:244px; position:relative; touch-action:none; user-select:none; -webkit-user-select:none; -webkit-touch-callout:none; }\n#pad[hidden], body.gestures #pad { display:none; }\nbody.gestures #stage { touch-action:none; user-select:none; -webkit-user-select:none; }\n#dpad { position:absolute; left:6px; top:36px; width:172px; height:172px; border-radius:50%; background:var(--panel); border:2px solid #3a4680; }\n#dpad i { position:absolute; width:0; height:0; border:14px solid transparent; opacity:.55; }\n#dpad .u { left:58px; top:8px; border-bottom:20px solid var(--fg); border-top:0; }\n#dpad .d { left:58px; bottom:8px; border-top:20px solid var(--fg); border-bottom:0; }\n#dpad .l { top:58px; left:8px; border-right:20px solid var(--fg); border-left:0; }\n#dpad .r { top:58px; right:8px; border-left:20px solid var(--fg); border-right:0; }\n#dpad.UP .u, #dpad.DOWN .d, #dpad.LEFT .l, #dpad.RIGHT .r { opacity:1; filter:drop-shadow(0 0 6px var(--accent)); }\n#pad .ab button { position:absolute; width:84px; height:84px; border-radius:50%; font-size:26px; font-weight:700; }\n#pad .ab [data-key=A] { right:8px; top:48px; } #pad .ab [data-key=B] { right:104px; top:98px; }\n#pad .center { position:absolute; left:50%; bottom:2px; transform:translateX(-50%); display:flex; gap:10px; }\n#pad .center button { min-width:92px; height:48px; border-radius:24px; font-size:15px; }\n#pad button.down { background:var(--accent); color:var(--ink); }\n\n#cloud { flex:none; display:flex; gap:8px; align-items:center; }\n#status { flex:1; min-width:0; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; opacity:.75; font-size:14px; }\n#cloud button { min-height:44px; padding:0 14px; font-size:14px; }\n.hint { display:none; margin:0; opacity:.6; font-size:13px; text-align:center; }\n@media (hover:hover) and (pointer:fine) { #pad { display:none !important; } .hint { display:block; } main { height:min(100dvh, 900px); } }\n\ndialog#account { width:min(92vw,380px); padding:20px; color:var(--fg); background:var(--panel); border:1px solid #3a4680; border-radius:18px; }\ndialog#account::backdrop { background:#000b; }\n#account h2 { margin:0 0 4px; } #account p { margin:6px 0 12px; font-size:14px; opacity:.8; }\n#account input { width:100%; min-height:48px; margin-bottom:10px; padding:0 14px; font:inherit; color:var(--fg); background:var(--bg); border:1px solid #3a4680; border-radius:12px; }\n#account .row { display:flex; gap:8px; } #account .row button { flex:1; padding:0 8px; } #account form > button, #acct-logout { width:100%; margin-top:6px; }\n#acct-msg { min-height:1.2em; color:var(--accent); }\n","/manifest.json":"{\n  \"name\": \"Buddymon Gold\",\n  \"short_name\": \"Buddymon\",\n  \"description\": \"Catch, train and battle with buddymon. Plays offline once installed.\",\n  \"start_url\": \"/\",\n  \"scope\": \"/\",\n  \"display\": \"standalone\",\n  \"orientation\": \"portrait\",\n  \"background_color\": \"#0b1022\",\n  \"theme_color\": \"#0b1022\",\n  \"icons\": [\n    { \"src\": \"/icon-192.png\", \"sizes\": \"192x192\", \"type\": \"image/png\", \"purpose\": \"any\" },\n    { \"src\": \"/icon-512.png\", \"sizes\": \"512x512\", \"type\": \"image/png\", \"purpose\": \"any\" },\n    { \"src\": \"/maskable-512.png\", \"sizes\": \"512x512\", \"type\": \"image/png\", \"purpose\": \"maskable\" }\n  ]\n}\n","/icon-192.png":"","/icon-512.png":"","/maskable-512.png":"","/sw.js":"// Service worker: keeps the game shell (page, scripts, icons) so Buddymon Gold opens and plays offline once installed.\n// build.js replaces a1f9b19dea with a hash of the shell, so a new worker.js refreshes the cache. Saves (/api/*) always go to the network.\nconst VERSION = \"__VERSION__\";\nconst SHELL = [\"/\", \"/app.js\", \"/style.css\", \"/manifest.json\", \"/icon-192.png\", \"/icon-512.png\"];\n\nself.addEventListener(\"install\", (e) => {\n  e.waitUntil(caches.open(VERSION).then((c) => c.addAll(SHELL)).then(() => self.skipWaiting()));\n});\nself.addEventListener(\"activate\", (e) => {\n  e.waitUntil(caches.keys().then((keys) => Promise.all(keys.filter((k) => k !== VERSION).map((k) => caches.delete(k)))).then(() => self.clients.claim()));\n});\nself.addEventListener(\"fetch\", (e) => {\n  const url = new URL(e.request.url);\n  if (e.request.method !== \"GET\" || url.pathname.startsWith(\"/api/\")) return;\n  // Fonts come from Google: keep what we have and refresh it in the background. Everything else: the cached shell first.\n  e.respondWith(caches.open(VERSION).then(async (cache) => {\n    const hit = await cache.match(e.request, { ignoreSearch: true });\n    const fresh = fetch(e.request).then((res) => { if (res.ok && (url.origin !== location.origin)) cache.put(e.request, res.clone()); return res; }).catch(() => hit);\n    return hit || fresh;\n  }));\n});\n"};

// Cloudflare Worker: serves the game page (embedded by build.js) and stores each player's save in KV.
//
//   GET    /api/save         -> the save JSON, 404 if none
//   PUT    /api/save         -> store the save JSON (max 64 KB)
//   DELETE /api/save
//   GET    /api/me           -> { code, username }   username is null for guests
//   POST   /api/register     -> { username }   {username, password}; the account keeps the guest's saves
//   POST   /api/login        -> { username }   {username, password}; switches to the account's saves
//   POST   /api/logout       -> {}             back to a fresh guest
//
// A player is identified by a random 128-bit code kept in an HttpOnly cookie, so playing needs no account.
// An account is just a username + password that points at one such code, so it works from any device.

const SAVE_MAX = 64 * 1024;
const COOKIE = "player";
const CODE_RE = /^[0-9a-f]{32}$/;
const USER_RE = /^[a-z0-9_]{3,20}$/;

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    if (url.pathname.startsWith("/api/")) return handleApi(request, env, url);
    return serveEmbedded(url);
  },
};

async function handleApi(request, env, url) {
  const cookies = parseCookies(request.headers.get("Cookie"));
  let code = CODE_RE.test(cookies[COOKIE] || "") ? cookies[COOKIE] : null;
  const headers = new Headers();

  if (url.pathname === "/api/me") {
    if (!code) code = newCode();
    setCookie(headers, code);
    return json({ code, username: await env.SAVES.get(`acct:${code}`) }, 200, headers);
  }

  if (request.method === "POST" && /^\/api\/(register|login|logout)$/.test(url.pathname)) {
    const action = url.pathname.slice(5);
    if (action === "logout") {
      setCookie(headers, newCode());
      return json({}, 200, headers);
    }
    const body = await request.json().catch(() => ({}));
    const username = String(body.username || "").trim().toLowerCase();
    const password = String(body.password || "");
    if (!USER_RE.test(username)) return json({ error: "Username: 3-20 letters, numbers or _" }, 400);
    const record = JSON.parse((await env.SAVES.get(`user:${username}`)) || "null");
    if (action === "login") {
      if (!record || !(await passwordOk(password, record))) return json({ error: "Wrong username or password" }, 401);
      setCookie(headers, record.code);
      return json({ username }, 200, headers);
    }
    if (password.length < 6) return json({ error: "Password needs at least 6 characters" }, 400);
    if (record) return json({ error: "That username is taken" }, 409);
    if (code && (await env.SAVES.get(`acct:${code}`))) return json({ error: "Already signed in" }, 409);
    code ||= newCode();
    const salt = newCode();
    await env.SAVES.put(`user:${username}`, JSON.stringify({ salt, hash: await hashPassword(password, salt), code }));
    await env.SAVES.put(`acct:${code}`, username);
    setCookie(headers, code);
    return json({ username }, 200, headers);
  }

  if (url.pathname !== "/api/save") return json({ error: "Not found" }, 404);
  if (!code) return json({ error: "No player; call /api/me first" }, 401);
  const key = `save:${code}`;

  switch (request.method) {
    case "GET": {
      const data = await env.SAVES.get(key);
      if (!data) return json({ error: "No save" }, 404);
      return new Response(data, { headers: { "Content-Type": "application/json", "Cache-Control": "no-store" } });
    }
    case "PUT": {
      const data = await request.text();
      if (data.length > SAVE_MAX) return json({ error: "Save too large" }, 413);
      try { JSON.parse(data); } catch { return json({ error: "Bad save" }, 400); }
      await env.SAVES.put(key, data);
      return json({ ok: true });
    }
    case "DELETE":
      await env.SAVES.delete(key);
      return json({ ok: true });
    default:
      return json({ error: "Method not allowed" }, 405);
  }
}

async function hashPassword(password, salt) {
  const key = await crypto.subtle.importKey("raw", new TextEncoder().encode(password), "PBKDF2", false, ["deriveBits"]);
  const bits = await crypto.subtle.deriveBits({ name: "PBKDF2", hash: "SHA-256", salt: new TextEncoder().encode(salt), iterations: 100000 }, key, 256);
  return [...new Uint8Array(bits)].map((b) => b.toString(16).padStart(2, "0")).join("");
}

async function passwordOk(password, record) {
  return (await hashPassword(password, record.salt)) === record.hash;
}

function newCode() {
  const bytes = crypto.getRandomValues(new Uint8Array(16));
  return [...bytes].map((b) => b.toString(16).padStart(2, "0")).join("");
}

function setCookie(headers, code) {
  headers.append(
    "Set-Cookie",
    `${COOKIE}=${code}; Path=/; Max-Age=31536000; HttpOnly; Secure; SameSite=Strict`
  );
}

function parseCookies(header) {
  const out = {};
  for (const part of (header || "").split(";")) {
    const i = part.indexOf("=");
    if (i > 0) out[part.slice(0, i).trim()] = part.slice(i + 1).trim();
  }
  return out;
}

function json(body, status = 200, headers = new Headers()) {
  headers.set("Content-Type", "application/json");
  headers.set("Cache-Control", "no-store");
  return new Response(JSON.stringify(body), { status, headers });
}

// --- embedded page ----------------------------------------------------------
// build.js prepends `const EMBEDDED = { "/index.html": "...", ... }` (text files as strings, PNG icons as base64).

const TYPES = {
  html: "text/html; charset=utf-8",
  js: "text/javascript; charset=utf-8",
  css: "text/css; charset=utf-8",
  json: "application/manifest+json",
  png: "image/png",
};

function serveEmbedded(url) {
  const path = url.pathname === "/" ? "/index.html" : url.pathname;
  let body = EMBEDDED[path];
  if (body === undefined) return new Response("Not found", { status: 404 });
  if (path.endsWith(".png")) body = Uint8Array.from(atob(body), (c) => c.charCodeAt(0)); // images are embedded as base64
  return new Response(body, { headers: { "Content-Type": TYPES[path.split(".").pop()], "Cache-Control": "no-cache" } });
}
